window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0095", [{"word":"camouflaged","ipa_uk":"/ˈkæməflɑːʒd/","ipa_us":"/ˌkæməˈflɑːʒd/","definition_zh":"伪装的；保护色的；隐蔽的","definition_en":"made to blend into the surroundings so that it is hard to see or recognise","core_image":"一只停在树皮上的蛾，翅上的斑纹与树皮纹理严丝合缝","scene":"雨后的林地，一只蛾停在长满苔藓的树干上，翅上的纹路与树皮几乎一致。The moth is camouflaged against the mossy bark.","sceneCN":"这里 camouflaged 指「颜色或斑纹与背景一致，使物体难以被发现」（第 1 个义项：外观与周围环境相合而隐藏起来）；句意为这只蛾贴在长满苔藓的树皮上，因与背景同色而不易被看见。图中可辨识物件：蛾、苔藓树皮、翅面斑纹。","pos":[{"tag":"adj.","zh":"伪装的；保护色的；隐蔽的（常作表语或前置定语）"},{"tag":"v.","zh":"camouflage 的过去式与过去分词：把……伪装起来"}],"collocations":[{"phrase":"heavily camouflaged","zh":"伪装得很严密的"},{"phrase":"camouflaged vehicle","zh":"伪装车辆"},{"phrase":"camouflaged position","zh":"伪装阵地"},{"phrase":"camouflaged uniform","zh":"迷彩制服"},{"phrase":"well camouflaged","zh":"伪装得当的"},{"phrase":"camouflaged nest","zh":"伪装巢"}],"forms":[{"label":"原级（分词形容词）","form":"camouflaged"},{"label":"比较级","form":"more camouflaged"},{"label":"最高级","form":"most camouflaged"},{"label":"动词原形","form":"camouflage"},{"label":"三单（he/she/it）","form":"camouflages"},{"label":"过去式","form":"camouflaged"},{"label":"过去分词","form":"camouflaged"},{"label":"现在分词","form":"camouflaging"},{"label":"名词（伪装）","form":"camouflage"},{"label":"名词（施动者）","form":"camoufleur"}],"derivatives":[{"word":"camouflage","pos":"n./v.","zh":"伪装；把……伪装起来"},{"word":"camoufleur","pos":"n.","zh":"伪装设计者；伪装技师"},{"word":"camouflage pattern","pos":"n.","zh":"迷彩图案"},{"word":"camouflage net","pos":"n.","zh":"伪装网"}],"senses":[{"no":"01","title":"Blend into natural surroundings","titleCN":"与自然环境融为一体","definition":"having colours or patterns that match the background so that an animal is hard to detect","definitionCN":"颜色或斑纹与背景一致，使动物难以被发现","example":"The moth is camouflaged against the mossy bark.","exampleCN":"这只蛾贴在长满苔藓的树皮上，与背景融为一体。","why":"The ending -ed states the result of camouflage: the surface has been made to copy what lies behind it.","whyCN":"词尾 -ed 表示伪装的结果：表面已经被做成与背后的东西相似。"},{"no":"02","title":"Conceal military equipment","titleCN":"掩蔽军事装备","definition":"covered or painted so that troops, vehicles or positions cannot be seen from a distance or from the air","definitionCN":"用网、树枝或涂料遮盖，使部队、车辆或阵地无法从远处或空中被看见","example":"The artillery battery was camouflaged with netting and cut branches.","exampleCN":"炮兵阵地用伪装网和砍下的树枝掩蔽起来。","why":"Modern camouflage began as a military problem: artillery and aircraft made any visible target fatal, so hiding shape and colour became a tactic.","whyCN":"现代伪装最初是军事问题：火炮与飞机让任何暴露的目标都变得致命，于是隐藏形状与颜色成了一种战术。"},{"no":"03","title":"Disguise an object as another kind","titleCN":"把物件伪装成别的东西","definition":"made to look like something ordinary so that observers do not recognise it for what it is","definitionCN":"把物件做成普通事物的样子，使观察者认不出它的本来面目","example":"The truck was camouflaged to look like a delivery van.","exampleCN":"那辆卡车被伪装成一辆送货车。","why":"Once hiding by appearance was established, disguising a whole object as a different object was a short practical step.","whyCN":"一旦按外观隐藏的思路确立，把整个物件伪装成另一种物件只是顺理成章的实用一步。"},{"no":"04","title":"Mask an intention or feeling","titleCN":"掩饰真实意图或情绪","definition":"used of words, behaviour or expressions that hide what someone really means or feels","definitionCN":"形容言辞、行为或表情掩盖真实意思或感受","example":"His polite phrasing camouflaged a blunt refusal.","exampleCN":"他客气的措辞掩饰了一个生硬的拒绝。","why":"What works for surfaces in war also works for speech: a friendly outer layer can cover a hostile content.","whyCN":"战时的表面伪装同样适用于言语：友善的外层可以遮住敌对的内容。"},{"no":"05","title":"Wearing camouflage-patterned gear","titleCN":"穿着迷彩图案的衣物或装备","definition":"made of fabric or material printed with a camouflage pattern","definitionCN":"由印有迷彩图案的布料或材料制成","example":"Soldiers in camouflaged jackets moved along the ridge.","exampleCN":"身穿迷彩夹克的士兵沿着山脊移动。","why":"The pattern took its name from the noun, so anything printed with it is described by the same participle.","whyCN":"这种图案沿用了名词 camouflage 的名称，因此印有该图案的物品也用同一个分词来形容。"},{"no":"06","title":"Shield eggs or young by matching the nest","titleCN":"以巢穴配色护住卵或幼体","definition":"used of eggs, nests or young whose appearance matches the ground so that predators overlook them","definitionCN":"形容卵、巢或幼体外观与地面一致，使捕食者忽略它们","example":"The camouflaged eggs survive better on speckled gravel than on plain sand.","exampleCN":"这些伪装色的卵在斑驳的砾石上比在纯色沙地上存活得更好。","why":"Protective resemblance extends from the parent's body to the clutch, so the same adjective covers eggs and nests.","whyCN":"保护性相似从亲本体表延伸到整窝卵，因此同一个形容词也用于卵与巢。"},{"no":"07","title":"Hide an installation in plain sight","titleCN":"让设施隐身于寻常景观","definition":"used of buildings or sites designed to look ordinary so that they escape notice","definitionCN":"形容建筑或场地被设计成寻常样子，从而不引起注意","example":"The office block was camouflaged as a warehouse to hide the laboratory inside.","exampleCN":"那栋办公楼被伪装成仓库，以遮住里面的实验室。","why":"Military concealment scaled up to whole sites: a building can wear an ordinary face.","whyCN":"军事隐蔽放大到整个场地：一栋建筑可以戴上一张寻常的脸。"},{"no":"08","title":"Disguise network traffic or signals","titleCN":"伪装网络流量或信号","definition":"used of data or signals altered to look like ordinary traffic so that monitoring does not flag them","definitionCN":"形容数据或信号被改造成普通流量的样子，使监测不予标记","example":"The messages were camouflaged as routine software updates.","exampleCN":"这些信息被伪装成常规的软件更新。","why":"The newest extension keeps the same logic: hide the real content inside an expected pattern.","whyCN":"最新的引申保持同一逻辑：把真实内容藏进一个可预期的模式里。"}],"etymology":{"intro":{"en":"Camouflaged is the past participle of camouflage, a word English borrowed from French military slang during the First World War; French took it from Italian. No Latin etymon can be recovered, so the Latin list is empty.","cn":"camouflaged 是 camouflage 的过去分词；camouflage 是第一次世界大战期间英语从法语军事俚语借入的词，法语又取自意大利语。无法追溯到可靠的拉丁词源，故拉丁条目留空。"},"items":[{"era":"ITALIAN CAMUFFARE","en":"Italian camuffare 'to disguise, to trick' is the earliest traceable form, recorded in the nineteenth century.","cn":"意大利语 camuffare「伪装、欺骗」是最早可追溯的形式，见于 19 世纪。"},{"era":"FRENCH SLANG","en":"French slang camoufler 'to disguise' entered military speech around 1915, apparently from the Italian verb.","cn":"法语俚语 camoufler「伪装」约在 1915 年进入军人用语，一般认为来自上述意大利语动词。"},{"era":"WORLD WAR I","en":"English adopted camouflage in 1917, when the concealment of guns and aircraft became an official concern; the participle camouflaged appeared at the same time.","cn":"英语在 1917 年借入 camouflage，当时火炮与飞机的隐蔽成为官方要务；分词 camouflaged 同时出现。"},{"era":"THE -AGE NOUN","en":"The French noun camouflage used -age, a suffix of action or result, and English kept the noun unchanged.","cn":"法语名词 camouflage 使用表示行为或结果的后缀 -age，英语把这个名词原样保留。"},{"era":"FIGURATIVE SPREAD","en":"By the mid twentieth century camouflaged extended from bodies and vehicles to intentions, institutions and transmitted signals.","cn":"到 20 世纪中叶，camouflaged 已从身体与车辆扩展到意图、机构与传输信号。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root): the deeper origin of Italian camuffare is disputed; one hypothesis links it to muffare 'to muffle', another to a dialect word for a mask, and no Latin etymon can be established. Only the first printed dates are approximate.","cn":"来源不确定（词根）：意大利语 camuffare 的更深来源有争议，一说与 muffare「捂住」有关，一说与某种方言中表示面具的词有关，无法确立拉丁词源；仅首见年代为约数。"}]},"similar":{"note":{"en":"Group one holds the base form and its immediate derivatives, which are easy to confuse with the participle; group two holds near synonyms that differ in how openly or how completely the hiding is done.","cn":"第一组是本词原形及其直接派生形式，容易与这个分词混用；第二组是近义词，区别在于隐藏的公开程度与彻底程度。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"camouflage","ipa":"/ˈkæməflɑːʒ/","tag":"base noun and verb","definition":"The verb or the thing itself, not the resulting state; camouflaged describes something after the act has been done.","definitionCN":"指动词或伪装这一事物本身，而非结果状态；camouflaged 描述行为完成后的样子。"},{"word":"camouflaging","ipa":"/ˈkæməflɑːʒɪŋ/","tag":"ongoing action","definition":"The present participle, naming the act while it happens; camouflaged names the finished condition.","definitionCN":"现在分词，指正在进行的动作；camouflaged 指完成后的状态。"},{"word":"camoufleur","ipa":"/ˌkæməˈflɜː/","tag":"person, not state","definition":"A person who designs camouflage; it is an agent noun and never describes the hidden object.","definitionCN":"指设计伪装的人；是施动名词，从不形容被隐藏的物件。"},{"word":"camouflage pattern","ipa":"/ˈkæməflɑːʒ ˈpætn/","tag":"the design","definition":"The printed design itself; a camouflaged jacket is a jacket made with that design.","definitionCN":"指图案本身；camouflaged jacket 指用该图案制成的夹克。"}]},{"heading":"NEAR MEANING","entries":[{"word":"disguised","ipa":"/dɪsˈɡaɪzd/","tag":"altered identity","definition":"Made to look like another person or thing; it stresses a false identity more than a merge with the background.","definitionCN":"指被改扮成另一个人或物；更强调假身份，而非与背景融合。"},{"word":"concealed","ipa":"/kənˈsiːld/","tag":"kept from view","definition":"Deliberately kept out of sight; it says nothing about matching colours or patterns.","definitionCN":"指被有意藏起来看不见；不涉及颜色或斑纹是否相合。"},{"word":"cloaked","ipa":"/ˈkləʊkt/","tag":"covered over","definition":"Covered by something that hides the surface; the emphasis falls on a covering layer rather than on resemblance.","definitionCN":"指被某物覆盖而遮住表面；重点在覆盖层，而不在相似。"},{"word":"blended","ipa":"/ˈblendɪd/","tag":"merged softly","definition":"Merged into the surroundings without sharp edges; it describes visual mixing, not a deliberate military act.","definitionCN":"指与周围柔和地融在一起、没有明显边界；描述视觉混合，不含刻意的军事行为。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real French and Italian lineage, the real derivatives, and the fixed phrases that military writers actually use.","cn":"正常联想：真实的法语与意大利语来源、真实的派生词，以及军事写作中实际使用的固定搭配。"},"normal":[{"en":"camouflage plus -ed: the state of having been disguised.","cn":"camouflage 加 -ed：已经伪装好的状态。"},{"en":"The family runs camouflage, camouflaged, camouflaging, camoufleur.","cn":"同族词包括 camouflage、camouflaged、camouflaging、camoufleur。"},{"en":"Fixed phrases: heavily camouflaged, camouflaged vehicle, camouflaged position.","cn":"固定搭配有 heavily camouflaged、camouflaged vehicle、camouflaged position。"},{"en":"The word entered English in 1917, from French military slang.","cn":"这个词 1917 年从法语军事俚语进入英语。"},{"en":"Three scales to remember: an animal's skin, a vehicle's paint, a building's facade.","cn":"可按三个尺度记忆：动物的皮肤、车辆的漆面、建筑的外立面。"}],"abstract":[{"en":"Picture a moth whose wings repeat the bark grain so exactly that the eye slides off it.","cn":"想象一只蛾，翅膀把树皮纹理重复得如此精确，目光会从它身上滑过去。"},{"en":"Picture a tank wearing a coat of branches and reading as a hedge.","cn":"想象一辆坦克披着树枝，看上去像一道树篱。"},{"en":"Picture a polite sentence standing as a painted screen in front of a refusal.","cn":"想象一句客气话像一块彩绘屏风立在拒绝之前。"}]},"examples":[{"en":"The nestlings are camouflaged by their down, which matches the lichen.","cn":"雏鸟的绒羽与地衣同色，因此被伪装起来。"},{"en":"Every vehicle in the convoy was camouflaged before dawn.","cn":"车队里的每辆车都在天亮前完成了伪装。"},{"en":"The report's calm tone camouflaged a serious warning.","cn":"报告平静的语调掩盖了一个严重警告。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「camouflage（伪装）+ -ed」——被伪装起来的 → 伪装色的；隐蔽的","word":"camouflaged"},"root":"意大利语 camuffare「伪装、欺骗」（19 世纪）→ 法语俚语 camoufler → 英语 camouflage；词根来源不确定，无可考的拉丁同族词。","sensesIntro":{"en":"Eight senses follow one act of hiding: an animal's surface copies its background, then vehicles, objects, speech, clothing, nests, buildings and finally data wear the same disguise.","cn":"八个义项沿同一种隐藏行为展开：动物体表复制背景，随后车辆、物件、言语、衣物、巢、建筑，直到数据，都披上同一层伪装。"},"semanticMap":{"core":{"en":"CORE IMAGE: a moth whose wing pattern repeats the bark so closely that the eye cannot separate them.","cn":"核心意象：一只蛾的翅纹把树皮重复得如此紧密，眼睛无法把它们分开。"},"chain":["COPY SURFACE","MATCH BACKGROUND","HIDE SHAPE","FOOL THE EYE","CONCEAL PURPOSE","DISGUISE THE SYSTEM"],"branches":[{"senses":"01 · 06","en":"NATURAL RESEMBLANCE: bodies and clutches copy the ground for survival.","cn":"自然相似：身体与整窝卵复制地面以求生存。"},{"senses":"02 · 05","en":"MILITARY DRESS: equipment and uniforms take the pattern as a tactic.","cn":"军事装束：装备与制服把该图案当作战术。"},{"senses":"03","en":"OBJECT DISGUISE: a whole thing is remade as another kind of thing.","cn":"物件伪装：整个物体被改造成另一类物体。"},{"senses":"04","en":"VERBAL MASK: polite wording covers a blunt content.","cn":"言语掩饰：客气的措辞盖住生硬的内容。"},{"senses":"07 · 08","en":"SYSTEMIC COVER: sites and data traffic are hidden inside ordinary appearances.","cn":"系统性掩护：场地与数据流量被藏进寻常外观之中。"}]},"affixes":{"intro":{"en":"The word is a French-derived base with an English participial ending; its parts are a verb stem plus -age and -ed, not a Latin root plus prefix.","cn":"这个词是法语来源的词干加英语分词词尾；其构成为动词词干加 -age 与 -ed，而非拉丁词根加前缀。"},"latinIntro":{"en":"No Latin etymon is recoverable. The line runs from Italian camuffare through French camoufler to English, so the Latin entry list is empty by design.","cn":"无法追溯到拉丁词源。线索从意大利语 camuffare 经法语 camoufler 到英语，因此拉丁条目按规则留空。"},"items":[{"word":"camouflage","structure":"French camoufler + -age (action or result)","meaning":"disguise; to disguise","meaningCN":"伪装；把……伪装起来","example":"Camouflage buys a unit time to move.","exampleCN":"伪装为一个单位争取移动的时间。"},{"word":"camouflaged","structure":"camouflage + -ed (resulting state)","meaning":"made to blend in","meaningCN":"被伪装得与背景相合的","example":"The moth is camouflaged against the bark.","exampleCN":"这只蛾贴在树皮上，与背景相合。"},{"word":"camouflaging","structure":"camouflage + -ing (ongoing action)","meaning":"the act of disguising","meaningCN":"正在进行伪装","example":"They spent the night camouflaging the bridge.","exampleCN":"他们花了一夜时间伪装那座桥。"},{"word":"camoufleur","structure":"French camoufleur (agent noun)","meaning":"one who designs camouflage","meaningCN":"伪装设计者","example":"A camoufleur painted the hangar to match the hillside.","exampleCN":"一位伪装技师把机库漆成与山坡相合的颜色。"},{"word":"camouflage net","structure":"camouflage + net (compound noun)","meaning":"netting used to hide equipment","meaningCN":"用于遮蔽装备的伪装网","example":"The crew draped a camouflage net over the gun.","exampleCN":"炮组把一张伪装网盖在火炮上。"},{"word":"camouflage pattern","structure":"camouflage + pattern (compound noun)","meaning":"a printed design that imitates terrain","meaningCN":"仿照地形印制的图案","example":"The new camouflage pattern mixes four earth tones.","exampleCN":"新的迷彩图案混合了四种土色。"},{"word":"camouflage paint","structure":"camouflage + paint (compound noun)","meaning":"paint that reduces visibility","meaningCN":"降低可见度的伪装涂料","example":"Camouflage paint dulls the shine of metal.","exampleCN":"伪装涂料使金属不再反光。"},{"word":"camouflage jacket","structure":"camouflage + jacket (compound noun)","meaning":"jacket printed with a camouflage design","meaningCN":"印有迷彩图案的夹克","example":"He wore a camouflage jacket in the field.","exampleCN":"他在野外穿了一件迷彩夹克。"},{"word":"camouflage training","structure":"camouflage + training (compound noun)","meaning":"instruction in concealment","meaningCN":"隐蔽技能训练","example":"Camouflage training includes shadow and texture.","exampleCN":"伪装训练包括阴影与纹理的利用。"}],"latinEntries":[]}},{"word":"mimicry","ipa_uk":"/ˈmɪmɪkri/","ipa_us":"/ˈmɪmɪkri/","definition_zh":"模仿；拟态；模仿行为","definition_en":"the act of copying another's appearance, sound or behaviour, or a resemblance that has evolved because it helps survival","core_image":"一只蝴蝶的翅膀上长着与有毒同类几乎一样的警告色斑","scene":"雨林里，一只无毒的蝴蝶长着与有毒近亲相同的斑纹，捕食者因而避开它。In the rainforest, one butterfly's mimicry of a toxic cousin keeps predators away.","sceneCN":"这里 mimicry 指「生物为自保而演化出的相似外观」（第 1 个义项：一个物种模仿另一个物种的形态或色斑，从而获得保护）；句意为雨林中一只无毒蝴蝶模仿有毒近亲的样子，使捕食者避开。图中可辨识物件：翅面斑纹、有毒同类、退开的鸟。","pos":[{"tag":"n.","zh":"拟态；模仿；模仿行为（不可数；指具体事例时可用复数 mimicries）"}],"collocations":[{"phrase":"Batesian mimicry","zh":"贝氏拟态（无毒种模仿有毒种）"},{"phrase":"Müllerian mimicry","zh":"缪氏拟态（多种有毒种共享警告色）"},{"phrase":"protective mimicry","zh":"保护性拟态"},{"phrase":"vocal mimicry","zh":"声音模仿"},{"phrase":"molecular mimicry","zh":"分子拟态"},{"phrase":"mimicry of a model","zh":"对范本的模仿"}],"forms":[{"label":"复数","form":"mimicries"},{"label":"动词（模仿）","form":"mimic"},{"label":"名词（模仿者）","form":"mimic"},{"label":"形容词（拟态的）","form":"mimetic"},{"label":"抽象名词（摹拟）","form":"mimesis"},{"label":"相关名词（摹拟演员）","form":"mime"}],"derivatives":[{"word":"mimic","pos":"v./n.","zh":"模仿；模仿者"},{"word":"mimetic","pos":"adj.","zh":"模仿的；拟态的"},{"word":"mimesis","pos":"n.","zh":"摹拟；再现"},{"word":"mime","pos":"n./v.","zh":"哑剧；摹拟演员"},{"word":"mimicry behavior","pos":"n.","zh":"拟态行为"}],"senses":[{"no":"01","title":"Resemblance evolved for protection","titleCN":"为自保演化出的相似外观","definition":"the close resemblance of one organism to another that gives it an advantage, usually protection from predators","definitionCN":"一种生物与另一种生物高度相似，从而获得优势，通常是免于被捕食","example":"In the rainforest, one butterfly's mimicry of a toxic cousin keeps predators away.","exampleCN":"雨林里，一只无毒蝴蝶模仿有毒近亲，使捕食者避开。","why":"The suffix -ry turns the imitator's act into a named phenomenon; biology then took the word for resemblance that works like a disguise.","whyCN":"后缀 -ry 把模仿者的行为变成一个有名字的现象；生物学随后用这个词指像伪装一样起作用的相似。"},{"no":"02","title":"Copying another person's speech or gestures","titleCN":"模仿他人的言语或动作","definition":"the act of copying how someone speaks, moves or behaves, often for amusement","definitionCN":"复制他人说话、动作或行为的方式，常为逗乐","example":"Her mimicry of the professor's accent made the whole room laugh.","exampleCN":"她模仿教授的口音，让全场笑了起来。","why":"The everyday sense is simply the act of copying; no biological advantage is involved.","whyCN":"日常义就是复制行为本身，不涉及任何生物优势。"},{"no":"03","title":"Mocking imitation","titleCN":"带嘲弄意味的模仿","definition":"imitation intended to ridicule the person copied","definitionCN":"旨在嘲弄被模仿者的模仿","example":"The sketch show's mimicry of the minister was accurate but cruel.","exampleCN":"那个小品节目对部长的模仿准确却刻薄。","why":"Copying can be aimed at ridicule; English already had mockery, and mimicry took part of the same territory.","whyCN":"复制可以用来嘲弄；英语本有 mockery 一词，mimicry 分占了同一片语义地盘。"},{"no":"04","title":"Imitation as a learning route","titleCN":"作为学习途径的模仿","definition":"the copying of sounds or actions by which a learner acquires a skill","definitionCN":"学习者通过复制声音或动作来获得技能","example":"Mimicry of adult speech is how children first practise sounds.","exampleCN":"儿童最初正是靠模仿成人的话语来练习发音。","why":"Learning by copying is the human version of the biological pattern: repeat the model until it fits.","whyCN":"照着学是人类版的生物模式：重复范本，直到吻合。"},{"no":"05","title":"Molecular mimicry","titleCN":"分子拟态","definition":"a resemblance between molecular structures of a pathogen and the host that can misdirect the immune response","definitionCN":"病原体与宿主在分子结构上的相似，会误导免疫反应","example":"Molecular mimicry lets a pathogen's proteins trigger an immune attack on the body's own tissue.","exampleCN":"分子拟态使病原体蛋白引发免疫系统攻击人体自身组织。","why":"At molecular scale the copied feature is an amino-acid sequence, but the protective logic is the same.","whyCN":"在分子尺度上被复制的是氨基酸序列，但自保逻辑相同。"},{"no":"06","title":"Vocal mimicry in birds","titleCN":"鸟类的鸣声模仿","definition":"the reproduction of sounds, including other species' calls or human noises, by a bird","definitionCN":"鸟类复制声音，包括其他物种的鸣叫或人类的声音","example":"Vocal mimicry lets a parrot reproduce a household's telephone ring.","exampleCN":"声音模仿让一只鹦鹉复现家里的电话铃声。","why":"Sound is copied instead of colour, so the word covers acoustic resemblance as well.","whyCN":"被复制的是声音而非颜色，因此这个词也覆盖听觉上的相似。"},{"no":"07","title":"Stage impersonation","titleCN":"舞台上的仿演","definition":"a performance in which an actor reproduces a known person's voice and mannerisms","definitionCN":"演员复现知名人物的嗓音与举止的表演","example":"His mimicry of a tired stationmaster was the hit of the evening.","exampleCN":"他模仿一位疲惫站长的表演成了当晚最受欢迎的节目。","why":"Performance makes copying a craft, and the older sense of mime as an actor's art returns.","whyCN":"表演让复制成为一门技艺，mime 作为演员艺术的旧义也随之回来。"},{"no":"08","title":"Adaptive resemblance in plants or seeds","titleCN":"植物或种子的适应性相似","definition":"a resemblance in plants, seeds or eggs that reduces the chance of being eaten or removed","definitionCN":"植物、种子或卵在外观上的相似，降低被吃掉或被移走的机会","example":"Seed mimicry of pebbles keeps desert seeds from being eaten.","exampleCN":"种子模仿石子，使沙漠中的种子免于被吃掉。","why":"The term spread beyond animals because the same survival logic works for any organism.","whyCN":"这个词扩展到动物之外，因为同一套生存逻辑对任何生物都成立。"}],"etymology":{"intro":{"en":"Mimicry joins Greek mimos 'imitator' to the noun ending -ry. Greek mimesis and Latin mimus belong to the same family; the biological use is a nineteenth-century specialization.","cn":"mimicry 把希腊 mimos「模仿者」与名词后缀 -ry 结合。希腊 mimesis 与拉丁 mimus 同属一族；生物学用法是 19 世纪的特化。"},"items":[{"era":"GREEK MIMOS","en":"Greek mimos meant 'imitator' and also a performer in a mime; it is the source of the whole family.","cn":"希腊 mimos 意为「模仿者」，也指摹拟剧演员；它是整族词的源头。"},{"era":"GREEK MIMESIS","en":"Greek mimesis 'imitation' supplied the abstract noun later borrowed into Latin and modern languages.","cn":"希腊 mimesis「模仿」提供了这个抽象名词，后来被拉丁语与近代语言借入。"},{"era":"LATIN MIMUS","en":"Latin mimus 'mime actor' is a borrowing from Greek rather than an independent Latin root; it passed into French and then English.","cn":"拉丁 mimus「摹拟演员」借自希腊语，并非独立的拉丁词根；它传入法语，再进入英语。"},{"era":"THE SUFFIX -RY","en":"The ending -ry came through French -erie, from Latin -aria, and turns a noun of agent or trade into a noun of practice.","cn":"后缀 -ry 经法语 -erie 来自拉丁 -aria，把表示施动者或行业的名词变成表示实践的名词。"},{"era":"BIOLOGICAL SENSE","en":"The zoological sense is generally dated to the 1850s and was fixed by Henry Walter Bates's 1861 account of Amazonian butterflies.","cn":"动物学义一般认为是 1850 年代出现，并由亨利·沃尔特·贝茨 1861 年对亚马孙蝴蝶的记述固定下来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root): the secure layer is Greek mimos; whether mimos itself is Pre-Greek is disputed, and the first English date of the biological sense is approximate.","cn":"来源不确定（词根）：可靠的一层是希腊 mimos；mimos 本身是否属前希腊语底层的词，存在争议；生物义的首见年代为约数。"}]},"similar":{"note":{"en":"Group one separates the near-identical forms of the same family; group two separates kinds of imitation that differ in purpose or in the channel used.","cn":"第一组区分同一词族中形态相近的形式；第二组区分目的不同或渠道不同的各种模仿。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mimic","ipa":"/ˈmɪmɪk/","tag":"the agent or act","definition":"A person, animal or verb of copying; mimicry is the named practice or the evolved resemblance.","definitionCN":"指模仿者或模仿这一动词；mimicry 指被命名的做法或演化出的相似。"},{"word":"mimetic","ipa":"/mɪˈmetɪk/","tag":"adjective","definition":"The adjective meaning 'imitative'; it describes a quality rather than names the phenomenon.","definitionCN":"意为「模仿的」的形容词，描述性质而不命名现象。"},{"word":"mimesis","ipa":"/mɪˈmiːsɪs/","tag":"abstract imitation","definition":"Imitation as a general aesthetic or biological process; mimicry is the concrete case or strategy.","definitionCN":"指作为普遍审美或生物过程的模仿；mimicry 指具体个案或策略。"},{"word":"mime","ipa":"/maɪm/","tag":"silent performance","definition":"A silent performance art or its performer; mimicry may involve sound and is not restricted to theatre.","definitionCN":"指无声的表演艺术或其表演者；mimicry 可以涉及声音，也不限于戏剧。"}]},{"heading":"NEAR MEANING","entries":[{"word":"imitation","ipa":"/ˌɪmɪˈteɪʃn/","tag":"generic copying","definition":"The broadest word for copying; it carries no claim that the copy brings an advantage.","definitionCN":"表示复制的最宽泛的词，不暗示复制带来优势。"},{"word":"camouflage","ipa":"/ˈkæməflɑːʒ/","tag":"hiding, not resembling a species","definition":"Concealment by matching the background; mimicry copies another organism, which may itself be visible.","definitionCN":"指与背景相合而隐蔽；mimicry 复制的是另一种生物，那种生物本身可能很显眼。"},{"word":"impersonation","ipa":"/ɪmˌpɜːsəˈneɪʃn/","tag":"person-focused","definition":"Copying a particular person's identity for performance or fraud; mimicry can be species-wide and non-human.","definitionCN":"指为表演或行骗而复制某个特定人物的身份；mimicry 可以是整个物种层面，也可以与人类无关。"},{"word":"emulation","ipa":"/ɪˈmjʊleɪʃn/","tag":"striving to equal","definition":"Copying in order to equal or surpass a model; the aim is competition, not disguise.","definitionCN":"指为达到或超越范本而模仿；目的是竞争，而非伪装。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek family, real scientific collocations, and the actual historical sense development.","cn":"正常联想：真实的希腊词族、真实的科学搭配，以及实际的历史语义发展。"},"normal":[{"en":"mimos 'imitator' + -ry 'practice': the practice of copying.","cn":"mimos「模仿者」+ -ry「做法」：复制的做法。"},{"en":"The family runs mimic, mimicry, mimetic, mimesis, mime.","cn":"同族词包括 mimic、mimicry、mimetic、mimesis、mime。"},{"en":"Biology fixes two labels: Batesian and Müllerian mimicry.","cn":"生物学固定了两个标签：贝氏拟态与缪氏拟态。"},{"en":"The word first meant burlesque imitation before it meant animal resemblance.","cn":"这个词先指滑稽模仿，后指动物拟态。"},{"en":"Mimicry can copy colour, sound, shape or molecules.","cn":"拟态可以复制颜色、声音、形状或分子。"}],"abstract":[{"en":"Picture a harmless butterfly wearing a warning label it did not earn.","cn":"想象一只无毒蝴蝶挂着它并未挣来的警告标签。"},{"en":"Picture a child's voice fitting itself into an adult sentence like a hand into a glove.","cn":"想象孩子的声音把自己套进成人的句子，像手伸进手套。"},{"en":"Picture a protein shaped so much like the body's own tissue that the guard cannot tell them apart.","cn":"想象一种蛋白与人体自身组织长得太像，守卫分不出它们。"}]},"examples":[{"en":"Batesian mimicry works only while the toxic model stays common.","cn":"贝氏拟态只有在有毒范本仍常见时才有效。"},{"en":"The bird's mimicry of a hawk's cry clears the feeder in seconds.","cn":"这只鸟模仿鹰啼，几秒内就让喂食器旁空无一鸟。"},{"en":"Molecular mimicry is one route by which infections trigger autoimmune disease.","cn":"分子拟态是感染引发自身免疫病的途径之一。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「mimi（模仿声）+ -ry（行为）」——模仿这件事 → 模仿；拟态","word":"mimicry"},"root":"希腊 mimos「模仿者、摹拟演员」+ 后缀 -ry（经法语 -erie，出自拉丁 -aria）；拉丁 mimus 借自希腊语，并非独立拉丁词根。","sensesIntro":{"en":"Eight senses trace one copy: an organism copies another for protection, then people copy speech, mock, learn, copy molecules, copy calls, perform, and finally plants copy stones.","cn":"八个义项沿着同一种复制展开：生物为自保复制同类，人复制言语、嘲弄、学习、复制分子、复制鸣叫、表演，最后植物复制石子。"},"semanticMap":{"core":{"en":"CORE IMAGE: a harmless butterfly wearing the wing pattern of a poisonous relative.","cn":"核心意象：一只无毒蝴蝶戴着有毒近亲的翅纹。"},"chain":["COPY SHAPE","COPY SOUND","REPEAT A MODEL","FOOL AN OBSERVER","GAIN AN ADVANTAGE","NAME THE PRACTICE"],"branches":[{"senses":"01 · 05 · 08","en":"PROTECTIVE COPY: species, molecules and seeds borrow another's appearance to survive.","cn":"保护性复制：物种、分子与种子借用他者的外观以求生存。"},{"senses":"02 · 04","en":"HUMAN COPY: speech and skills are repeated until they belong to the copier.","cn":"人类复制：言语与技能被重复，直到归复制者所有。"},{"senses":"03","en":"DERISIVE COPY: the copy is aimed at making the model ridiculous.","cn":"嘲弄性复制：复制意在让范本显得可笑。"},{"senses":"06","en":"ACOUSTIC COPY: calls and noises replace colours as the copied feature.","cn":"听觉复制：鸣叫与噪声取代颜色成为被复制的特征。"},{"senses":"07","en":"STAGED COPY: imitation becomes a craft performed for an audience.","cn":"舞台复制：模仿成为面向观众表演的技艺。"}]},"affixes":{"intro":{"en":"Mimicry is a Greek noun stem plus a French-Latin noun ending; the related adjectives and verbs come from the same mimos family.","cn":"mimicry 是希腊语名词词干加法语—拉丁语名词词尾；相关形容词与动词都出自同一 mimos 词族。"},"latinIntro":{"en":"Latin mimus and mimicus are borrowings from Greek, not native Latin roots; they are listed as the route through which the family reached English.","cn":"拉丁 mimus 与 mimicus 借自希腊语，并非本土拉丁词根；列在此处是说明该词族进入英语的路径。"},"items":[{"word":"mimos","structure":"Greek mimos (imitator, mime actor)","meaning":"one who copies","meaningCN":"模仿者","example":"Greek mimos named both the copier and the stage imitator.","exampleCN":"希腊 mimos 既指模仿者，也指舞台上的仿演者。"},{"word":"-ry","structure":"French -erie, from Latin -aria (practice, collective)","meaning":"the practice or class of","meaningCN":"表示做法或一类事物的后缀","example":"The ending turns an agent into a named practice.","exampleCN":"这个后缀把施动者变成一种被命名的做法。"},{"word":"mimic","structure":"Greek mimos + -ic (belonging to)","meaning":"to copy; one who copies","meaningCN":"模仿；模仿者","example":"Children mimic what they hear.","exampleCN":"孩子会模仿听到的话。"},{"word":"mimetic","structure":"Greek mimētikos + -ic","meaning":"imitative","meaningCN":"模仿的；拟态的","example":"Mimetic colouring hides the insect.","exampleCN":"拟态色彩使昆虫隐蔽起来。"},{"word":"mimesis","structure":"Greek mimesis (imitation)","meaning":"imitation as a process","meaningCN":"作为过程的摹拟","example":"Mimesis is the older abstract term.","exampleCN":"mimesis 是更早的抽象术语。"},{"word":"mime","structure":"French mime, from Latin mimus","meaning":"silent performance","meaningCN":"哑剧；摹拟表演","example":"The mime told the story without words.","exampleCN":"那位哑剧演员不用言语讲完了故事。"},{"word":"Batesian mimicry","structure":"Bates + -ian + mimicry","meaning":"a harmless species copying a harmful one","meaningCN":"无毒种模仿有毒种","example":"Batesian mimicry depends on the model being noxious.","exampleCN":"贝氏拟态依赖范本确实有毒。"},{"word":"Müllerian mimicry","structure":"Müller + -ian + mimicry","meaning":"two harmful species sharing a warning pattern","meaningCN":"两种有毒种共享警告色","example":"Müllerian mimicry reinforces one warning signal.","exampleCN":"缪氏拟态强化同一个警告信号。"},{"word":"mimicry behavior","structure":"mimicry + behavior (compound noun)","meaning":"the actions by which copying is carried out","meaningCN":"实施复制的具体行为","example":"The study filmed mimicry behavior in pairs.","exampleCN":"这项研究拍摄了成对个体的拟态行为。"}],"latinEntries":[{"word":"mimus","structure":"mimus, mimi (noun, borrowed from Greek)","meaning":"mime actor; imitator","meaningCN":"摹拟演员；模仿者"},{"word":"mimicus","structure":"mimicus, mimica, mimicum (adjective, from Greek mimikos)","meaning":"imitative; of a mime","meaningCN":"模仿的；摹拟表演的"},{"word":"mimesis","structure":"mimesis (noun, borrowed from Greek)","meaning":"imitation","meaningCN":"模仿；摹拟"}]}},{"word":"mimic","ipa_uk":"/ˈmɪmɪk/","ipa_us":"/ˈmɪmɪk/","definition_zh":"模仿；模仿者；拟态的","definition_en":"to copy the look, sound or behaviour of another, often to amuse or deceive; a person or animal that copies","core_image":"一个人对着镜子学另一个人的口音与手势，动作几乎同步","scene":"孩子们还叫不出这些动作的名字，就已经在学了。Children mimic the gestures of the adults around them long before they can name them.","sceneCN":"这里 mimic 指「模仿他人的动作或举止」（第 2 个义项：通过复制范本的行为来学习或融入）；句意为孩子们还叫不出这些动作的名称，就已经在模仿身边成人的手势。图中可辨识物件：镜子、成人的手势、孩子同步抬起的手。","pos":[{"tag":"vt.","zh":"模仿；学……的样子；酷似（病症、声音等）"},{"tag":"n.","zh":"模仿者；善于模仿的人；拟态动物"},{"tag":"adj.","zh":"模仿的；拟态的（多作定语）"}],"collocations":[{"phrase":"mimic the accent","zh":"模仿口音"},{"phrase":"mimic a voice","zh":"模仿嗓音"},{"phrase":"mimic the symptoms","zh":"（病症）与……症状相似"},{"phrase":"mimic natural processes","zh":"模拟自然过程"},{"phrase":"a gifted mimic","zh":"有天赋的模仿者"},{"phrase":"mimic the behaviour of","zh":"模拟……的行为"}],"forms":[{"label":"原形","form":"mimic"},{"label":"三单（he/she/it）","form":"mimics"},{"label":"过去式","form":"mimicked"},{"label":"过去分词","form":"mimicked"},{"label":"现在分词","form":"mimicking"},{"label":"名词复数","form":"mimics"},{"label":"形容词（拟态的）","form":"mimetic"},{"label":"名词（拟态）","form":"mimicry"}],"derivatives":[{"word":"mimicry","pos":"n.","zh":"拟态；模仿"},{"word":"mimetic","pos":"adj.","zh":"模仿的；拟态的"},{"word":"mimicked","pos":"adj.","zh":"被模仿的；仿制的"},{"word":"mimicker","pos":"n.","zh":"模仿者"},{"word":"mimicry behavior","pos":"n.","zh":"拟态行为"}],"senses":[{"no":"01","title":"Imitate to entertain","titleCN":"为逗乐而模仿","definition":"to copy someone's voice, accent or mannerisms in order to amuse others","definitionCN":"复制他人的嗓音、口音或举止以逗乐旁人","example":"He can mimic the lecturer so well that the class bursts out laughing.","exampleCN":"他把讲师模仿得惟妙惟肖，全班都笑了出来。","why":"The verb keeps the oldest stage sense of mimos: a performer reproducing another's manner.","whyCN":"这个动词保留了 mimos 最古老的舞台义：表演者复制他人的举止。"},{"no":"02","title":"Copy a model in order to learn","titleCN":"为学习而照着做","definition":"to reproduce an action or sound as a way of acquiring the skill","definitionCN":"复制动作或声音，以此获得该项技能","example":"Children mimic the gestures of the adults around them long before they can name them.","exampleCN":"孩子们还叫不出这些动作的名称，就已经在模仿身边成人的手势。","why":"Copying is the cheapest learning device: the model supplies the pattern before the learner has a rule.","whyCN":"复制是最省力的学习装置：学习者还没有规则时，范本先提供了样式。"},{"no":"03","title":"Imitate in order to deceive","titleCN":"为欺骗而冒充","definition":"to copy another's appearance or signals so that a observer draws a false conclusion","definitionCN":"复制他者的外观或信号，使观察者得出错误判断","example":"Some spiders mimic ants to enter a colony unnoticed.","exampleCN":"有些蜘蛛模仿蚂蚁，以便不被察觉地进入蚁巢。","why":"Deception is the dark twin of entertainment: both depend on the copy being accepted as the original.","whyCN":"欺骗是娱乐的暗面双生：两者都依赖复制品被当作原件。"},{"no":"04","title":"Reproduce another system's behaviour","titleCN":"复现另一系统的行为（仿真）","definition":"used of software, hardware or models that reproduce the behaviour of another system","definitionCN":"用于软件、硬件或模型复现另一系统的行为","example":"The test rig mimics the vibration of a real wing.","exampleCN":"试验台模拟真实机翼的振动。","why":"Engineering generalizes the biological sense: the copy needs to behave like the original, not look like it.","whyCN":"工程学把生物义一般化：复制品需要行为像原件，而不必外形像。"},{"no":"05","title":"A person skilled at imitation","titleCN":"擅长模仿的人","definition":"a person who can reproduce another's voice or manner convincingly","definitionCN":"能令人信服地复现他人嗓音或举止的人","example":"She is the best mimic in the troupe.","exampleCN":"她是剧团里最擅长模仿的人。","why":"The agent noun is simply the person who performs the act named by the verb.","whyCN":"这个施动名词就是执行该动词所表行为的人。"},{"no":"06","title":"An organism resembling another species","titleCN":"外形酷似另一物种的生物","definition":"an animal or plant that has evolved to look like another species","definitionCN":"演化出与另一物种相似外形的动物或植物","example":"The hoverfly is a mimic of a wasp, but it has no sting.","exampleCN":"这只食蚜蝇酷似黄蜂，却并没有蜇针。","why":"Biology turns the noun into a label for the copying organism itself.","whyCN":"生物学把该名词转成对实施复制的生物本身的称呼。"},{"no":"07","title":"Attributive: imitative rather than genuine","titleCN":"作定语：仿制的、模拟的","definition":"used before a noun to mean that the thing imitates something else rather than being it","definitionCN":"置于名词前，表示该物仿照他物而非其本身","example":"The fish has mimic colouring that copies a dead leaf.","exampleCN":"这条鱼有模仿枯叶的体色。","why":"As an adjective the word moves from the actor to the feature that does the copying.","whyCN":"作形容词时，这个词从施动者转到实施复制的特征上。"},{"no":"08","title":"Of symptoms: resemble another disease","titleCN":"症状酷似另一种病","definition":"used of a condition whose signs copy those of a different disease, making diagnosis difficult","definitionCN":"用于症状复制另一种疾病表现、使诊断困难的情形","example":"A benign cyst can mimic a tumour on a scan.","exampleCN":"良性囊肿在扫描影像上可以酷似肿瘤。","why":"Medicine borrows the word for resemblance that misleads an expert observer, not a predator.","whyCN":"医学借用这个词指误导专业观察者的相似，而非误导捕食者。"}],"etymology":{"intro":{"en":"Mimic reached English through French mimique from Latin mimicus, itself from Greek mimikos, an adjective of mimos 'imitator'. The adjective and noun are sixteenth-century, the verb seventeenth-century.","cn":"mimic 经法语 mimique 来自拉丁 mimicus，后者出自希腊 mimikos，即 mimos「模仿者」的形容词。形容词与名词见于 16 世纪，动词见于 17 世纪。"},"items":[{"era":"GREEK MIMOS","en":"Greek mimos 'imitator, mime actor' is the base noun of the family.","cn":"希腊 mimos「模仿者、摹拟演员」是该词族的基础名词。"},{"era":"GREEK MIMIKOS","en":"The Greek adjective mimikos 'imitative, of a mime' supplied the shape later taken by Latin mimicus.","cn":"希腊形容词 mimikos「模仿的、摹拟表演的」提供了后来拉丁 mimicus 所取的形态。"},{"era":"LATIN MIMICUS","en":"Latin mimicus is a borrowing of the Greek adjective; it is not an inherited Latin formation.","cn":"拉丁 mimicus 借自希腊形容词，并非拉丁语继承而来的构词。"},{"era":"FRENCH MIMIQUE","en":"French mimique carried the adjective into English, where mimic appeared as adjective and noun in the 1570s.","cn":"法语 mimique 把这个形容词带入英语，mimic 于 1570 年代作为形容词与名词出现。"},{"era":"THE VERB","en":"The verb is generally dated to the 1680s, at first in the sense of burlesque imitation.","cn":"动词一般认为是 1680 年代出现，最初指滑稽模仿。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root): Greek mimos is secure as the immediate source, but its own deeper origin is disputed and may be Pre-Greek; the 1570s and 1680s dates are approximate.","cn":"来源不确定（词根）：希腊 mimos 作为直接来源是可靠的，但其更早的来源有争议，可能属前希腊语底层；1570 年代与 1680 年代均为约数。"}]},"similar":{"note":{"en":"Group one holds the same-family forms that are constantly swapped; group two holds verbs of copying that differ in purpose, fidelity or target.","cn":"第一组是同族中经常被混用的形式；第二组是复制类动词，区别在目的、逼真程度或对象。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mimicry","ipa":"/ˈmɪmɪkri/","tag":"noun of the practice","definition":"The named phenomenon or practice; mimic is the actor or the act itself.","definitionCN":"指被命名的现象或做法；mimic 指施动者或行为本身。"},{"word":"mimetic","ipa":"/mɪˈmetɪk/","tag":"adjective of quality","definition":"Describes something as imitative; mimic as an adjective is chiefly attributive and rarer.","definitionCN":"描述某物具有模仿性质；mimic 作形容词多作定语且更少见。"},{"word":"mimicked","ipa":"/ˈmɪmɪkt/","tag":"past form","definition":"The past tense or participle, not the base verb; note the double k before -ed.","definitionCN":"过去式或过去分词，不是动词原形；注意 -ed 前双写 k。"},{"word":"mimicker","ipa":"/ˈmɪmɪkə/","tag":"agent noun","definition":"A person who mimics; the formal agent noun, less common than the plain noun mimic.","definitionCN":"指模仿的人；是正式的施动名词，不如直接用 mimic 常见。"}]},{"heading":"NEAR MEANING","entries":[{"word":"imitate","ipa":"/ˈɪmɪteɪt/","tag":"neutral copying","definition":"The general verb for following a model; it lacks the playful or deceptive colour of mimic.","definitionCN":"表示照着范本做的一般动词，没有 mimic 那种戏谑或欺骗色彩。"},{"word":"impersonate","ipa":"/ɪmˈpɜːsəneɪt/","tag":"a specific person","definition":"To copy a particular person's identity, usually for performance or fraud; mimic can take a voice or a species.","definitionCN":"指复制某个特定人物的身份，多用于表演或行骗；mimic 的对象可以是嗓音或物种。"},{"word":"ape","ipa":"/eɪp/","tag":"crude or servile copying","definition":"To copy clumsily or without understanding; it carries disapproval that mimic need not carry.","definitionCN":"指笨拙或不加理解地照搬，含贬义，而 mimic 不一定含贬义。"},{"word":"emulate","ipa":"/ɪˈmjʊleɪt/","tag":"copy to rival","definition":"To copy in order to equal or surpass; the goal is competition, not amusement or disguise.","definitionCN":"指为达到或超越而仿效；目的是竞争，而非逗乐或伪装。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek-to-Latin route, the real inflected forms, and the collocations that distinguish the verb, noun and adjective uses.","cn":"正常联想：真实的希腊—拉丁路径、真实的屈折形式，以及区分动词、名词、形容词用法的固定搭配。"},"normal":[{"en":"mimos 'imitator' + -ic: belonging to an imitator.","cn":"mimos「模仿者」+ -ic：属于模仿者的。"},{"en":"The family runs mimic, mimicry, mimetic, mimesis, mime.","cn":"同族词包括 mimic、mimicry、mimetic、mimesis、mime。"},{"en":"Spelling note: mimics, mimicked, mimicking, with a doubled k.","cn":"拼写要点：mimics、mimicked、mimicking，k 要双写。"},{"en":"Fixed phrases: mimic the accent, mimic the symptoms, a gifted mimic.","cn":"固定搭配有 mimic the accent、mimic the symptoms、a gifted mimic。"},{"en":"Three jobs: entertain, learn, deceive.","cn":"三种功能：逗乐、学习、欺骗。"}],"abstract":[{"en":"Picture a mirror that learns the face in front of it.","cn":"想象一面镜子学会了它前面的那张脸。"},{"en":"Picture a spy copying a doorman's walk to pass a checkpoint.","cn":"想象一名间谍复制门卫的步态以通过检查站。"},{"en":"Picture a machine rehearsing a wing's tremor until the numbers match.","cn":"想象一台机器反复演练机翼的颤动，直到数据吻合。"}]},"examples":[{"en":"Parrots mimic household sounds with startling accuracy.","cn":"鹦鹉能以惊人的准确度模仿家中的声音。"},{"en":"The virus can mimic the body's own proteins and escape detection.","cn":"这种病毒能模仿人体自身的蛋白以躲过识别。"},{"en":"The robot was built to mimic a surgeon's hand movements.","cn":"这台机器人被造来模拟外科医生的手部动作。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「mimi（模仿声）+ -ic」——会学样子的 → 模仿；模仿者","word":"mimic"},"root":"希腊 mimos「模仿者」→ 希腊 mimikos「模仿的」→ 拉丁 mimicus（借自希腊语）→ 法语 mimique → 英语 mimic。","sensesIntro":{"en":"Eight senses branch from one act of copying: entertain, learn, deceive, simulate a system, name the copier, name the resembling organism, describe the imitative feature, and describe a misleading symptom.","cn":"八个义项由同一种复制行为分出：逗乐、学习、欺骗、模拟系统、称呼模仿者、称呼相似生物、描述仿制特征、描述误导性症状。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person following another's voice and hands in a mirror, half a beat behind.","cn":"核心意象：一个人对着镜子跟着另一个人的嗓音与手势，慢半拍。"},"chain":["WATCH A MODEL","REPEAT THE ACT","MATCH THE STYLE","PASS AS THE MODEL","SERVE A PURPOSE","NAME THE COPY"],"branches":[{"senses":"01 · 05","en":"PERFORMANCE: a skilled copier reproduces a voice for an audience.","cn":"表演：熟练的模仿者为观众复现嗓音。"},{"senses":"02","en":"LEARNING: repetition installs the pattern in the learner.","cn":"学习：重复把样式装进学习者。"},{"senses":"03 · 06 · 08","en":"DECEPTION: animals, symptoms and signals pass as something they are not.","cn":"欺骗：动物、症状与信号冒充成别的东西。"},{"senses":"04","en":"SIMULATION: a system reproduces another system's behaviour.","cn":"仿真：一个系统复现另一系统的行为。"},{"senses":"07","en":"ATTRIBUTION: the word describes the feature that carries the copy.","cn":"定语化：这个词描述承载复制特征的事物。"}]},"affixes":{"intro":{"en":"Mimic is a Greek noun stem with an adjective ending, routed through Latin and French; the family supplies both verbs and abstract nouns.","cn":"mimic 是希腊语名词词干加形容词词尾，经拉丁语与法语传入；该词族既提供动词，也提供抽象名词。"},"latinIntro":{"en":"Latin mimicus and mimus are Greek loans rather than native roots; they explain the shape of the French and English forms.","cn":"拉丁 mimicus 与 mimus 是希腊语借词，而非本土词根；它们解释了法语与英语形式的由来。"},"items":[{"word":"mimos","structure":"Greek mimos (imitator)","meaning":"one who copies","meaningCN":"模仿者","example":"Mimos named the stage imitator in Greek.","exampleCN":"mimos 在希腊语中指舞台上的仿演者。"},{"word":"-ic","structure":"Greek -ikos, Latin -icus (belonging to)","meaning":"of or belonging to","meaningCN":"属于……的","example":"The ending makes an adjective of a noun stem.","exampleCN":"这个后缀把名词词干变成形容词。"},{"word":"mimic","structure":"mimos + -ic","meaning":"to copy; a copier","meaningCN":"模仿；模仿者","example":"The child mimics the teacher.","exampleCN":"孩子模仿老师。"},{"word":"mimicry","structure":"mimic + -ry (practice)","meaning":"the practice or phenomenon of copying","meaningCN":"模仿或拟态这一现象","example":"Mimicry protects the hoverfly.","exampleCN":"拟态保护了这只食蚜蝇。"},{"word":"mimetic","structure":"Greek mimētikos + -ic","meaning":"imitative","meaningCN":"模仿的","example":"Mimetic art copies the visible world.","exampleCN":"模仿性艺术复制可见世界。"},{"word":"mimesis","structure":"Greek mimesis (imitation)","meaning":"imitation as a process","meaningCN":"作为过程的模仿","example":"Mimesis was a key term in Greek criticism.","exampleCN":"mimesis 是希腊文艺批评的关键术语。"},{"word":"mime","structure":"French mime, from Latin mimus","meaning":"silent performance","meaningCN":"哑剧","example":"He trained as a mime in Paris.","exampleCN":"他在巴黎学过哑剧。"},{"word":"mimicker","structure":"mimic + -er (agent)","meaning":"one who mimics","meaningCN":"模仿者","example":"A good mimicker hears the rhythm, not just the words.","exampleCN":"好的模仿者听的是节奏，而不只是词。"},{"word":"mimicry behavior","structure":"mimicry + behavior","meaning":"copying actions studied as behaviour","meaningCN":"作为行为研究的模仿动作","example":"Mimicry behavior spreads through a flock.","exampleCN":"拟态行为会在鸟群中扩散。"}],"latinEntries":[{"word":"mimicus","structure":"mimicus, mimica, mimicum (adjective, from Greek mimikos)","meaning":"imitative; of a mime","meaningCN":"模仿的；摹拟表演的"},{"word":"mimus","structure":"mimus, mimi (noun, from Greek mimos)","meaning":"mime actor","meaningCN":"摹拟演员"},{"word":"mimesis","structure":"mimesis (noun, from Greek)","meaning":"imitation","meaningCN":"模仿"}]}},{"word":"mimicry behavior","ipa_uk":"/ˈmɪmɪkri bɪˌheɪvjə/","ipa_us":"/ˈmɪmɪkri bɪˌheɪvjər/","definition_zh":"拟态行为；模仿行为","definition_en":"behavior in which an organism copies the appearance, signals or movements of another, or in which a person copies another's actions","core_image":"一只鸟跟着另一只鸟点头、转身，节奏几乎同步","scene":"观察站里，两只鸟轮流发出同一种叫声，动作一前一后完全对应。Researchers recorded mimicry behavior in pairs of birds that alternated the same call.","sceneCN":"这里 mimicry behavior 指「个体复制同类动作或信号的整套行为」（第 1 个义项：动物通过模仿他者的动作、姿态或叫声而获得某种功能）；句意为研究者记录了一对鸟轮流发出同一种叫声的拟态行为。图中可辨识物件：观察站、两只鸟、同步的抬头动作、录音设备。","pos":[{"tag":"n.","zh":"拟态行为；模仿行为（不可数；指具体事例时可用复数 mimicry behaviors）"}],"collocations":[{"phrase":"animal mimicry behavior","zh":"动物拟态行为"},{"phrase":"social mimicry behavior","zh":"社交模仿行为"},{"phrase":"vocal mimicry behavior","zh":"声音模仿行为"},{"phrase":"aggressive mimicry behavior","zh":"攻击性拟态行为"},{"phrase":"study mimicry behavior","zh":"研究模仿行为"},{"phrase":"mimicry behavior in pairs","zh":"成对个体间的模仿行为"}],"forms":[{"label":"复数（指具体事例）","form":"mimicry behaviors"},{"label":"英式拼写","form":"mimicry behaviour"},{"label":"相关名词（拟态）","form":"mimicry"},{"label":"相关动词（模仿）","form":"mimic"},{"label":"相关形容词（拟态的）","form":"mimetic"},{"label":"相关名词（行为）","form":"behavior"}],"derivatives":[{"word":"mimicry","pos":"n.","zh":"拟态；模仿"},{"word":"behavior","pos":"n.","zh":"行为；举止"},{"word":"behavioral","pos":"adj.","zh":"行为的"},{"word":"mimic","pos":"v./n.","zh":"模仿；模仿者"},{"word":"mimetic","pos":"adj.","zh":"模仿的"}],"senses":[{"no":"01","title":"Animal resemblance in action","titleCN":"动物的拟态行为","definition":"the actions by which one animal copies another's appearance, posture or signals in order to survive","definitionCN":"一种动物复制另一种动物的外观、姿态或信号以求生存的行为","example":"Researchers recorded mimicry behavior in pairs of birds that alternated the same call.","exampleCN":"研究者记录了一对鸟轮流发出同一种叫声的拟态行为。","why":"The compound names behaviour that carries out mimicry: the resemblance is not just a pattern on the body but something the animal does.","whyCN":"这个复合词命名的是实施拟态的行为：相似不只在体表图案上，也体现在动物所做的动作上。"},{"no":"02","title":"Social copying of posture and speech","titleCN":"社交中的姿态与语调趋同","definition":"the unconscious or deliberate copying of another person's posture, gesture or speech style during interaction","definitionCN":"互动中无意或有意复制他人的姿态、手势或说话风格","example":"Social mimicry behavior increases when two people feel rapport.","exampleCN":"两人感到投缘时，社交模仿行为会增多。","why":"Human interaction repeats the animal pattern: copying a posture signals that the copier belongs.","whyCN":"人类互动重复了动物的模式：复制姿态等于发出归属信号。"},{"no":"03","title":"Courtship copying of signals","titleCN":"求偶信号的模仿","definition":"the copying of courtship displays or signals by a rival or a satellite male","definitionCN":"竞争对手或卫星雄体复制求偶展示或信号的行为","example":"Satellite males use mimicry behavior to approach females guarded by a larger rival.","exampleCN":"卫星雄体用拟态行为接近被更大对手守护的雌性。","why":"In courtship the copied signal grants access, so copying becomes a reproductive tactic.","whyCN":"在求偶中，被复制的信号能带来接近机会，于是复制成了繁殖策略。"},{"no":"04","title":"Aggressive mimicry behavior","titleCN":"攻击性拟态行为","definition":"behavior that copies a harmless or attractive signal in order to lure prey within reach","definitionCN":"复制无害或诱人的信号，把猎物引到可及范围内的行为","example":"The spider's aggressive mimicry behavior imitates a mate's vibration on the web.","exampleCN":"这只蜘蛛的攻击性拟态行为模仿网上配偶的振动。","why":"The copy is bait: the predator performs the signal that the prey wants to find.","whyCN":"复制品是诱饵：捕食者表演出猎物想找到的那个信号。"},{"no":"05","title":"Vocal mimicry behavior","titleCN":"声音模仿行为","definition":"the copying of calls, songs or environmental sounds by an animal","definitionCN":"动物复制鸣叫、歌声或环境声音的行为","example":"Vocal mimicry behavior lets the parrot join a household's soundscape.","exampleCN":"声音模仿行为让鹦鹉融入家中的声音环境。","why":"When the copied channel is sound, the same behavioural label applies without any change of logic.","whyCN":"当被复制的渠道是声音时，同一个行为标签照旧适用，逻辑不变。"},{"no":"06","title":"Copying that builds rapport","titleCN":"建立亲近感的模仿","definition":"the use of matched gestures, rhythm or wording to make another person feel understood","definitionCN":"用相合的手势、节奏或措辞让对方感到被理解","example":"A counsellor's gentle mimicry behavior can put a nervous client at ease.","exampleCN":"咨询师温和的模仿行为能让紧张的来访者放松。","why":"Copying reduces distance; the behaviour is read as agreement rather than as imitation.","whyCN":"复制缩短距离；这种行为被读作认同，而不是被看作模仿。"},{"no":"07","title":"Copying as a research variable","titleCN":"作为研究变量的模仿行为","definition":"the measurable copying of movements or timing that psychologists code in interaction studies","definitionCN":"心理学家在互动研究中编码的可测量动作或时序复制","example":"The team coded mimicry behavior frame by frame from the video.","exampleCN":"团队逐帧编码视频中的模仿行为。","why":"Once behaviour is measured, the phrase becomes a countable variable rather than a description.","whyCN":"一旦行为被测量，这个短语就成了可计数的变量，而不再是描述。"},{"no":"08","title":"Imitation by machines or avatars","titleCN":"机器或虚拟形象的模仿行为","definition":"the reproduction of human movements or speech by a robot, avatar or generative system","definitionCN":"机器人、虚拟形象或生成系统复制人类动作或言语的行为","example":"The avatar's mimicry behavior made the interview feel strangely natural.","exampleCN":"虚拟形象的模仿行为让这场面试显得异样地自然。","why":"The newest extension moves the compound from organisms to systems that learn to copy people.","whyCN":"最新的引申把这个复合词从生物移到学会复制人的系统上。"}],"etymology":{"intro":{"en":"Mimicry behavior is an English compound of two learned words: mimicry from Greek mimos through Latin and French, and behavior from the native verb behave, of uncertain formation.","cn":"mimicry behavior 是由两个学术词构成的英语复合词：mimicry 出自希腊 mimos，经拉丁语与法语传入；behavior 出自本族动词 behave，其构词方式存疑。"},"items":[{"era":"GREEK MIMOS","en":"Greek mimos 'imitator' and its adjective mimikos underlie mimicry.","cn":"希腊 mimos「模仿者」及其形容词 mimikos 是 mimicry 的基础。"},{"era":"LATIN AND FRENCH","en":"Latin mimus and mimicus are Greek loans; French mimique then passed the adjective into English.","cn":"拉丁 mimus 与 mimicus 是希腊语借词；法语 mimique 随后把这个形容词带入英语。"},{"era":"BEHAVE","en":"Behavior derives from behave, first recorded in the sixteenth century as be- plus have, meaning 'to conduct oneself'.","cn":"behavior 来自 behave，16 世纪首次记录，由 be- 加 have 构成，意为「持身、举止」。"},{"era":"THE COMPOUND","en":"The compound mimicry behavior is a twentieth-century formation of technical English, built from two existing nouns rather than from a single root.","cn":"复合词 mimicry behavior 是 20 世纪技术英语的构词，由两个既有名词组合，而非出自单一词根。"},{"era":"SCIENTIFIC USE","en":"Ethologists and psychologists standardized the phrase when copying became a measured variable rather than an anecdote.","cn":"当复制成为可测量的变量而非轶事时，动物行为学家与心理学家把这个短语固定下来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact first use of the full compound is unrecorded, and the formation of behave is debated, with French influence suspected but not proved. The Greek root itself is secure.","cn":"来源不确定（首见年代）：完整复合词的最早使用无记录；behave 的构词方式有争议，所疑的法语影响未被证实；希腊词根本身可靠。"}]},"similar":{"note":{"en":"Group one separates the compound from its two source nouns and its spelling variants; group two separates kinds of copying behaviour by function.","cn":"第一组把该复合词与它的两个来源名词及拼写变体分开；第二组按功能区分不同类型的复制行为。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mimicry","ipa":"/ˈmɪmɪkri/","tag":"the phenomenon, not the actions","definition":"The resemblance or practice itself; mimicry behavior names the actions that produce or use it.","definitionCN":"指相似本身或这种做法；mimicry behavior 指产生或运用它的具体动作。"},{"word":"behavior","ipa":"/bɪˈheɪvjə/","tag":"general category","definition":"Any conduct; the compound narrows it to conduct that copies.","definitionCN":"泛指任何举止；复合词把它收窄为复制性的举止。"},{"word":"mimicry behaviours","ipa":"/bɪˈheɪvjəz/","tag":"British spelling and plural","definition":"The same term in British spelling, or a plural counting specific instances.","definitionCN":"同一术语的英式拼写，或指具体事例的复数形式。"},{"word":"mimic behaviour","ipa":"/ˈmɪmɪk bɪˈheɪvjə/","tag":"verb-based variant","definition":"A looser variant built on the verb mimic; the fixed technical term uses the noun mimicry.","definitionCN":"以动词 mimic 为基础的较松散变体；固定技术术语用名词 mimicry。"}]},{"heading":"NEAR MEANING","entries":[{"word":"social mimicry","ipa":"/ˈsəʊʃl ˈmɪmɪkri/","tag":"human rapport","definition":"Copying posture and speech to build rapport; it is one kind of mimicry behavior, not the whole class.","definitionCN":"指通过复制姿态与言语建立亲近感；它只是拟态行为的一类。"},{"word":"mimesis","ipa":"/mɪˈmiːsɪs/","tag":"process term","definition":"Imitation treated as a general process in art or biology, without reference to measured actions.","definitionCN":"把模仿当作艺术或生物中的普遍过程，不涉及可测量的动作。"},{"word":"copying","ipa":"/ˈkɒpiɪŋ/","tag":"plain and broad","definition":"The everyday word for reproducing something; it makes no claim about signals or survival value.","definitionCN":"日常用词，泛指复制；不涉及信号或生存价值。"},{"word":"mimicry display","ipa":"/ˈmɪmɪkri dɪˈspleɪ/","tag":"a single performance","definition":"One staged instance of copying; mimicry behavior covers the whole recurring pattern.","definitionCN":"指一次具体的模仿展示；mimicry behavior 指整套反复出现的行为模式。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real source nouns, the real spelling variants, and the way ethology and psychology actually use the phrase.","cn":"正常联想：两个真实的来源名词、真实的拼写变体，以及动物行为学与心理学实际使用该短语的方式。"},"normal":[{"en":"mimicry plus behavior: the doing of imitation.","cn":"mimicry 加 behavior：模仿这件事的实施。"},{"en":"The family runs mimicry, mimic, mimetic, behavior, behavioral.","cn":"同族词包括 mimicry、mimic、mimetic、behavior、behavioral。"},{"en":"American spelling behavior, British behaviour.","cn":"美式拼写 behavior，英式拼写 behaviour。"},{"en":"Fixed phrases: animal mimicry behavior, social mimicry behavior, vocal mimicry behavior.","cn":"固定搭配有 animal mimicry behavior、social mimicry behavior、vocal mimicry behavior。"},{"en":"The phrase is countable only when it means individual cases.","cn":"只有指具体个案时，这个短语才可数。"}],"abstract":[{"en":"Picture two birds nodding in turn like two pendulums sharing one beat.","cn":"想象两只鸟轮流点头，像两个共享同一节拍的单摆。"},{"en":"Picture a conversation in which one person slowly adopts the other's rhythm.","cn":"想象一段对话，其中一人慢慢采用了另一人的节奏。"},{"en":"Picture a lure that performs the exact vibration a spider's prey expects.","cn":"想象一个诱饵，表演出蜘蛛猎物正期待的那种振动。"}]},"examples":[{"en":"The study links mimicry behavior to the survival of the brood.","cn":"这项研究把拟态行为与整窝幼体的存活联系起来。"},{"en":"Social mimicry behavior is strongest among people who already agree.","cn":"社交模仿行为在本来意见相合的人之间最强。"},{"en":"The robot's mimicry behavior was judged natural by most viewers.","cn":"多数观看者认为这台机器人的模仿行为很自然。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「mimicry（模仿）+ behavior（行为）」——做出来的模仿 → 拟态行为；模仿行为","word":"mimicry behavior"},"root":"希腊 mimos「模仿者」→ 拉丁 mimus、mimicus → 法语 mimique → 英语 mimicry；behavior 由本族动词 behave（be- + have）派生；整个短语为 20 世纪英语复合词。","sensesIntro":{"en":"Eight senses take one copied action through its uses: survival resemblance, social bonding, courtship, luring prey, voice, rapport, measurement, and finally machines that copy people.","cn":"八个义项把同一种复制动作依次放进不同用途：生存相似、社交联结、求偶、诱捕、声音、亲近感、测量，最后是复制人的机器。"},"semanticMap":{"core":{"en":"CORE IMAGE: two birds nodding in turn, one beat apart, until their rhythms lock.","cn":"核心意象：两只鸟轮流点头，相差一拍，直到节奏锁合。"},"chain":["WATCH A SIGNAL","REPEAT THE ACT","SYNCHRONIZE","SERVE A FUNCTION","MEASURE THE COPY","EXTEND TO MACHINES"],"branches":[{"senses":"01 · 03 · 04","en":"SURVIVAL USE: resemblance, courtship access and luring all depend on the copy being believed.","cn":"生存用途：相似、求偶接近与诱捕都依赖复制品被相信。"},{"senses":"02 · 06","en":"SOCIAL USE: copied posture and rhythm turn strangers into allies.","cn":"社交用途：被复制的姿态与节奏把陌生人变成同盟。"},{"senses":"05","en":"VOICE: the copied channel is sound rather than sight.","cn":"声音：被复制的渠道是听觉而非视觉。"},{"senses":"07","en":"MEASUREMENT: behaviour is coded frame by frame as data.","cn":"测量：行为被逐帧编码成数据。"},{"senses":"08","en":"MACHINE COPY: systems learn to reproduce human conduct.","cn":"机器复制：系统学会复现人类举止。"}]},"affixes":{"intro":{"en":"The phrase is a compound of a Greek-derived noun and a native-derived noun of behaviour; there is no single root or prefix to divide.","cn":"这个短语是希腊来源名词与本族来源行为名词的复合，无法再分成单一词根加词缀。"},"latinIntro":{"en":"Latin contributes only mimus and mimicus, both Greek loans; behave is native Germanic and has no Latin etymon.","cn":"拉丁语只贡献 mimus 与 mimicus，两者都是希腊语借词；behave 属本族日耳曼语，没有拉丁词源。"},"items":[{"word":"mimicry","structure":"Greek mimos + -ry","meaning":"the practice of copying","meaningCN":"模仿的做法","example":"Mimicry is the older noun.","exampleCN":"mimicry 是更早的名词。"},{"word":"behavior","structure":"behave + -ior (noun of state)","meaning":"conduct; manner of acting","meaningCN":"举止；行为方式","example":"Behavior can be observed and counted.","exampleCN":"行为可以被观察和计数。"},{"word":"behave","structure":"be- + have (to hold oneself)","meaning":"to conduct oneself","meaningCN":"持身；举止","example":"The animals behave differently in pairs.","exampleCN":"这些动物成对时行为不同。"},{"word":"behavioral","structure":"behavior + -al (relating to)","meaning":"relating to conduct","meaningCN":"与行为有关的","example":"Behavioral studies code the timing of gestures.","exampleCN":"行为研究编码手势的时序。"},{"word":"mimic","structure":"mimos + -ic","meaning":"to copy","meaningCN":"模仿","example":"The young mimic the old.","exampleCN":"年幼者模仿年长者。"},{"word":"mimetic","structure":"Greek mimētikos + -ic","meaning":"imitative","meaningCN":"模仿的","example":"Mimetic signals are easy to copy.","exampleCN":"模仿性信号容易被复制。"},{"word":"mimesis","structure":"Greek mimesis","meaning":"imitation as process","meaningCN":"作为过程的模仿","example":"Mimesis names the process, not the act.","exampleCN":"mimesis 命名过程，而非具体动作。"},{"word":"mimicry behavior","structure":"mimicry + behavior","meaning":"actions that carry out copying","meaningCN":"实施复制的动作","example":"Mimicry behavior was coded from video.","exampleCN":"拟态行为已从视频中被编码。"},{"word":"mimicry behaviours","structure":"mimicry behavior + plural -s","meaning":"specific instances","meaningCN":"具体事例","example":"The paper lists three mimicry behaviours.","exampleCN":"论文列出了三种拟态行为。"}],"latinEntries":[{"word":"mimus","structure":"mimus, mimi (noun, from Greek mimos)","meaning":"mime actor; imitator","meaningCN":"摹拟演员；模仿者"},{"word":"mimicus","structure":"mimicus, mimica, mimicum (adjective, from Greek)","meaning":"imitative","meaningCN":"模仿的"},{"word":"mimesis","structure":"mimesis (noun, from Greek)","meaning":"imitation","meaningCN":"模仿"}]}},{"word":"coloration","ipa_uk":"/ˌkɒləˈreɪʃn/","ipa_us":"/ˌkoʊləˈreɪʃn/","definition_zh":"着色；色彩；体色；（生物的）色彩图案","definition_en":"the arrangement or quality of colours on an organism or object, or the act of giving something colour","core_image":"一只甲虫的鞘翅从深蓝过渡到金属绿，颜色像被刷上去的一层","scene":"热带雨林的落叶层上，一只甲虫的鞘翅随角度由深蓝转为金属绿。The beetle's iridescent coloration warns birds that it tastes bitter.","sceneCN":"这里 coloration 指「生物体表的整体色彩图案」（第 1 个义项：一个生物身上颜色的分布与组合方式）；句意为这只甲虫彩虹般的体色警告鸟类它味道苦涩。图中可辨识物件：甲虫鞘翅、蓝绿渐变、退开的鸟。","pos":[{"tag":"n.","zh":"着色；色彩；体色；色彩图案（多不可数）"}],"collocations":[{"phrase":"protective coloration","zh":"保护色"},{"phrase":"warning coloration","zh":"警戒色"},{"phrase":"cryptic coloration","zh":"隐蔽色"},{"phrase":"seasonal coloration","zh":"季节性体色"},{"phrase":"iridescent coloration","zh":"虹彩体色"},{"phrase":"skin coloration","zh":"皮肤色泽"}],"forms":[{"label":"复数（指多种色彩类型）","form":"colorations"},{"label":"动词（着色）","form":"color"},{"label":"动词（英式拼写）","form":"colour"},{"label":"形容词（有色彩的）","form":"colorful"},{"label":"形容词（无色彩的）","form":"colorless"},{"label":"相关名词（颜色）","form":"color"}],"derivatives":[{"word":"color","pos":"n./v.","zh":"颜色；给……着色"},{"word":"colorful","pos":"adj.","zh":"色彩丰富的"},{"word":"colorless","pos":"adj.","zh":"无色的；乏味的"},{"word":"colored","pos":"adj.","zh":"有色的；着色的"},{"word":"colorant","pos":"n.","zh":"着色剂"}],"senses":[{"no":"01","title":"Overall colour pattern of an organism","titleCN":"生物体表的整体色彩图案","definition":"the whole arrangement of colours and markings on an animal's or plant's body","definitionCN":"动物或植物身上颜色与斑纹的整体分布","example":"The beetle's iridescent coloration warns birds that it tastes bitter.","exampleCN":"这只甲虫的虹彩体色警告鸟类它味道苦涩。","why":"The -ation noun names the resulting state: what the colours together look like on a body.","whyCN":"-ation 名词命名结果状态：各种颜色在体表合起来呈现的样子。"},{"no":"02","title":"Cryptic coloration","titleCN":"隐蔽色","definition":"colours that match the background and make an animal difficult to see","definitionCN":"与背景相合、使动物难以被看见的颜色","example":"The lizard's cryptic coloration makes it disappear against the gravel.","exampleCN":"这只蜥蜴的隐蔽色使它消失在砾石背景中。","why":"Hiding is the most common use of body colour, so the general noun took this sense early.","whyCN":"隐藏是体色最常见的用途，因此这个一般名词很早就承担了这一义。"},{"no":"03","title":"Warning coloration","titleCN":"警戒色","definition":"bright colours that advertise a defence such as poison or a sting","definitionCN":"鲜艳的颜色，用以通告毒液或蜇针等防御手段","example":"The wasp's black and yellow coloration is a warning, not an invitation.","exampleCN":"黄蜂的黑黄体色是警告，不是邀请。","why":"The same surface can carry the opposite message: instead of hiding, it announces.","whyCN":"同一层体表可以传递相反的信息：不隐藏，而是宣告。"},{"no":"04","title":"Coloration of plants","titleCN":"植物的色彩","definition":"the colours of leaves, flowers, fruits or stems, often serving attraction or protection","definitionCN":"叶、花、果或茎的颜色，常起吸引或保护作用","example":"The red coloration of the fruit attracts seed-dispersing birds.","exampleCN":"果实的红色吸引传播种子的鸟。","why":"Plants use colour for the same two jobs as animals: hide or advertise.","whyCN":"植物用颜色做与动物同样的两件事：隐藏或宣传。"},{"no":"05","title":"Dyeing or colouring process","titleCN":"着色过程","definition":"the act or process of giving colour to a material","definitionCN":"给材料加上颜色的行为或过程","example":"The coloration of the glass takes place in a single furnace pass.","exampleCN":"这块玻璃的着色在一次炉内处理中完成。","why":"The noun also names the act that produces the state, not only the state itself.","whyCN":"这个名词也命名产生该状态的行为，而不只是状态本身。"},{"no":"06","title":"Colour scheme in design","titleCN":"设计中的配色","definition":"the chosen combination of colours in a design, garment or interior","definitionCN":"设计、服装或室内所选用的颜色组合","example":"The room's warm coloration makes it feel smaller and calmer.","exampleCN":"房间的暖色调让它显得更小、更安静。","why":"The word extends from bodies to made objects once colour is planned as a scheme.","whyCN":"一旦颜色被当作方案来规划，这个词就从身体扩展到人造物。"},{"no":"07","title":"Vocal coloration or timbre","titleCN":"嗓音的色彩或音色","definition":"the quality of tone that gives a voice or instrument its particular character","definitionCN":"赋予人声或乐器特定性格的音质","example":"Her low coloration suits the narrator's quiet authority.","exampleCN":"她低沉的音色正适合叙述者那种安静的权威感。","why":"Music borrows the visual word: timbre colours a sound the way pigment colours a surface.","whyCN":"音乐借用了这个视觉词：音色给声音上色，正如颜料给表面上色。"},{"no":"08","title":"Slight bias in a report","titleCN":"叙述中的偏向色彩","definition":"a subtle emotional or political tint given to a description or account","definitionCN":"给描述或叙述加上细微的情绪或政治色彩","example":"The report's cheerful coloration hides a serious failure.","exampleCN":"报告欢快的色彩掩盖了一次严重失误。","why":"The figurative sense keeps the idea of a surface coat: wording adds a hue without changing the facts.","whyCN":"比喻义保留「表面涂层」的意思：措辞加上一层色调，却不改变事实。"}],"etymology":{"intro":{"en":"Coloration comes from Latin colorare 'to colour', a verb built on color, through French coloration. The deeper origin of Latin color is debated; the common link to a root meaning 'to cover' is a reconstruction.","cn":"coloration 经法语 coloration 来自拉丁 colorare「着色」，后者由 color 构成。拉丁 color 的更早来源有争议；把它与表示「遮盖」的词根相联属重构。"},"items":[{"era":"LATIN COLOR","en":"Latin color meant 'colour, hue, outward appearance' and also 'pretext'; it is the noun behind the whole family.","cn":"拉丁 color 意为「颜色、色调、外观」，也指「借口」；它是整族词背后的名词。"},{"era":"LATIN COLORARE","en":"Colorare 'to give colour to, to dye' is a derivative verb of color, with coloratus as its participle.","cn":"colorare「给……上色、染」是由 color 派生的动词，分词为 coloratus。"},{"era":"FRENCH COLORATION","en":"French coloration named the act or result of colouring and passed into English in the sixteenth century.","cn":"法语 coloration 命名着色行为或结果，16 世纪进入英语。"},{"era":"SCIENTIFIC SENSE","en":"Biology fixed the sense 'body colour pattern' in the nineteenth century, when protective and warning coloration became standard terms.","cn":"生物学在 19 世纪固定了「体色图案」这一义，当时保护色与警戒色成为标准术语。"},{"era":"FIGURATIVE EXTENSIONS","en":"The musical and rhetorical senses are later metaphors: timbre and wording are treated as coats of colour.","cn":"音乐义与修辞义是更晚的比喻：音色与措辞都被当作一层颜色涂层。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root): Latin color may descend from a root meaning 'to cover, conceal', which would also explain celare 'to hide'; this is a reconstruction and competing accounts exist. The first English date is approximate.","cn":"来源不确定（词根）：拉丁 color 可能出自表示「覆盖、隐藏」的词根，这也能解释 celare「藏」；此说属重构形式，另有不同说法。首见英语年代为约数。"}]},"similar":{"note":{"en":"Group one separates the noun from its verb and adjective relatives; group two separates terms that describe colour in organisms, design and language.","cn":"第一组区分该名词与它的动词、形容词同族；第二组区分描述生物、设计与语言中颜色的术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"color","ipa":"/ˈkəʊlə/","tag":"the substance or hue","definition":"A particular hue or the material producing it; coloration is the pattern or state produced.","definitionCN":"指某一种色调或产生它的材料；coloration 指由此形成的图案或状态。"},{"word":"colorant","ipa":"/ˈkəʊlərənt/","tag":"the additive","definition":"A dye or pigment added to something; it is an agent, not a resulting appearance.","definitionCN":"指加入某物中的染料或颜料；是施动者，不是呈现出的外观。"},{"word":"colored","ipa":"/ˈkəʊləd/","tag":"adjective of possession","definition":"Having colour; it states a property rather than naming the pattern.","definitionCN":"表示有颜色；陈述一种属性，而不命名图案。"},{"word":"colouration","ipa":"/ˌkɒləˈreɪʃn/","tag":"British spelling","definition":"The same word in British spelling; American texts use coloration.","definitionCN":"同一词的英式拼写；美式文本用 coloration。"}]},{"heading":"NEAR MEANING","entries":[{"word":"pigmentation","ipa":"/ˌpɪɡmenˈteɪʃn/","tag":"pigment deposit","definition":"Colour produced specifically by pigment in tissue; coloration is the broader visible pattern, however produced.","definitionCN":"特指组织内色素产生的颜色；coloration 是更宽泛的可见图案，不问成因。"},{"word":"colouring","ipa":"/ˈkəʊlərɪŋ/","tag":"British gerund","definition":"The act of adding colour or the added substance; coloration is more common in scientific description.","definitionCN":"指加色的行为或所加物质；coloration 更常用于科学描述。"},{"word":"hue","ipa":"/hjuː/","tag":"single tone","definition":"One shade within the spectrum; coloration covers the whole arrangement of shades.","definitionCN":"指光谱中的单一色调；coloration 覆盖全部色调的组合。"},{"word":"markings","ipa":"/ˈmɑːkɪŋz/","tag":"pattern elements","definition":"Visible spots, stripes or patches; coloration includes both markings and the ground colour.","definitionCN":"指可见的斑点、条纹或斑块；coloration 同时包含斑纹与底色。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin verb, the real scientific compounds, and the genuine extension into music and rhetoric.","cn":"正常联想：真实的拉丁动词、真实的科学复合词，以及进入音乐与修辞的真实引申。"},"normal":[{"en":"color + -ation: the state or act of being coloured.","cn":"color 加 -ation：被上色的状态或行为。"},{"en":"The family runs color, colorare, coloration, colorful, colorless.","cn":"同族词包括 color、colorare、coloration、colorful、colorless。"},{"en":"Biology pairs the term with cryptic, protective and warning.","cn":"生物学把这个词与 cryptic、protective、warning 搭配。"},{"en":"Iridescent coloration changes with the angle of light.","cn":"虹彩体色随光线角度变化。"},{"en":"The same noun serves animals, paint, interiors and voices.","cn":"同一个名词可用于动物、涂料、室内与嗓音。"}],"abstract":[{"en":"Picture a beetle whose shell shifts from blue to green as it turns.","cn":"想象一只甲虫转身时鞘翅从蓝变绿。"},{"en":"Picture a warning flag painted on a living body.","cn":"想象一面警告旗被画在活体身上。"},{"en":"Picture a sentence wearing a cheerful coat over bad news.","cn":"想象一句话给坏消息披上欢快的外衣。"}]},"examples":[{"en":"Seasonal coloration helps the hare match snow and soil.","cn":"季节性体色帮助野兔匹配雪地与泥土。"},{"en":"The glass owes its green coloration to iron impurities.","cn":"这块玻璃的绿色来自铁杂质。"},{"en":"The choir's warm coloration softened the closing line.","cn":"合唱团温暖的音色软化了收尾句。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「color（颜色）+ -ation（状态）」——呈现出来的颜色状态 → 色彩；体色","word":"coloration"},"root":"拉丁 color「颜色、外观」→ 拉丁 colorare「着色」→ 法语 coloration → 英语 coloration；拉丁 color 的更深词根存疑，可能与表示「遮盖」的词根有关。","sensesIntro":{"en":"Eight senses grow from one surface of colour: an organism's pattern, its hiding and warning uses, plants, dyeing, design, vocal timbre, and finally the tint of a report.","cn":"八个义项从同一层颜色表面长出：生物的图案、其隐藏与警告用途、植物、染色、设计、音色，最后是叙述的色调。"},"semanticMap":{"core":{"en":"CORE IMAGE: a beetle's wing case shifting from deep blue to metallic green as it turns.","cn":"核心意象：一只甲虫的鞘翅随转动从深蓝变为金属绿。"},"chain":["SURFACE COLOUR","PATTERN ON A BODY","HIDE OR WARN","EXTEND TO PLANTS","APPLY TO MADE THINGS","TINT SOUND AND SPEECH"],"branches":[{"senses":"01 · 02","en":"BODY PATTERN: the whole arrangement of colour on an organism, including concealment.","cn":"体表图案：生物身上颜色的整体安排，包括隐蔽。"},{"senses":"03 · 04","en":"SIGNAL AND PLANT: colour advertises defence and draws pollinators or dispersers.","cn":"信号与植物：颜色通告防御，也吸引传粉者或传播者。"},{"senses":"05","en":"PROCESS: colour is applied to a material rather than grown on a body.","cn":"过程：颜色被施加到材料上，而非长在身体上。"},{"senses":"06","en":"DESIGN: colours are chosen as a deliberate scheme.","cn":"设计：颜色被当作有意的方案来挑选。"},{"senses":"07 · 08","en":"METAPHOR: tone colours a voice, and wording colours an account.","cn":"比喻：音色给嗓音上色，措辞给叙述上色。"}]},"affixes":{"intro":{"en":"Coloration is a Latin verb stem plus the noun ending -ation; the Latin family around color supplies verbs, adjectives and agent nouns.","cn":"coloration 是拉丁动词词干加名词词尾 -ation；围绕 color 的拉丁词族提供动词、形容词与施动名词。"},"latinIntro":{"en":"Latin color, colorare and coloratus supply the stem and the sense of applying colour.","cn":"拉丁 color、colorare 与 coloratus 提供词干及「施加颜色」的含义。"},"items":[{"word":"color","structure":"Latin color (colour, hue)","meaning":"colour; outward appearance","meaningCN":"颜色；外观","example":"Color is the noun behind the family.","exampleCN":"color 是整族词背后的名词。"},{"word":"-ation","structure":"Latin -atio, -ationis (action or result)","meaning":"process or resulting state","meaningCN":"过程或结果状态","example":"The ending names both the act and its result.","exampleCN":"这个后缀同时命名行为与结果。"},{"word":"colorare","structure":"Latin colorare (to colour)","meaning":"to give colour to","meaningCN":"给……上色","example":"Colorare produced French colorer.","exampleCN":"colorare 产生了法语 colorer。"},{"word":"coloration","structure":"colorare + -ation","meaning":"colouring; colour pattern","meaningCN":"着色；色彩图案","example":"The bird's coloration is purely seasonal.","exampleCN":"这只鸟的体色完全是季节性的。"},{"word":"colorful","structure":"color + -ful (full of)","meaning":"rich in colour","meaningCN":"色彩丰富的","example":"The reef is colorful at noon.","exampleCN":"正午时珊瑚礁色彩丰富。"},{"word":"colorless","structure":"color + -less (without)","meaning":"without colour","meaningCN":"无色的","example":"The gas is colourless.","exampleCN":"这种气体是无色的。"},{"word":"colored","structure":"color + -ed (having)","meaning":"having colour","meaningCN":"有颜色的","example":"The glass is colored with iron oxide.","exampleCN":"这块玻璃用氧化铁着色。"},{"word":"colorant","structure":"color + -ant (agent)","meaning":"a colouring agent","meaningCN":"着色剂","example":"A natural colorant replaced the dye.","exampleCN":"一种天然着色剂取代了染料。"},{"word":"colorimetry","structure":"color + -metry (measurement)","meaning":"measurement of colour","meaningCN":"色度测量","example":"Colorimetry tracks the beetle's hue.","exampleCN":"色度测量追踪甲虫的色调。"}],"latinEntries":[{"word":"color","structure":"color, coloris (noun, third declension)","meaning":"colour; hue","meaningCN":"颜色；色调"},{"word":"colorare","structure":"colorare, coloravi, coloratum (verb, first conjugation)","meaning":"to colour, dye","meaningCN":"着色；染色"},{"word":"coloratus","structure":"coloratus, colorata, coloratum (participle/adjective)","meaning":"coloured","meaningCN":"着了色的"}]}},{"word":"pigmentation","ipa_uk":"/ˌpɪɡmenˈteɪʃn/","ipa_us":"/ˌpɪɡmənˈteɪʃn/","definition_zh":"色素沉着；着色；色素分布","definition_en":"the presence, amount or deposition of pigment in a tissue or material, or the colouring that results","core_image":"皮肤表层下一簇深色颗粒均匀铺开，像撒了一层细沙","scene":"海边正午，一名渔民的肩膀被晒成深褐色。Sun exposure increases pigmentation in the skin, forming freckles and dark patches.","sceneCN":"这里 pigmentation 指「皮肤中色素增多而形成的着色」（第 1 个义项：日晒后黑色素在皮肤中沉积，使肤色变深）；句意为日晒使皮肤色素沉着增加，形成雀斑与深色斑块。图中可辨识物件：晒成深褐色的肩膀、肩带留下的浅色痕、帽檐阴影。","pos":[{"tag":"n.","zh":"色素沉着；着色；色素分布（不可数）"}],"collocations":[{"phrase":"skin pigmentation","zh":"皮肤色素沉着"},{"phrase":"abnormal pigmentation","zh":"色素异常"},{"phrase":"increased pigmentation","zh":"色素增多"},{"phrase":"loss of pigmentation","zh":"色素丧失"},{"phrase":"pigmentation disorder","zh":"色素障碍"},{"phrase":"facial pigmentation","zh":"面部色素沉着"}],"forms":[{"label":"复数（指多种类型）","form":"pigmentations"},{"label":"名词（色素）","form":"pigment"},{"label":"形容词（有色的）","form":"pigmented"},{"label":"形容词（色素的）","form":"pigmentary"},{"label":"动词（着色）","form":"pigment"},{"label":"反义名词（脱色）","form":"depigmentation"}],"derivatives":[{"word":"pigment","pos":"n./v.","zh":"色素；给……着色"},{"word":"pigmented","pos":"adj.","zh":"有色的；色素沉着的"},{"word":"pigmentary","pos":"adj.","zh":"色素的"},{"word":"depigmentation","pos":"n.","zh":"色素脱失"},{"word":"hyperpigmentation","pos":"n.","zh":"色素沉着过度"}],"senses":[{"no":"01","title":"Colouring from pigment in the skin","titleCN":"皮肤中色素形成的着色","definition":"the deposition of pigment in skin that produces a tan, freckles or naturally dark complexion","definitionCN":"色素在皮肤中沉积，形成晒黑、雀斑或天生深肤色","example":"Sun exposure increases pigmentation in the skin, forming freckles and dark patches.","exampleCN":"日晒使皮肤色素沉着增加，形成雀斑与深色斑块。","why":"The -ation noun names the process and its visible result: pigment has settled into tissue and changed its colour.","whyCN":"-ation 名词同时命名过程与可见结果：色素沉入组织并改变了它的颜色。"},{"no":"02","title":"Medical disorder of pigment","titleCN":"医学上的色素异常","definition":"an abnormal increase, decrease or distribution of pigment that signals a skin condition","definitionCN":"色素的异常增多、减少或分布，提示某种皮肤病变","example":"The clinic treats pigmentation caused by old sun damage.","exampleCN":"这家诊所治疗旧日晒伤留下的色素沉着。","why":"Once pigmentation is measured, any departure from the expected amount becomes a clinical finding.","whyCN":"一旦色素量可被测量，任何偏离预期的量都成了临床所见。"},{"no":"03","title":"Colour in plant tissue","titleCN":"植物组织中的着色","definition":"the presence of coloured compounds such as anthocyanins in leaves, petals or fruit","definitionCN":"叶片、花瓣或果实中存在花青素等着色化合物","example":"Cool nights deepen the pigmentation of the maple leaves.","exampleCN":"寒冷的夜晚加深了枫叶的色素。","why":"Plants produce their own pigments, so the same noun covers tissue colour without any animal skin.","whyCN":"植物自己产生色素，因此这个名词无需动物皮肤也能指组织颜色。"},{"no":"04","title":"Colour pattern in feathers or fur","titleCN":"羽毛或毛皮的颜色分布","definition":"the arrangement of pigment in feathers, hair or fur that gives an animal its markings","definitionCN":"羽毛、毛发或毛皮中色素的分布，形成动物的斑纹","example":"The owl's pigmentation breaks up its outline against the trunk.","exampleCN":"这只猫头鹰的羽色把它的轮廓从树干背景中打散。","why":"Feathers and fur are dead tissue coloured by pigment, exactly the surface the noun describes.","whyCN":"羽毛与毛皮是由色素着色的死组织，正是这个名词所描述的表面。"},{"no":"05","title":"Pigment in the eye","titleCN":"眼睛中的色素","definition":"the amount of melanin in the iris or retina that determines eye colour and light tolerance","definitionCN":"虹膜或视网膜中黑色素的含量，决定眼睛颜色与耐光程度","example":"Low pigmentation in the iris lets more light scatter, so the eyes look blue.","exampleCN":"虹膜色素少会让更多光线散射，于是眼睛看起来是蓝色。","why":"The eye is another pigmented surface; the noun needs no new meaning for it.","whyCN":"眼睛是又一个带色素的表面，这个名词无需新义就能覆盖。"},{"no":"06","title":"Colour of microbial colonies","titleCN":"微生物菌落的颜色","definition":"the pigment produced by bacteria or fungi that colours their colonies","definitionCN":"细菌或真菌产生、使菌落显色的色素","example":"The plate showed pigmentation typical of a soil bacterium.","exampleCN":"培养皿显示出一种土壤细菌典型的色素。","why":"Colour is a by-product of microbial chemistry, so the noun applies to colonies exactly as it does to skin.","whyCN":"颜色是微生物化学的副产物，因此这个名词用于菌落与用于皮肤完全同理。"},{"no":"07","title":"Industrial colouring of materials","titleCN":"工业材料着色","definition":"the addition of pigment to plastics, coatings or ceramics to give them colour","definitionCN":"向塑料、涂料或陶瓷加入色素以赋予颜色","example":"Uniform pigmentation is essential in automotive paint.","exampleCN":"汽车漆中均匀的着色至关重要。","why":"Industry applies pigment to inert materials, extending the biological noun to manufacture.","whyCN":"工业把色素施加到惰性材料上，把这个生物名词扩展到制造领域。"},{"no":"08","title":"Pigment traces in fossils","titleCN":"化石中的色素痕迹","definition":"chemical residues of pigment preserved in fossils that reveal original colours","definitionCN":"化石中保存的色素化学残留，可揭示原本的颜色","example":"Pigmentation preserved in the fossil shows the dinosaur was dark-backed.","exampleCN":"化石中保存的色素表明这只恐龙背部颜色深。","why":"Deep time leaves only the pigment chemistry, but it is still the same noun: colour preserved in stone.","whyCN":"深时只留下色素的化学成分，但仍是同一个名词：保存在石头里的颜色。"}],"etymology":{"intro":{"en":"Pigmentation is Latin pigmentum 'paint' plus -ation, from the verb pigmentare; pigmentum itself comes from pingere 'to paint'. The word entered English through French in the nineteenth century.","cn":"pigmentation 由拉丁 pigmentum「颜料」加 -ation 构成，出自动词 pigmentare；pigmentum 本身来自 pingere「绘画」。这个词 19 世纪经法语进入英语。"},"items":[{"era":"LATIN PINGERE","en":"Pingere 'to paint, to embroider' is the verb at the base of the family; its past participle is pictus.","cn":"pingere「绘画、刺绣」是该词族底层的动词，其过去分词为 pictus。"},{"era":"LATIN PIGMENTUM","en":"Pigmentum meant 'colouring matter, paint' and was formed from pingere with the noun suffix -mentum.","cn":"pigmentum 意为「着色物、颜料」，由 pingere 加名词后缀 -mentum 构成。"},{"era":"FRENCH PIGMENTATION","en":"French pigmentation named the action of colouring and reached English in the 1830s, first in medical descriptions.","cn":"法语 pigmentation 命名着色行为，1830 年代进入英语，最初用于医学描述。"},{"era":"SCIENTIFIC SPREAD","en":"Nineteenth-century biology applied the noun to skin, feathers and plant tissue, fixing the modern sense.","cn":"19 世纪生物学把这个名词用于皮肤、羽毛与植物组织，固定了现代义。"},{"era":"ROOT RECONSTRUCTION","en":"The deeper source of pingere is reconstructed as a root meaning 'to cut, mark, paint'; the form is a reconstruction, not a recorded word.","cn":"pingere 的更早来源被重构为表示「切、刻、画」的词根；该形式是重构，并非有记录的词。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and root): the 1830s date is approximate, and the reconstructed root of pingere has competing proposals. The Latin pigmentum layer itself is secure.","cn":"来源不确定（首见年代与词根）：1830 年代为约数，pingere 的重构词根存在不同提案；拉丁 pigmentum 这一层本身可靠。"}]},"similar":{"note":{"en":"Group one holds forms of the same Latin family that are easily confused; group two holds words for colour change that differ in cause or in scope.","cn":"第一组是同一拉丁词族中容易混淆的形式；第二组是表示颜色变化的词，区别在成因或范围。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"pigment","ipa":"/ˈpɪɡmənt/","tag":"the substance","definition":"The colouring matter itself; pigmentation is its presence or deposition in tissue.","definitionCN":"指着色物质本身；pigmentation 指它在组织中的存在或沉积。"},{"word":"pigmented","ipa":"/ˈpɪɡməntɪd/","tag":"adjective","definition":"Having pigment; it describes a thing, not the process that put pigment there.","definitionCN":"指含有色素的；描述事物，而非把色素放进去的过程。"},{"word":"pigmentary","ipa":"/ˈpɪɡməntəri/","tag":"relational adjective","definition":"Relating to pigment, as in pigmentary layer; it does not name the colouring itself.","definitionCN":"表示与色素有关的，如色素层；并不命名着色本身。"},{"word":"depigmentation","ipa":"/ˌdiːpɪɡmenˈteɪʃn/","tag":"opposite process","definition":"The loss of pigment, the reverse of pigmentation; the prefix de- reverses the direction.","definitionCN":"指色素丧失，与 pigmentation 方向相反；前缀 de- 表示反向。"}]},{"heading":"NEAR MEANING","entries":[{"word":"coloration","ipa":"/ˌkɒləˈreɪʃn/","tag":"visible pattern","definition":"The overall colour pattern, whatever produces it; pigmentation names the pigment cause specifically.","definitionCN":"指整体色彩图案，不问成因；pigmentation 特指色素这一成因。"},{"word":"tanning","ipa":"/ˈtænɪŋ/","tag":"sun response","definition":"The skin's darkening after sun exposure; pigmentation is the underlying deposit, tanning the everyday result.","definitionCN":"指日晒后皮肤变深；pigmentation 是底层的沉积，tanning 是日常可见的结果。"},{"word":"discoloration","ipa":"/ˌdɪsˌkʌləˈreɪʃn/","tag":"unwanted change","definition":"A change of colour seen as damage or fault; pigmentation is neutral about whether the colour is wanted.","definitionCN":"指被视为损伤或缺陷的颜色变化；pigmentation 不判断这种颜色是否受欢迎。"},{"word":"staining","ipa":"/ˈsteɪnɪŋ/","tag":"external deposit","definition":"Colour left on a surface by an external substance; pigmentation usually arises inside the tissue.","definitionCN":"指外部物质在表面留下的颜色；pigmentation 多由组织内部产生。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin chain of pingere, pigmentum and -ation, the real medical compounds, and the fixed collocations.","cn":"正常联想：pingere、pigmentum 与 -ation 的真实拉丁链条、真实的医学复合词，以及固定搭配。"},"normal":[{"en":"pingere 'paint' gives pigmentum 'paint', and -ation names the result.","cn":"pingere「画」给出 pigmentum「颜料」，-ation 命名结果。"},{"en":"The family runs pigment, pigmented, pigmentary, pigmentation, depigmentation.","cn":"同族词包括 pigment、pigmented、pigmentary、pigmentation、depigmentation。"},{"en":"Medical pairs: hyperpigmentation and hypopigmentation.","cn":"医学配对：色素沉着过度与色素减少。"},{"en":"Fixed phrases: skin pigmentation, pigmentation disorder, facial pigmentation.","cn":"固定搭配有 skin pigmentation、pigmentation disorder、facial pigmentation。"},{"en":"The word covers skin, feathers, leaves, eyes, colonies and paint.","cn":"这个词覆盖皮肤、羽毛、叶片、眼睛、菌落与涂料。"}],"abstract":[{"en":"Picture fine dark grains settling under a sheet of skin like sand under glass.","cn":"想象细小的深色颗粒沉在皮肤之下，像玻璃下的沙。"},{"en":"Picture a maple leaf deepening its red as the nights get cold.","cn":"想象一片枫叶随着夜寒加深而变红。"},{"en":"Picture an eye whose blue is only scattered light over very little pigment.","cn":"想象一只蓝眼睛，那蓝色只是极少色素之上散射的光。"}]},"examples":[{"en":"Pigmentation varies with latitude and with inherited melanin levels.","cn":"色素沉着随纬度与遗传的黑色素水平而变化。"},{"en":"The fungus produces pigmentation only when exposed to light.","cn":"这种真菌只在见光时产生色素。"},{"en":"The paint's pigmentation faded after a decade in the sun.","cn":"这种漆的着色在日晒十年后褪去。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pigment（色素）+ -ation（状态）」——色素落下来形成的状态 → 色素沉着；着色","word":"pigmentation"},"root":"拉丁 pingere「绘画」→ 拉丁 pigmentum「颜料」→ 法语 pigmentation → 英语 pigmentation；pingere 的更深词根为重构形式，存在不同提案。","sensesIntro":{"en":"Eight senses follow pigment as it settles: into skin, into a disorder, into plants, feathers, eyes, colonies, industrial coatings and finally fossil stone.","cn":"八个义项跟随色素沉降的路径：进入皮肤、成为病变、进入植物、羽毛、眼睛、菌落、工业涂层，最后进入化石。"},"semanticMap":{"core":{"en":"CORE IMAGE: fine dark grains settling under a sheet of skin like sand beneath glass.","cn":"核心意象：细小深色颗粒沉在皮肤之下，像玻璃下的沙。"},"chain":["PIGMENT GRAINS","SETTLE IN TISSUE","CHANGE SURFACE COLOUR","BECOME A CLINICAL SIGN","EXTEND TO OTHER SURFACES","LEAVE A FOSSIL TRACE"],"branches":[{"senses":"01 · 05","en":"HUMAN BODY: skin and iris colour record how much pigment sits where.","cn":"人体：皮肤与虹膜颜色记录色素沉积的位置与数量。"},{"senses":"02","en":"MEDICINE: excess or loss of pigment becomes a diagnosis.","cn":"医学：色素过多或过少成为诊断。"},{"senses":"03 · 04 · 06","en":"OTHER ORGANISMS: plants, feathers and microbes each colour their own tissue.","cn":"其他生物：植物、羽毛与微生物各自给组织上色。"},{"senses":"07","en":"INDUSTRY: pigment is added to inert materials by design.","cn":"工业：色素被有意加入惰性材料。"},{"senses":"08","en":"DEEP TIME: pigment residues survive in fossils.","cn":"深时：色素残留能在化石中保存。"}]},"affixes":{"intro":{"en":"Pigmentation is a Latin noun stem plus -ation; pigmentum in turn is pingere plus -mentum, so two Latin suffixes stack in the history of the word.","cn":"pigmentation 是拉丁名词词干加 -ation；pigmentum 又是 pingere 加 -mentum，因此这个词的历史上叠了两个拉丁后缀。"},"latinIntro":{"en":"Latin pingere, pigmentum and pictus supply the paint family behind pigmentation and picture alike.","cn":"拉丁 pingere、pigmentum 与 pictus 提供「颜料」词族，pigmentation 与 picture 都出自这里。"},"items":[{"word":"pigment","structure":"Latin pigmentum < pingere + -mentum","meaning":"colouring matter","meaningCN":"着色物质；颜料","example":"The pigment is ground fine before mixing.","exampleCN":"颜料在混合前被磨得很细。"},{"word":"-ation","structure":"Latin -atio, -ationis (action or result)","meaning":"process or state","meaningCN":"过程或状态","example":"The ending names the deposit and its result.","exampleCN":"这个后缀命名沉积及其结果。"},{"word":"pigmentation","structure":"French pigmentation < pigment + -ation","meaning":"deposition of colour","meaningCN":"色素沉积","example":"Skin pigmentation increased after the holiday.","exampleCN":"假期后皮肤色素沉着增加了。"},{"word":"pigmented","structure":"pigment + -ed (having)","meaning":"having pigment","meaningCN":"含有色素的","example":"The lesion is unevenly pigmented.","exampleCN":"这块病灶的色素分布不均。"},{"word":"pigmentary","structure":"pigment + -ary (relating to)","meaning":"relating to pigment","meaningCN":"与色素有关的","example":"A pigmentary layer lies beneath the retina.","exampleCN":"视网膜下有一层色素层。"},{"word":"pigment cell","structure":"pigment + cell (compound)","meaning":"a cell containing pigment","meaningCN":"含色素的细胞","example":"Pigment cells cluster in the iris.","exampleCN":"色素细胞聚集在虹膜中。"},{"word":"pigment granule","structure":"pigment + granule (compound)","meaning":"a tiny packet of pigment","meaningCN":"微小的色素颗粒","example":"Each pigment granule holds melanin.","exampleCN":"每个色素颗粒都装着黑色素。"},{"word":"hyperpigmentation","structure":"hyper- (over) + pigmentation","meaning":"excess pigment","meaningCN":"色素沉着过度","example":"Hyperpigmentation followed the inflammation.","exampleCN":"炎症之后出现了色素沉着过度。"},{"word":"hypopigmentation","structure":"hypo- (under) + pigmentation","meaning":"deficient pigment","meaningCN":"色素减少","example":"Hypopigmentation left pale patches.","exampleCN":"色素减少留下了浅色斑块。"}],"latinEntries":[{"word":"pigmentum","structure":"pigmentum, pigmenti (noun, second declension)","meaning":"paint, colouring matter","meaningCN":"颜料；着色物"},{"word":"pingere","structure":"pingere, pinxi, pictum (verb, third conjugation)","meaning":"to paint, embroider","meaningCN":"绘画；刺绣"},{"word":"pictus","structure":"pictus, picta, pictum (participle/adjective)","meaning":"painted","meaningCN":"画过的；着色的"}]}},{"word":"pigment","ipa_uk":"/ˈpɪɡmənt/","ipa_us":"/ˈpɪɡmənt/","definition_zh":"色素；颜料；（动植物组织中的）色质","definition_en":"a substance that gives colour to paint, ink, tissue or another material","core_image":"一只陶罐里沉着赭红色的矿粉，手指一捻就留下颜色","scene":"岩洞壁画开工前，画师先把赭石磨成细粉。Grinding ochre into a fine pigment was the first step before any cave painting.","sceneCN":"这里 pigment 指「使材料显色的物质本身」（第 1 个义项：用于绘画或染色的着色材料）；句意为在任何岩洞壁画开工之前，第一步都是把赭石磨成细颜料。图中可辨识物件：陶罐、赭红色矿粉、研磨石、手指上的色痕。","pos":[{"tag":"n.","zh":"色素；颜料；色质"},{"tag":"vt.","zh":"给……着色（重音后移，读 /pɪɡˈment/）"}],"collocations":[{"phrase":"natural pigment","zh":"天然色素"},{"phrase":"synthetic pigment","zh":"合成颜料"},{"phrase":"pigment powder","zh":"颜料粉末"},{"phrase":"photosynthetic pigment","zh":"光和色素"},{"phrase":"pigment cells","zh":"色素细胞"},{"phrase":"mineral pigment","zh":"矿物颜料"}],"forms":[{"label":"复数","form":"pigments"},{"label":"三单（动词）","form":"pigments"},{"label":"过去式","form":"pigmented"},{"label":"过去分词","form":"pigmented"},{"label":"现在分词","form":"pigmenting"},{"label":"形容词（有色的）","form":"pigmented"},{"label":"形容词（色素的）","form":"pigmentary"},{"label":"名词（色素沉着）","form":"pigmentation"}],"derivatives":[{"word":"pigmentation","pos":"n.","zh":"色素沉着；着色"},{"word":"pigmented","pos":"adj.","zh":"有色的"},{"word":"pigmentary","pos":"adj.","zh":"色素的"},{"word":"pigment cell","pos":"n.","zh":"色素细胞"},{"word":"depigment","pos":"v.","zh":"使脱色"}],"senses":[{"no":"01","title":"Colouring matter in paint or ink","titleCN":"涂料或油墨中的着色物质","definition":"a solid substance ground into a medium to give paint, ink or dye its colour","definitionCN":"被研磨进介质、使涂料、油墨或染料显色的固体物质","example":"Grinding ochre into a fine pigment was the first step before any cave painting.","exampleCN":"在任何岩洞壁画开工之前，第一步都是把赭石磨成细颜料。","why":"The Latin noun meant 'paint' first: the material itself, before the colour it produces.","whyCN":"这个拉丁名词最初意为「颜料」：先指着色材料本身，再指它产生的颜色。"},{"no":"02","title":"Natural colouring in living tissue","titleCN":"生物组织中的天然色素","definition":"a compound such as melanin, chlorophyll or haemoglobin that colours living tissue","definitionCN":"如黑色素、叶绿素或血红蛋白这类使活体组织显色的化合物","example":"Melanin is the pigment that darkens skin and hair.","exampleCN":"黑色素是使皮肤与毛发变深的色素。","why":"Living tissue makes its own colouring matter, so the industrial noun transfers to biology without change.","whyCN":"活体组织自己制造着色物质，因此工业名词不加变化地转到生物学。"},{"no":"03","title":"Skin or hair colouring substance","titleCN":"皮肤或毛发中的色素","definition":"the pigment in skin, hair or eyes that determines how dark they appear","definitionCN":"皮肤、毛发或眼睛中决定其深浅的色素","example":"Less pigment in the iris lets the eyes appear blue.","exampleCN":"虹膜中色素较少时，眼睛呈蓝色。","why":"Skin and hair are surfaces coloured by a substance, which is the original meaning of the noun.","whyCN":"皮肤与毛发是被某种物质着色的表面，正是这个名词的本义。"},{"no":"04","title":"Dry colour powder for artists","titleCN":"画家的干色粉","definition":"a dry powdered colour that an artist mixes with a binder","definitionCN":"画家与黏结剂混合使用的干色粉","example":"The studio shelves were lined with jars of pigment.","exampleCN":"画室的架子上排满了装着颜料的罐子。","why":"An artist's powder is the noun at its most literal: colour before any medium is added.","whyCN":"画家的干粉是这个名词最字面的用法：尚未加介质的颜色。"},{"no":"05","title":"Industrial colourant","titleCN":"工业着色剂","definition":"a colouring additive used in plastics, coatings, ceramics or printing","definitionCN":"用于塑料、涂料、陶瓷或印刷的着色添加剂","example":"The factory adds a red pigment to every batch of plastic.","exampleCN":"工厂给每一批塑料都加入红色颜料。","why":"Industry adds the same kind of powder to inert material instead of tissue.","whyCN":"工业把同类粉末加入惰性材料，而非组织。"},{"no":"06","title":"Photosynthetic pigment","titleCN":"光和色素","definition":"a molecule such as chlorophyll that absorbs light for photosynthesis","definitionCN":"如叶绿素这类吸收光能以进行光合作用的分子","example":"Chlorophyll is the main pigment that captures light in leaves.","exampleCN":"叶绿素是叶片中捕获光能的主要色素。","why":"Biology narrows the word to compounds whose colour is a by-product of light capture.","whyCN":"生物学把词义收窄到那些颜色只是捕光副产物的化合物。"},{"no":"07","title":"Colourant in cosmetics","titleCN":"化妆品中的着色剂","definition":"an approved colouring substance added to makeup, sunscreen or soap","definitionCN":"加入化妆品、防晒霜或肥皂的许可着色物质","example":"The lipstick's pigment is iron oxide, not dye.","exampleCN":"这支口红的着色剂是氧化铁，而不是染料。","why":"Cosmetics are another surface where a stable colouring substance replaces a dye.","whyCN":"化妆品是又一个用稳定着色物质替代染料的表面。"},{"no":"08","title":"To colour something with pigment","titleCN":"用色素给某物着色","definition":"to add pigment to a material so that it takes on colour","definitionCN":"把色素加入材料，使其呈现颜色","example":"Workers pigment the concrete while it is still wet.","exampleCN":"工人在混凝土还湿的时候给它着色。","why":"The verb is the zero-derived action of the noun, stressed on the second syllable.","whyCN":"动词由名词零派生而来，重音落在第二个音节。"}],"etymology":{"intro":{"en":"Pigment comes from Latin pigmentum 'colouring matter, paint', formed from pingere 'to paint' with -mentum. English borrowed it through French in the fourteenth century.","cn":"pigment 来自拉丁 pigmentum「着色物、颜料」，由 pingere「绘画」加 -mentum 构成。英语于 14 世纪经法语借入。"},"items":[{"era":"LATIN PINGERE","en":"Pingere meant 'to paint, to embroider'; its past participle pictus gives picture and depict as well.","cn":"pingere 意为「绘画、刺绣」；其过去分词 pictus 也衍生出 picture 与 depict。"},{"era":"LATIN PIGMENTUM","en":"Pigmentum 'paint, colouring matter' was built with -mentum, a suffix of means or result.","cn":"pigmentum「颜料、着色物」由表示手段或结果的后缀 -mentum 构成。"},{"era":"FRENCH AND ENGLISH","en":"Old French pigment passed into English in the 1300s, first for painters' materials and later for bodily colour.","cn":"古法语 pigment 于 14 世纪进入英语，先指画家用料，后指身体颜色。"},{"era":"BIOLOGICAL SENSE","en":"The biological use for melanin and chlorophyll developed in the nineteenth century with tissue chemistry.","cn":"指黑色素与叶绿素的生物义在 19 世纪随组织化学发展而来。"},{"era":"ROOT RECONSTRUCTION","en":"The root behind pingere is reconstructed as a word for cutting or marking; it is a reconstruction rather than an attested form.","cn":"pingere 背后的词根被重构为表示切或刻的词；这是重构形式，并非有记录的词形。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root): the reconstructed root of pingere has competing proposals, and the exact first English date is approximate. The Latin pigmentum layer is secure.","cn":"来源不确定（词根）：pingere 的重构词根存在不同提案，英语首见的确切年代为约数；拉丁 pigmentum 这一层可靠。"}]},"similar":{"note":{"en":"Group one separates the noun from its derived adjectives and its action noun; group two separates colouring materials by how they are used.","cn":"第一组区分该名词与派生形容词、动作名词；第二组按用途区分各类着色材料。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"pigmentation","ipa":"/ˌpɪɡmenˈteɪʃn/","tag":"process or state","definition":"The presence or deposition of pigment; pigment is the material that is deposited.","definitionCN":"指色素的存在或沉积；pigment 指被沉积的材料。"},{"word":"pigmented","ipa":"/ˈpɪɡməntɪd/","tag":"adjective","definition":"Having pigment; it describes a surface rather than the substance.","definitionCN":"指含有色素的；描述表面，而非物质本身。"},{"word":"pigmentary","ipa":"/ˈpɪɡməntəri/","tag":"relational","definition":"Relating to pigment, as in a pigmentary layer; it cannot stand for the substance.","definitionCN":"表示与色素有关的，如色素层；不能代替物质本身。"},{"word":"pigmentosa","ipa":"/ˌpɪɡmənˈtəʊsə/","tag":"medical label","definition":"A Latin-derived adjective used in disease names; it is not a general word for pigment.","definitionCN":"用于病名的拉丁来源形容词，并非泛指色素的词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dye","ipa":"/daɪ/","tag":"soluble colour","definition":"A soluble colouring substance that penetrates a material; a pigment is usually insoluble and sits on or in a binder.","definitionCN":"指可溶的着色物质，能渗入材料；pigment 通常不溶，靠黏结剂附着。"},{"word":"paint","ipa":"/peɪnt/","tag":"the finished mixture","definition":"Pigment mixed with a binder and solvent; pigment is only one ingredient of paint.","definitionCN":"指颜料与黏结剂、溶剂混合后的成品；pigment 只是涂料的一种成分。"},{"word":"colorant","ipa":"/ˈkʌlərənt/","tag":"broad category","definition":"Any substance added to change colour, including dyes and pigments; it is the wider term.","definitionCN":"指任何为改变颜色而加入的物质，包括染料与颜料；是更宽泛的上位词。"},{"word":"tint","ipa":"/tɪnt/","tag":"a pale shade","definition":"A pale or slight colour, or to give one; pigment is the material, tint the effect.","definitionCN":"指浅淡的颜色或使变浅；pigment 是材料，tint 是效果。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin paint family, the real biological pigments, and the stress shift between noun and verb.","cn":"正常联想：真实的拉丁颜料词族、真实的生物色素，以及名词与动词之间的重音转移。"},"normal":[{"en":"pingere 'paint' + -mentum: the stuff you paint with.","cn":"pingere「画」+ -mentum：用来画的东西。"},{"en":"The family runs pigment, pigmentation, pigmented, pigmentary, picture.","cn":"同族词包括 pigment、pigmentation、pigmented、pigmentary、picture。"},{"en":"Biology names three: melanin, chlorophyll, haemoglobin.","cn":"生物学常举三种：黑色素、叶绿素、血红蛋白。"},{"en":"Noun stress PIG-ment, verb stress pig-MENT.","cn":"名词重音在前，动词重音在后。"},{"en":"Fixed phrases: natural pigment, mineral pigment, pigment powder.","cn":"固定搭配有 natural pigment、mineral pigment、pigment powder。"}],"abstract":[{"en":"Picture a jar of red earth that becomes a cave wall's whole story.","cn":"想象一罐红土变成整面岩壁的故事。"},{"en":"Picture a leaf's green as the visible edge of captured sunlight.","cn":"想象叶片的绿色是被捕获的阳光露出的边缘。"},{"en":"Picture a fingertip carrying colour before any brush arrives.","cn":"想象在画笔到来之前，指尖已经沾上了颜色。"}]},"examples":[{"en":"The artist mixed the pigment with egg yolk to make tempera.","cn":"画家把颜料与蛋黄混合，制成蛋彩。"},{"en":"Iron oxide pigments give the desert its red and yellow rocks.","cn":"氧化铁颜料让沙漠岩石呈现红黄两色。"},{"en":"Some bacteria pigment their colonies deep purple.","cn":"有些细菌把菌落染成深紫色。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pig（猪）+ ment」——像猪拱地翻出的红土粉 → 颜料；色素","word":"pigment"},"root":"拉丁 pingere「绘画」→ 拉丁 pigmentum「颜料」→ 古法语 pigment → 英语 pigment；pingere 的更深词根为重构形式。","sensesIntro":{"en":"Eight senses start from a jar of ground colour and move to living tissue, skin, an artist's shelf, a factory, a leaf, a lipstick and finally the verb of colouring.","cn":"八个义项从一罐研磨好的颜色出发，依次到活体组织、皮肤、画家架子、工厂、叶片、口红，最后是着色的动词。"},"semanticMap":{"core":{"en":"CORE IMAGE: a jar of ochre powder that leaves colour on a fingertip.","cn":"核心意象：一罐赭石粉在指尖留下颜色。"},"chain":["GROUND COLOUR","MIXED WITH A BINDER","APPLIED TO A SURFACE","FOUND IN TISSUE","CAPTURES LIGHT","ADDS COLOUR BY DESIGN"],"branches":[{"senses":"01 · 04","en":"ART MATERIAL: dry colour ground and bound for painting.","cn":"绘画材料：磨细并加黏结剂用于绘画的干色。"},{"senses":"03 · 06","en":"LIVING COLOUR: skin pigment and chlorophyll colour tissue.","cn":"活体色彩：皮肤色素与叶绿素给组织上色。"},{"senses":"07","en":"COSMETICS: colour is added by design to products worn on the body.","cn":"化妆品：为穿戴在身上的产品按设计添加颜色。"},{"senses":"08","en":"ACTION: the noun turns into a verb of colouring.","cn":"动作：名词转为着色的动词。"},{"senses":"02 · 05","en":"SCALE: the same material serves a cell and a factory batch.","cn":"尺度：同一材料既供细胞使用，也供工厂批量使用。"}]},"affixes":{"intro":{"en":"Pigment is a Latin noun in -mentum built on the verb pingere; its derivatives add English suffixes for state, relation and action.","cn":"pigment 是由动词 pingere 加 -mentum 构成的拉丁名词；其派生词再加英语后缀表示状态、关系与动作。"},"latinIntro":{"en":"Latin pingere, pigmentum and pictura supply the whole paint family in English.","cn":"拉丁 pingere、pigmentum 与 pictura 提供英语中整个「颜料」词族。"},"items":[{"word":"pigment","structure":"Latin pigmentum < pingere + -mentum","meaning":"colouring matter","meaningCN":"着色物质","example":"The pigment is stored in a dark jar.","exampleCN":"颜料存放在深色罐中。"},{"word":"-mentum","structure":"Latin -mentum (means or result)","meaning":"instrument or product","meaningCN":"工具或产物","example":"The suffix marks the material as a means.","exampleCN":"这个后缀把这材料标为手段。"},{"word":"pigmentation","structure":"pigment + -ation","meaning":"deposition of colour","meaningCN":"色素沉积","example":"Pigmentation protects the skin from sunlight.","exampleCN":"色素沉着保护皮肤免受日晒。"},{"word":"pigmented","structure":"pigment + -ed","meaning":"having pigment","meaningCN":"含色素的","example":"The upper layer is heavily pigmented.","exampleCN":"上层色素很重。"},{"word":"pigmentary","structure":"pigment + -ary","meaning":"relating to pigment","meaningCN":"与色素有关的","example":"Pigmentary cells line the skin.","exampleCN":"色素细胞排列在皮肤中。"},{"word":"pigment cell","structure":"pigment + cell","meaning":"a colour-bearing cell","meaningCN":"含色素的细胞","example":"Pigment cells respond to sunlight.","exampleCN":"色素细胞对日晒有反应。"},{"word":"pigment granule","structure":"pigment + granule","meaning":"a small pigment particle","meaningCN":"色素颗粒","example":"The granule releases colour when crushed.","exampleCN":"颗粒被压碎时释放颜色。"},{"word":"photosynthetic pigment","structure":"photosynthetic + pigment","meaning":"a light-capturing colour","meaningCN":"捕获光能的色素","example":"Chlorophyll is a photosynthetic pigment.","exampleCN":"叶绿素是一种光和色素。"},{"word":"depigment","structure":"de- (remove) + pigment","meaning":"to remove colour","meaningCN":"使脱色","example":"The process depigments the hair.","exampleCN":"这一过程使毛发脱色。"}],"latinEntries":[{"word":"pigmentum","structure":"pigmentum, pigmenti (noun)","meaning":"paint; colouring matter","meaningCN":"颜料；着色物"},{"word":"pingere","structure":"pingere, pinxi, pictum (verb)","meaning":"to paint","meaningCN":"绘画"},{"word":"pictura","structure":"pictura, picturae (noun)","meaning":"painting; picture","meaningCN":"绘画；图画"}]}},{"word":"melanin","ipa_uk":"/ˈmelənɪn/","ipa_us":"/ˈmelənɪn/","definition_zh":"黑色素","definition_en":"the dark brown or black pigment produced in skin, hair, eyes, feathers and some other tissues","core_image":"皮肤基底层里一排装满深褐色颗粒的细胞，像一排小墨囊","scene":"同一双眼睛在强光下显得近乎黑色。More melanin in the iris makes the eyes look dark brown rather than blue.","sceneCN":"这里 melanin 指「决定皮肤、毛发与眼睛深浅的深色色素」（第 1 个义项：黑色素在组织中的含量决定颜色深浅）；句意为虹膜中黑色素越多，眼睛就越呈深褐色而不是蓝色。图中可辨识物件：虹膜、深褐与浅蓝的对照、一束强光。","pos":[{"tag":"n.","zh":"黑色素（不可数）"}],"collocations":[{"phrase":"melanin production","zh":"黑色素生成"},{"phrase":"melanin levels","zh":"黑色素水平"},{"phrase":"excess melanin","zh":"黑色素过多"},{"phrase":"melanin pigment","zh":"黑色素颜料"},{"phrase":"melanin synthesis","zh":"黑色素合成"},{"phrase":"lack of melanin","zh":"缺乏黑色素"}],"forms":[{"label":"形容词（含黑色素的）","form":"melanized"},{"label":"形容词（黑色素过多的）","form":"melanotic"},{"label":"名词（黑色素细胞）","form":"melanocyte"},{"label":"名词（黑色素体）","form":"melanosome"},{"label":"名词（黑素瘤）","form":"melanoma"},{"label":"名词（黑色素增多）","form":"melanism"}],"derivatives":[{"word":"melanocyte","pos":"n.","zh":"黑色素细胞"},{"word":"melanosome","pos":"n.","zh":"黑色素体"},{"word":"melanoma","pos":"n.","zh":"黑素瘤"},{"word":"melanistic","pos":"adj.","zh":"黑化的"},{"word":"melanism","pos":"n.","zh":"黑化现象"}],"senses":[{"no":"01","title":"Pigment of skin and hair","titleCN":"皮肤与毛发中的黑色素","definition":"the brown-black pigment produced by melanocytes that determines the shade of skin and hair","definitionCN":"黑色素细胞产生的棕黑色色素，决定皮肤与毛发的深浅","example":"More melanin in the iris makes the eyes look dark brown rather than blue.","exampleCN":"虹膜中黑色素越多，眼睛就越呈深褐色而不是蓝色。","why":"The Greek word for black gave the pigment its name; the amount, not the presence, sets the visible colour.","whyCN":"希腊语中表示「黑」的词给了这种色素名称；决定可见颜色的是含量，而不是有无。"},{"no":"02","title":"Pigment in the iris","titleCN":"虹膜中的黑色素","definition":"melanin in the front layers of the iris, whose density produces brown, hazel or apparently blue eyes","definitionCN":"虹膜前层中的黑色素，其密度形成褐色、淡褐色或看似蓝色的眼睛","example":"Blue eyes contain little melanin, so light scatters at short wavelengths.","exampleCN":"蓝眼睛含黑色素很少，光线在短波长上散射。","why":"The iris is a thin pigmented layer, so its colour is read directly from melanin density.","whyCN":"虹膜是一层薄薄的带色素组织，其颜色直接由黑色素密度读出。"},{"no":"03","title":"Pigment in feathers and fur","titleCN":"羽毛与毛皮中的黑色素","definition":"melanin deposited in feathers or hair that produces black, brown and grey coats","definitionCN":"沉积在羽毛或毛发中的黑色素，形成黑、褐、灰色被毛","example":"The crow's black feathers are dense with melanin.","exampleCN":"乌鸦的黑色羽毛中黑色素很密。","why":"Feathers are dead tissue packed with pigment, the same surface logic as skin.","whyCN":"羽毛是装满色素的死组织，与皮肤遵循同一表面逻辑。"},{"no":"04","title":"Pigment in insect cuticle","titleCN":"昆虫表皮中的黑色素","definition":"melanin in the outer skeleton of insects that darkens the cuticle and hardens it","definitionCN":"昆虫外骨骼中的黑色素，使表皮变深并增强硬度","example":"Melanin thickens the beetle's cuticle as well as darkening it.","exampleCN":"黑色素既加深甲虫表皮的颜色，也使它更坚硬。","why":"In insects melanin also hardens the cuticle, so the pigment serves structure as well as colour.","whyCN":"在昆虫中，黑色素还使表皮硬化，因此它既供颜色也供结构。"},{"no":"05","title":"Pigment in fungi","titleCN":"真菌中的黑色素","definition":"melanin produced by fungi that protects them from radiation, enzymes and immune attack","definitionCN":"真菌产生的黑色素，保护它们免受辐射、酶与免疫攻击","example":"Many soil fungi use melanin as a shield against ultraviolet light.","exampleCN":"许多土壤真菌把黑色素当作抵御紫外线的盾牌。","why":"Fungi use the same dark polymer as a shield, extending the name beyond animals.","whyCN":"真菌用同一种深色聚合物作盾牌，把这个名称扩展到动物之外。"},{"no":"06","title":"Natural sunscreen","titleCN":"天然的防晒层","definition":"the function of melanin in absorbing ultraviolet radiation before it damages DNA","definitionCN":"黑色素在紫外线损伤 DNA 之前将其吸收的功能","example":"Melanin absorbs part of the ultraviolet light that reaches the skin.","exampleCN":"黑色素吸收了到达皮肤的一部分紫外线。","why":"The pigment's colour is a consequence of its light absorption, so protection becomes a named function.","whyCN":"色素的颜色是其吸光的后果，于是保护成了被命名的功能。"},{"no":"07","title":"Pigment in cephalopod ink","titleCN":"头足类墨汁中的黑色素","definition":"the melanin that gives squid and octopus ink its dark colour","definitionCN":"使鱿鱼与章鱼墨汁呈深色的黑色素","example":"The squid's ink owes its blackness to melanin.","exampleCN":"鱿鱼墨汁的黑色来自黑色素。","why":"Squid ink is a concentrated suspension of the same pigment, used as a screen rather than a colour.","whyCN":"鱿鱼墨汁是同一色素的浓缩悬浮液，用作烟幕而非颜色。"},{"no":"08","title":"Synthetic melanin in materials research","titleCN":"材料研究中的合成黑色素","definition":"laboratory-made melanin used to study pigmentation or to build light-absorbing materials","definitionCN":"实验室制造的黑色素，用于研究色素或制造吸光材料","example":"The team grew a synthetic melanin film that absorbs nearly all visible light.","exampleCN":"团队培育出一种合成黑色素薄膜，几乎吸收全部可见光。","why":"Once the polymer can be synthesized, the biological noun follows it into materials science.","whyCN":"一旦这种聚合物可以合成，生物名词就跟着它进入材料科学。"}],"etymology":{"intro":{"en":"Melanin joins Greek melas, genitive melanos, 'black, dark', to the chemical suffix -in. It was coined in the early nineteenth century for the dark pigment of tissue. No reliable Latin relative exists, so the Latin list is empty.","cn":"melanin 把希腊 melas（属格 melanos）「黑的、暗的」与化学后缀 -in 结合，于 19 世纪初为组织中的深色色素造出。没有可靠的拉丁同族词，故拉丁条目留空。"},"items":[{"era":"GREEK MELAS","en":"Greek melas, genitive melanos, meant 'black, dark' and supplied the first element of the name.","cn":"希腊 melas（属格 melanos）意为「黑的、暗的」，提供名称的第一个成分。"},{"era":"CHEMICAL -IN","en":"The suffix -in, used for substances such as proteins and pigments, came through French -ine from Latin -ina.","cn":"用于蛋白质与色素等物质名称的后缀 -in，经法语 -ine 来自拉丁 -ina。"},{"era":"COINAGE","en":"The term is generally dated to the 1830s, when chemists isolated the dark pigment of the eye and of tumours.","cn":"这个术语一般认为是 1830 年代所造，当时化学家从眼睛与肿瘤中分离出深色色素。"},{"era":"BIOCHEMISTRY","en":"Twentieth-century work identified melanin as a family of polymers rather than one compound, so the word now covers several related pigments.","cn":"20 世纪的研究确认黑色素是一族聚合物而非单一化合物，因此这个词现在覆盖数种相关色素。"},{"era":"DEEPER ROOT","en":"Greek melas is often linked to a reconstructed Indo-European root for 'dark, black'; the link is a reconstruction, not a recorded form.","cn":"希腊 melas 常被联系到一个重构的印欧词根，意为「暗、黑」；此联系属重构形式，并非有记录的形式。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root and first date): the Indo-European root is reconstructed, the Greek word's earlier history is unclear, and the 1830s coinage date is approximate. The Greek melas layer is secure.","cn":"来源不确定（词根与首见年代）：印欧词根属重构，希腊词更早的历史不清楚，1830 年代的造词年代为约数；希腊 melas 这一层可靠。"}]},"similar":{"note":{"en":"Group one separates the pigment from the cells, bodies and conditions named after it; group two separates the main biological pigments by colour and chemistry.","cn":"第一组把黑色素与以它命名的细胞、结构和病症分开；第二组按颜色与化学性质区分主要生物色素。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"melanocyte","ipa":"/ˈmelənəsaɪt/","tag":"the cell","definition":"The cell that produces melanin; melanin is the substance it makes.","definitionCN":"指产生黑色素的细胞；melanin 是它制造的物。"},{"word":"melanosome","ipa":"/ˈmelənəsəʊm/","tag":"the packet","definition":"The organelle inside a melanocyte that carries melanin; it is a container, not the pigment.","definitionCN":"指黑色素细胞内装载黑色素的细胞器；是容器，不是色素本身。"},{"word":"melanism","ipa":"/ˈmelənɪzəm/","tag":"the condition","definition":"The condition of being unusually dark because of excess melanin; the pigment is the cause, not the condition.","definitionCN":"指因黑色素过多而异常深色的状态；色素是成因，不是状态。"},{"word":"melanoma","ipa":"/ˌmeləˈnəʊmə/","tag":"a tumour","definition":"A cancer of melanin-producing cells; the name is built on melanin but denotes a disease.","definitionCN":"指产生黑色素的细胞所患的癌症；名称由 melanin 构成，但指一种疾病。"}]},{"heading":"NEAR MEANING","entries":[{"word":"pigment","ipa":"/ˈpɪɡmənt/","tag":"general category","definition":"Any colouring substance; melanin is one specific dark pigment among many.","definitionCN":"泛指任何着色物质；melanin 只是众多种深色色素中的一种。"},{"word":"eumelanin","ipa":"/ˌjuːˈmelənɪn/","tag":"brown-black type","definition":"The brown-to-black form of melanin; the word melanin also covers the reddish pheomelanin.","definitionCN":"指黑色素中棕黑的一型；melanin 一词也包含偏红的褐黑色素。"},{"word":"pheomelanin","ipa":"/ˌfiːəˈmelənɪn/","tag":"red-yellow type","definition":"The red-yellow form of melanin found in hair and freckles; it is a subtype, not a synonym.","definitionCN":"指毛发与雀斑中偏红黄的黑色素类型；是亚型，不是同义词。"},{"word":"carotene","ipa":"/ˈkærətiːn/","tag":"different pigment","definition":"An orange plant pigment stored in fat; it is chemically unrelated to melanin.","definitionCN":"指储存在脂肪中的橙色植物色素；与黑色素在化学上无关。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek word for black, the real chemical suffix, and the genuine medical family built on the term.","cn":"正常联想：真实的希腊语「黑」、真实的化学后缀，以及由该术语构成的真实医学词族。"},"normal":[{"en":"melas 'black' + -in: the black substance.","cn":"melas「黑」+ -in：黑色的物质。"},{"en":"The family runs melanin, melanocyte, melanosome, melanoma, melanism.","cn":"同族词包括 melanin、melanocyte、melanosome、melanoma、melanism。"},{"en":"Two subtypes: eumelanin for brown-black, pheomelanin for red-yellow.","cn":"两个亚型：棕黑的真黑色素与红黄的褐黑色素。"},{"en":"It colours skin, hair, iris, feathers, cuticle, fungi and ink.","cn":"它给皮肤、毛发、虹膜、羽毛、表皮、真菌与墨汁上色。"},{"en":"Its other job is shielding DNA from ultraviolet light.","cn":"它的另一项职责是替 DNA 遮挡紫外线。"}],"abstract":[{"en":"Picture a row of tiny ink sacs packed beneath the skin.","cn":"想象皮肤下排着一列小小的墨囊。"},{"en":"Picture an iris whose brown is the density of the dots behind it.","cn":"想象一只褐色的虹膜，那褐色就是背后小点的密度。"},{"en":"Picture a squid writing its escape in one black stroke.","cn":"想象一只鱿鱼用一道黑色笔触写下自己的逃脱。"}]},"examples":[{"en":"Melanin protects the skin by absorbing ultraviolet radiation.","cn":"黑色素通过吸收紫外线保护皮肤。"},{"en":"Albinism results from a failure to produce melanin.","cn":"白化病源于无法产生黑色素。"},{"en":"The fossil feather retained traces of melanin arranged like modern patterns.","cn":"这块化石羽毛保留了黑色素痕迹，排列方式与现代图案相似。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「melan（黑）+ -in（素）」——让皮肤变黑的那种素 → 黑色素","word":"melanin"},"root":"希腊 melas（属格 melanos）「黑的、暗的」+ 化学后缀 -in（经法语 -ine，出自拉丁 -ina）；更早的印欧词根为重构形式。","sensesIntro":{"en":"Eight senses follow one dark polymer: skin and hair, iris, feathers, insect shell, fungi, sun defence, squid ink and a laboratory film.","cn":"八个义项沿同一种深色聚合物展开：皮肤与毛发、虹膜、羽毛、昆虫外壳、真菌、防晒、鱿鱼墨汁与实验室薄膜。"},"semanticMap":{"core":{"en":"CORE IMAGE: rows of dark granules packed under a thin layer of skin.","cn":"核心意象：薄薄一层皮肤下排满深色颗粒。"},"chain":["DARK GRANULES","FILL A CELL","COLOUR THE SURFACE","BLOCK ULTRAVIOLET","APPEAR ACROSS SPECIES","BE MADE IN A LAB"],"branches":[{"senses":"01 · 02","en":"BODY COLOUR: skin and iris shade report melanin density.","cn":"身体颜色：皮肤与虹膜的深浅反映黑色素密度。"},{"senses":"05","en":"FUNGI: moulds and yeasts make their own dark pigment.","cn":"真菌：霉菌与酵母自行制造深色色素。"},{"senses":"06","en":"PROTECTION: the pigment absorbs ultraviolet light before it reaches DNA.","cn":"保护：色素在紫外线触及 DNA 之前将其吸收。"},{"senses":"08","en":"SYNTHESIS: the same polymer can be grown as a film.","cn":"合成：同一种聚合物可以被培育成薄膜。"},{"senses":"03 · 04 · 07","en":"MATERIAL RANGE: feathers, cuticle and ink show the same chemistry in different tissues.","cn":"材料范围：羽毛、表皮与墨汁展示同一化学在不同组织中的表现。"}]},"affixes":{"intro":{"en":"Melanin is a Greek adjective stem plus the chemical suffix -in; later terms add Greek suffixes for cell, body and tumour.","cn":"melanin 是希腊语形容词词干加化学后缀 -in；后续术语再加希腊后缀表示细胞、体和肿瘤。"},"latinIntro":{"en":"No Latin etymon is recoverable for melanin; the -in suffix reached English through French -ine from Latin -ina, but that is a suffix, not a root, so the Latin entry list is empty.","cn":"melanin 无法追溯到拉丁词源；后缀 -in 虽经法语 -ine 来自拉丁 -ina，但那只是后缀而非词根，因此拉丁条目留空。"},"items":[{"word":"melas","structure":"Greek melas, melanos (black)","meaning":"black, dark","meaningCN":"黑的；暗的","example":"Melas is the Greek word behind the name.","exampleCN":"melas 是名称背后的希腊词。"},{"word":"-in","structure":"French -ine, from Latin -ina (chemical substance)","meaning":"substance or compound","meaningCN":"物质或化合物","example":"The suffix marks a named chemical substance.","exampleCN":"这个后缀标记一种被命名的化学物质。"},{"word":"melanin","structure":"melas + -in","meaning":"the dark pigment","meaningCN":"深色色素","example":"Melanin absorbs light across the visible range.","exampleCN":"黑色素吸收可见光范围内的光。"},{"word":"melanocyte","structure":"melanin + Greek kytos (cell)","meaning":"pigment-producing cell","meaningCN":"产生色素的细胞","example":"A melanocyte transfers pigment to skin cells.","exampleCN":"黑色素细胞把色素转交给皮肤细胞。"},{"word":"melanosome","structure":"melanin + Greek soma (body)","meaning":"pigment-carrying organelle","meaningCN":"运载色素的细胞器","example":"Each melanosome is a packet of granules.","exampleCN":"每个黑色素体都是一包颗粒。"},{"word":"melanoma","structure":"melanin + Greek -oma (tumour)","meaning":"cancer of pigment cells","meaningCN":"色素细胞癌","example":"Melanoma begins in pigment cells.","exampleCN":"黑素瘤起于色素细胞。"},{"word":"melanism","structure":"melanin + -ism (condition)","meaning":"abnormally dark colouring","meaningCN":"异常深色；黑化","example":"Melanism is common in some moths.","exampleCN":"黑化在某些蛾类中很常见。"},{"word":"melanistic","structure":"melanism + -istic (adjective)","meaning":"darkened by excess pigment","meaningCN":"因色素过多而变黑的","example":"A melanistic leopard is called a black panther.","exampleCN":"黑化的豹被称为黑豹。"},{"word":"eumelanin","structure":"eu- (good, true) + melanin","meaning":"brown-black melanin","meaningCN":"棕黑色的真黑色素","example":"Eumelanin dominates dark hair.","exampleCN":"真黑色素在深色毛发中占主导。"}],"latinEntries":[]}},{"word":"adaptation mechanism","ipa_uk":"/əˌdæpˈteɪʃn ˈmekənɪzəm/","ipa_us":"/ˌædæpˈteɪʃn ˈmekənɪzəm/","definition_zh":"适应机制；适应装置","definition_en":"a process, structure or behaviour that lets an organism survive and function in a particular environment","core_image":"一只沙漠甲虫背上的小槽把晨雾凝成水珠，水珠顺着沟槽流进嘴里","scene":"纳米布沙漠的清晨，雾气从海上吹来。The beetle's waxy shell is an adaptation mechanism that collects fog into drinking water.","sceneCN":"这里 adaptation mechanism 指「使生物在特定环境中存活的构造或过程」（第 1 个义项：演化形成的适应性构造，能解决环境中的生存难题）；句意为这只甲虫的蜡质背壳是一种把雾气收集成饮用水的适应机制。图中可辨识物件：甲虫背壳、凝结水珠、顺槽流下的水线、海雾。","pos":[{"tag":"n.","zh":"适应机制；适应装置（可数）"}],"collocations":[{"phrase":"evolutionary adaptation mechanism","zh":"演化适应机制"},{"phrase":"physiological adaptation mechanism","zh":"生理适应机制"},{"phrase":"behavioral adaptation mechanism","zh":"行为适应机制"},{"phrase":"a key adaptation mechanism","zh":"一种关键的适应机制"},{"phrase":"adaptation mechanism to heat","zh":"对高温的适应机制"},{"phrase":"study adaptation mechanisms","zh":"研究适应机制"}],"forms":[{"label":"复数","form":"adaptation mechanisms"},{"label":"相关名词（适应）","form":"adaptation"},{"label":"相关动词（适应）","form":"adapt"},{"label":"相关形容词（适应的）","form":"adaptive"},{"label":"相关名词（机制）","form":"mechanism"},{"label":"相关形容词（机械的）","form":"mechanical"}],"derivatives":[{"word":"adaptation","pos":"n.","zh":"适应；改编"},{"word":"adapt","pos":"v.","zh":"适应；改编"},{"word":"adaptive","pos":"adj.","zh":"适应的；适应性强的"},{"word":"mechanism","pos":"n.","zh":"机制；机械装置"},{"word":"mechanistic","pos":"adj.","zh":"机械论的；机制性的"}],"senses":[{"no":"01","title":"Evolved structure that solves a problem","titleCN":"解决生存难题的演化构造","definition":"a body part or process shaped by natural selection that answers a specific environmental challenge","definitionCN":"由自然选择塑造、应对特定环境挑战的身体构造或过程","example":"The beetle's waxy shell is an adaptation mechanism that collects fog into drinking water.","exampleCN":"这只甲虫的蜡质背壳是一种把雾气收集成饮用水的适应机制。","why":"Adaptation names the fit and mechanism names the means; together they point to the device that produces the fit.","whyCN":"adaptation 命名契合本身，mechanism 命名手段；合起来指产生这种契合的装置。"},{"no":"02","title":"Physiological regulation","titleCN":"生理调节机制","definition":"an internal process such as sweating, vasoconstriction or salt excretion that keeps the body working","definitionCN":"出汗、血管收缩或排盐等维持身体运转的内部过程","example":"Sweating is an adaptation mechanism for cooling the body in dry heat.","exampleCN":"出汗是在干热环境中给身体降温的适应机制。","why":"Regulation is internal, so the mechanism is a process rather than a body part.","whyCN":"调节发生在体内，因此机制是过程而非身体部件。"},{"no":"03","title":"Behavioural adjustment","titleCN":"行为上的调整","definition":"a learned or inherited pattern of movement that reduces exposure to danger or heat","definitionCN":"减少危险或高温暴露的学习或遗传性活动模式","example":"Shuttling between sun and shade is a behavioural adaptation mechanism in lizards.","exampleCN":"在阳光与阴影之间往返是蜥蜴的一种行为适应机制。","why":"If the body cannot solve the problem, moving the body can.","whyCN":"如果身体解决不了问题，就让身体移动。"},{"no":"04","title":"Anatomical specialisation","titleCN":"解剖结构上的特化","definition":"a physical feature such as a long beak, webbed foot or thick fur that improves survival","definitionCN":"长喙、蹼足或厚毛等提高存活率的身体特征","example":"The thick fur is an adaptation mechanism to Arctic cold.","exampleCN":"厚毛皮是对北极严寒的一种适应机制。","why":"Anatomy is the permanent version of the same solution.","whyCN":"解剖结构是同一解决方式的永久版本。"},{"no":"05","title":"Genetic or molecular route","titleCN":"基因或分子层面的途径","definition":"a mutation or gene-expression pattern that allows survival under a new pressure","definitionCN":"使生物在新压力下存活的突变或基因表达模式","example":"Antibiotic resistance is a bacterial adaptation mechanism to the drug.","exampleCN":"抗生素耐药性是细菌对药物的一种适应机制。","why":"Selection writes the solution into genes, which is the mechanism at its deepest.","whyCN":"选择把解决方案写进基因，这是最深层面的机制。"},{"no":"06","title":"Engineered adaptive device","titleCN":"工程上的自适应装置","definition":"a designed system that adjusts its own behaviour to changing conditions","definitionCN":"随条件变化而自行调整行为的设计系统","example":"The wing's morphing skin is an adaptation mechanism for gusty air.","exampleCN":"机翼的可变蒙皮是一种应对阵风的适应机制。","why":"The same fit can be designed instead of evolved, so the phrase crosses into engineering.","whyCN":"同样的契合可以被设计而非演化，因此这个短语进入工程领域。"},{"no":"07","title":"Institutional adjustment","titleCN":"制度层面的调整","definition":"a rule or procedure that lets an organisation or society cope with a new condition","definitionCN":"使组织或社会应对新情况的规则或程序","example":"Index-linked benefits act as an adaptation mechanism to inflation.","exampleCN":"指数化福利是一种应对通胀的适应机制。","why":"An organisation facing a new condition behaves like an organism facing one.","whyCN":"组织面对新情况，正如生物面对新情况。"},{"no":"08","title":"Psychological coping route","titleCN":"心理层面的应对途径","definition":"a mental strategy that reduces stress and keeps functioning possible","definitionCN":"减轻压力、维持功能的心理策略","example":"Reframing the loss was her adaptation mechanism during the first year.","exampleCN":"重新解释这次失去，是她第一年里的心理适应机制。","why":"When the threat is internal, the fitted device is a story the mind tells itself.","whyCN":"当威胁来自内部，适配的装置就是心灵对自己讲的故事。"}],"etymology":{"intro":{"en":"Adaptation comes from Latin adaptare 'to fit to', built on aptus 'fit'; mechanism comes from Greek mēkhanē 'device' through Latin machina. The compound is modern technical English.","cn":"adaptation 来自拉丁 adaptare「使适合」，其基础是 aptus「合适的」；mechanism 经拉丁 machina 来自希腊 mēkhanē「装置」。整个复合词是现代技术英语。"},"items":[{"era":"LATIN APTUS","en":"Aptus meant 'fit, suited' and supplied the adjective inside adaptare.","cn":"aptus 意为「合适的、相配的」，提供了 adaptare 中的形容词成分。"},{"era":"LATIN ADAPTARE","en":"Adaptare 'to fit to, adjust' joined ad- 'to' with aptare, a verb from aptus.","cn":"adaptare「使适合、调整」把 ad-「向」与由 aptus 派生的动词 aptare 结合。"},{"era":"GREEK MEKHANE","en":"Greek mēkhanē meant 'machine, device, contrivance' and entered Latin as machina.","cn":"希腊 mēkhanē 意为「机械、装置、巧计」，以 machina 进入拉丁语。"},{"era":"MECHANISM","en":"English mechanism is a seventeenth-century word for the arrangement of parts in a machine, later extended to natural processes.","cn":"英语 mechanism 是 17 世纪表示机械部件配置的词，后来扩展到自然过程。"},{"era":"BIOLOGICAL COMPOUND","en":"Nineteenth-century biology combined adaptation with mechanism to name the means by which organisms fit their habitats.","cn":"19 世纪生物学把 adaptation 与 mechanism 组合，命名生物适应生境的手段。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (Greek root): the origin of mēkhanē is debated and may be Pre-Greek; the first date of the full compound is unrecorded and is only approximate. The Latin adaptare layer is secure.","cn":"来源不确定（希腊词根）：mēkhanē 的来源有争议，可能属前希腊语底层；完整复合词的首见年代无记录，仅为约数；拉丁 adaptare 这一层可靠。"}]},"similar":{"note":{"en":"Group one separates the compound from its two source nouns and their adjectives; group two separates kinds of fit and response.","cn":"第一组把复合词与它的两个来源名词及形容词分开；第二组区分不同类型的契合与反应。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"adaptation","ipa":"/ˌædæpˈteɪʃn/","tag":"the fit itself","definition":"The resulting fit between organism and environment; the mechanism is one means of achieving it.","definitionCN":"指生物与环境之间的契合结果；机制是实现这种契合的一种手段。"},{"word":"adaptive","ipa":"/əˈdæptɪv/","tag":"adjective","definition":"Describes something as improving fitness; it does not name the device.","definitionCN":"描述某物提高适应力；并不命名装置。"},{"word":"adaptability","ipa":"/əˌdæptəˈbɪləti/","tag":"capacity","definition":"The capacity to adapt; a mechanism is one concrete expression of that capacity.","definitionCN":"指适应的能力；机制是这种能力的一种具体表现。"},{"word":"mechanism","ipa":"/ˈmekənɪzəm/","tag":"general means","definition":"Any working arrangement of parts; the compound restricts it to arrangements that serve adaptation.","definitionCN":"泛指任何运作的部件安排；复合词把它限定为服务于适应的安排。"}]},{"heading":"NEAR MEANING","entries":[{"word":"acclimatization","ipa":"/əˌklaɪmətaɪˈzeɪʃn/","tag":"short-term adjustment","definition":"A reversible adjustment to a new climate within one lifetime; an adaptation mechanism may be evolved and permanent.","definitionCN":"指个体一生内可逆的气候调整；适应机制可以是演化而来且永久的。"},{"word":"coping mechanism","ipa":"/ˈkəʊpɪŋ ˈmekənɪzəm/","tag":"psychological only","definition":"A mental strategy for handling stress; it is the human psychological member of the wider class.","definitionCN":"指应对压力的心理策略；是人类心理层面的一个成员。"},{"word":"evolutionary strategy","ipa":"/ˌiːvəˈluːʃnəri ˈstrætədʒi/","tag":"selection-level term","definition":"A pattern favoured by selection over generations; a mechanism is the physical or behavioural device that carries it out.","definitionCN":"指经多代选择而占优的模式；机制是执行该模式的物理或行为装置。"},{"word":"homeostasis","ipa":"/ˌhəʊmiəʊˈsteɪsɪs/","tag":"internal stability","definition":"The maintenance of a steady internal state; it is a goal that adaptation mechanisms serve.","definitionCN":"指维持稳定的内部状态；它是适应机制所服务的目标。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin verb of fitting, the real Greek word for device, and the actual biological collocations.","cn":"正常联想：真实的拉丁「使适合」动词、真实的希腊「装置」词，以及真实的生物学搭配。"},"normal":[{"en":"adapt 'fit to' + mechanism 'device': the device that produces the fit.","cn":"adapt「使适合」+ mechanism「装置」：产生契合的装置。"},{"en":"The family runs adapt, adaptation, adaptive, adaptability, mechanism.","cn":"同族词包括 adapt、adaptation、adaptive、adaptability、mechanism。"},{"en":"Three levels: anatomical, physiological, behavioural.","cn":"三个层次：解剖、生理、行为。"},{"en":"Fixed phrases: physiological adaptation mechanism, behavioral adaptation mechanism.","cn":"固定搭配有 physiological adaptation mechanism、behavioral adaptation mechanism。"},{"en":"The compound is modern: adaptation for the fit, mechanism for the means.","cn":"这个复合词很现代：adaptation 指契合，mechanism 指手段。"}],"abstract":[{"en":"Picture a beetle's back turning fog into a thread of drinking water.","cn":"想象一只甲虫的背把雾变成一线可饮的水。"},{"en":"Picture a lizard shuttling between hot stone and cool shadow like a moving thermostat.","cn":"想象一只蜥蜴在烫石与凉影之间往返，像一个移动的恒温器。"},{"en":"Picture an institution that adjusts its rules the way a wing adjusts its shape.","cn":"想象一个机构调整规则，像机翼调整形状那样。"}]},"examples":[{"en":"Thick fur is an adaptation mechanism for Arctic mammals.","cn":"厚毛皮是北极哺乳动物的一种适应机制。"},{"en":"The plant's deep roots are an adaptation mechanism to drought.","cn":"这种植物的深根是对干旱的一种适应机制。"},{"en":"The engineers copied the seed's attachment as an adaptation mechanism for climbing.","cn":"工程师仿照种子的附着结构，做成一种攀爬适应机制。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「adaptation（适应）+ mechanism（机制）」——让生物适应环境的装置 → 适应机制","word":"adaptation mechanism"},"root":"拉丁 aptus「合适的」→ aptare「使适合」→ adaptare「使适应」→ adaptation；希腊 mēkhanē「装置」→ 拉丁 machina → mechanism；整个短语为现代技术英语复合词。","sensesIntro":{"en":"Eight senses take one fitting device through levels of life: evolved structure, physiology, behaviour, anatomy, genes, engineering, institutions and the mind.","cn":"八个义项把同一种适应装置依次放到不同层面：演化构造、生理、行为、解剖、基因、工程、制度与心理。"},"semanticMap":{"core":{"en":"CORE IMAGE: a beetle's ridged back condensing fog into drops that run to its mouth.","cn":"核心意象：甲虫带沟槽的背把雾凝成水珠，水珠流进它嘴里。"},"chain":["A HARD PROBLEM","A BODY FEATURE","CAPTURE THE RESOURCE","HOLD THE INTERNAL STATE","CHANGE THE BEHAVIOUR","COPY THE DESIGN"],"branches":[{"senses":"01 · 04","en":"STRUCTURE: anatomy solves a physical problem, as the shell collects water.","cn":"结构：解剖解决物理难题，如背壳收集水。"},{"senses":"02 · 05","en":"INTERNAL CONTROL: physiology and genes keep the body working under pressure.","cn":"内部控制：生理与基因让身体在压力下继续运转。"},{"senses":"03","en":"BEHAVIOUR: the animal moves to avoid what its body cannot endure.","cn":"行为：动物通过移动避开身体无法承受的条件。"},{"senses":"06 · 07","en":"DESIGNED FIT: wings and institutions imitate the same logic.","cn":"设计性契合：机翼与制度模仿同一逻辑。"},{"senses":"08","en":"MENTAL FIT: a story reframed until the person can keep functioning.","cn":"心理契合：重新框定叙事，直到人能继续运转。"}]},"affixes":{"intro":{"en":"The phrase combines a Latin-derived noun of fitting with a Greek-derived noun of device; each half has its own suffix history.","cn":"这个短语把拉丁来源的「适合」名词与希腊来源的「装置」名词结合；两半各有自己的后缀历史。"},"latinIntro":{"en":"Latin aptus and adaptare supply adaptation; machina, borrowed from Greek mēkhanē, supplies mechanism.","cn":"拉丁 aptus 与 adaptare 提供 adaptation；借自希腊 mēkhanē 的 machina 提供 mechanism。"},"items":[{"word":"aptus","structure":"Latin aptus, apta, aptum (fit, suited)","meaning":"fit; suited","meaningCN":"合适的；相配的","example":"Aptus is the adjective inside adaptare.","exampleCN":"aptus 是 adaptare 中的形容词成分。"},{"word":"adapt","structure":"Latin adaptare (ad- + aptare)","meaning":"to fit, adjust","meaningCN":"使适合；调整","example":"Species adapt to new pressures.","exampleCN":"物种适应新的压力。"},{"word":"adaptation","structure":"adapt + -ation (result)","meaning":"the state of being fitted","meaningCN":"被适应的状态；适应","example":"The finches show adaptation to seed size.","exampleCN":"这些雀鸟显示出对种子大小的适应。"},{"word":"adaptive","structure":"adapt + -ive (tending to)","meaning":"improving survival","meaningCN":"有适应作用的","example":"Adaptive traits spread under selection.","exampleCN":"适应性特征在选择下扩散。"},{"word":"mechanism","structure":"Greek mēkhanē via Latin machina + -ism","meaning":"working arrangement","meaningCN":"运作机制","example":"The mechanism is visible under a lens.","exampleCN":"这个机制在镜下可见。"},{"word":"mechanical","structure":"mechanism + -al (relating to)","meaning":"of machines","meaningCN":"机械的","example":"Mechanical parts imitate the joint.","exampleCN":"机械部件模仿这个关节。"},{"word":"mechanistic","structure":"mechanism + -istic","meaning":"explained by mechanism","meaningCN":"机械论的","example":"A mechanistic account leaves out purpose.","exampleCN":"机械论的解释略去了目的。"},{"word":"adaptation mechanism","structure":"adaptation + mechanism (compound)","meaning":"the device that produces the fit","meaningCN":"产生契合的装置","example":"The shell is an adaptation mechanism.","exampleCN":"这副背壳是一种适应机制。"},{"word":"adaptation mechanisms","structure":"adaptation mechanism + plural","meaning":"several such devices","meaningCN":"多种此类装置","example":"Deserts select for several adaptation mechanisms.","exampleCN":"沙漠会筛选出多种适应机制。"}],"latinEntries":[{"word":"aptus","structure":"aptus, apta, aptum (adjective)","meaning":"fit, suited","meaningCN":"合适的；相配的"},{"word":"adaptare","structure":"adaptare, adaptavi, adaptatum (verb)","meaning":"to fit to, adjust","meaningCN":"使适合；调整"},{"word":"machina","structure":"machina, machinae (noun, from Greek mēkhanē)","meaning":"device, machine","meaningCN":"装置；机械"}]}},{"word":"defense","ipa_uk":"/dɪˈfens/","ipa_us":"/dɪˈfens/","definition_zh":"防御；保卫；防御工事；辩护；防守","definition_en":"the act of protecting someone or something against attack, or the means used to do so","core_image":"一道石墙横在城门之前，墙上站着持盾的守兵","scene":"山口的城堡没有护城河，只有一道厚墙挡在骑兵必经之路上。The castle's outer wall was built as a first line of defense against cavalry.","sceneCN":"这里 defense 指「抵御进攻的军事防御」（第 1 个义项：以工事或兵力阻止敌方推进）；句意为这座城堡的外墙被建成抵御骑兵的第一道防线。图中可辨识物件：石墙、城门、持盾守兵、远处骑兵。","pos":[{"tag":"n.","zh":"防御；保卫；防御工事；辩护；防守（美式拼写；英式拼作 defence）"}],"collocations":[{"phrase":"national defense","zh":"国防"},{"phrase":"self-defense","zh":"自卫"},{"phrase":"defense mechanism","zh":"防御机制"},{"phrase":"in defense of","zh":"为……辩护"},{"phrase":"defense line","zh":"防线"},{"phrase":"legal defense","zh":"法律辩护"}],"forms":[{"label":"复数","form":"defenses"},{"label":"英式拼写","form":"defence"},{"label":"动词（保卫）","form":"defend"},{"label":"名词（保卫者）","form":"defender"},{"label":"形容词（防御的）","form":"defensive"},{"label":"形容词（可辩护的）","form":"defensible"},{"label":"形容词（无防备的）","form":"defenseless"}],"derivatives":[{"word":"defend","pos":"v.","zh":"保卫；辩护"},{"word":"defensive","pos":"adj.","zh":"防御的；戒备的"},{"word":"defender","pos":"n.","zh":"保卫者；防守队员"},{"word":"defensible","pos":"adj.","zh":"可辩护的；可守住的"},{"word":"defenseless","pos":"adj.","zh":"无防备的"}],"senses":[{"no":"01","title":"Military protection against attack","titleCN":"抵御进攻的军事防御","definition":"the organised resistance of armed forces or fortifications against an enemy","definitionCN":"武装力量或工事对敌方进攻的有组织抵抗","example":"The castle's outer wall was built as a first line of defense against cavalry.","exampleCN":"这座城堡的外墙被建成抵御骑兵的第一道防线。","why":"The Latin verb meant 'to ward off'; the noun names the whole activity of warding off.","whyCN":"这个拉丁动词意为「挡开」；名词命名整个挡开的活动。"},{"no":"02","title":"Legal defence of a case","titleCN":"法律上的辩护","definition":"the argument and evidence presented to protect a person or position in a legal proceeding","definitionCN":"在法律程序中为保护某人或某立场而提出的论证与证据","example":"The lawyer mounted a strong defense of the client's innocence.","exampleCN":"律师为当事人的清白作了有力的辩护。","why":"A trial is an attack on a claim, and answering it is the same act of warding off.","whyCN":"审判是对某项主张的攻击，回应它就是同一种挡开行为。"},{"no":"03","title":"Defensive play in sport","titleCN":"体育中的防守","definition":"the part of a game in which a team tries to stop the opponent from scoring","definitionCN":"比赛中一方力图阻止对手得分的那一部分","example":"Their defense held for the final ten minutes.","exampleCN":"他们的防守在最后十分钟守住了。","why":"Sport reuses the military frame: one side attacks, the other wards off.","whyCN":"体育沿用军事框架：一方进攻，另一方挡开。"},{"no":"04","title":"Biological immune defence","titleCN":"生物的免疫防御","definition":"the body's systems for resisting infection or damage","definitionCN":"身体抵抗感染或损伤的系统","example":"The skin is the body's first defense against infection.","exampleCN":"皮肤是身体抵抗感染的第一道防御。","why":"The body treats infection as an attack, so the military noun fits without metaphor.","whyCN":"身体把感染当作进攻，军事名词无需比喻便适用。"},{"no":"05","title":"Self-defence against physical harm","titleCN":"人身自卫","definition":"action taken to protect oneself from immediate physical danger","definitionCN":"为保护自己免受即时人身危险而采取的行动","example":"She took a self-defense class before moving to the city.","exampleCN":"她在搬到大城市前上了一门自卫课。","why":"Self-defence narrows the object of protection to one's own body.","whyCN":"自卫把保护对象收窄到自己的身体。"},{"no":"06","title":"Verbal justification of an idea","titleCN":"为观点作言语辩护","definition":"a spoken or written argument in support of a person, policy or belief","definitionCN":"为某人、某政策或某信念作支持的口头或书面论证","example":"He wrote a defense of the new tax in the newspaper.","exampleCN":"他在报纸上写了一篇为新税辩护的文章。","why":"A claim can be attacked, and answering it repeats the same warding-off.","whyCN":"主张可以被攻击，回应它就是同一种挡开。"},{"no":"07","title":"A fortification or barrier","titleCN":"防御工事或屏障","definition":"a concrete structure such as a wall, ditch or bunker built to stop an attack","definitionCN":"为阻止进攻而建的墙、壕沟或掩体等实体结构","example":"The old defense crumbled after two centuries of rain.","exampleCN":"这座旧防御工事在两百年雨水侵蚀后坍塌了。","why":"The abstract act hardens into a concrete wall.","whyCN":"抽象行为凝固成具体的墙。"},{"no":"08","title":"Psychological defence","titleCN":"心理防御","definition":"an unconscious mental strategy that protects a person from anxiety or painful insight","definitionCN":"保护个人免于焦虑或痛苦觉察的无意识心理策略","example":"Humor can serve as a defense against bad news.","exampleCN":"幽默可以作为面对坏消息的一种防御。","why":"What cannot be stopped outside can be kept outside the mind.","whyCN":"外部挡不住的东西，可以挡在心灵之外。"}],"etymology":{"intro":{"en":"Defense comes from Latin defensa, the feminine of defensus, past participle of defendere 'to ward off'. The verb joins de- 'away' to fendere 'to strike'. English uses defense in American spelling and defence in British.","cn":"defense 来自拉丁 defensa，即 defendere「挡开」的过去分词 defensus 的阴性形式。该动词由 de-「离开」与 fendere「击打」构成。英语美式拼作 defense，英式拼作 defence。"},"items":[{"era":"LATIN DEFENDERE","en":"Defendere meant 'to ward off, repel, protect' and is the source of defend, defense and defensive.","cn":"defendere 意为「挡开、击退、保护」，是 defend、defense 与 defensive 的来源。"},{"era":"DE- PREFIX","en":"The prefix de- here carries the sense 'away, off', giving the compound the idea of driving something off.","cn":"前缀 de- 在此表示「离开、推开」，使复合词带有「把某物赶开」的意思。"},{"era":"LATIN FENDERE","en":"Fendere 'to strike' is rare outside compounds; it also lies behind offend and fend.","cn":"fendere「击打」很少单独出现，只见于复合词；offend 与 fend 也出自它。"},{"era":"FRENCH DEFENSE","en":"Old French defense carried the noun into English in the fourteenth century, first in the military sense.","cn":"古法语 defense 于 14 世纪把这个名词带入英语，最初为军事义。"},{"era":"SPELLING SPLIT","en":"British English kept defence from the French form, while American English standardized defense after Webster.","cn":"英式英语保留法语形式的 defence，美式英语则在韦伯斯特之后统一为 defense。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root): fendere is poorly attested outside compounds, and its deeper origin is reconstructed rather than recorded; the first English date is approximate. The defendere layer is secure.","cn":"来源不确定（词根）：fendere 在复合词之外少有记录，其更早来源属重构而非有记录的形式；英语首见年代为约数；defendere 这一层可靠。"}]},"similar":{"note":{"en":"Group one separates the noun from its spelling variant and its family members; group two separates kinds of protection by means and by setting.","cn":"第一组区分该名词与拼写变体、同族成员；第二组按手段与场景区分各类保护。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"defence","ipa":"/dɪˈfens/","tag":"British spelling","definition":"The same noun in British spelling; American texts write defense.","definitionCN":"同一名词的英式拼写；美式文本写 defense。"},{"word":"defensive","ipa":"/dɪˈfensɪv/","tag":"adjective","definition":"The adjective describing a posture or attitude; it cannot stand for the noun itself.","definitionCN":"描述姿态或态度的形容词；不能代替名词本身。"},{"word":"defender","ipa":"/dɪˈfendə/","tag":"person","definition":"A person who defends; it is an agent noun, not the act.","definitionCN":"指进行保卫的人；是施动名词，不是行为。"},{"word":"defensible","ipa":"/dɪˈfensəbl/","tag":"adjective of merit","definition":"Able to be justified or held; it judges the case rather than naming the defence.","definitionCN":"指可被辩护或可守住的；评价该主张，而非命名防御。"}]},{"heading":"NEAR MEANING","entries":[{"word":"protection","ipa":"/prəˈtekʃn/","tag":"general safety","definition":"Keeping something safe from any harm; defense usually implies a specific attack to be warded off.","definitionCN":"指使某物免受任何伤害；defense 通常暗示有具体进攻需要挡开。"},{"word":"resistance","ipa":"/rɪˈzɪstəns/","tag":"active pushing back","definition":"The act of opposing a force; defense is the broader plan of which resistance may be one part.","definitionCN":"指对抗某种力量的行为；defense 是更宏大的方案，抵抗可以是其中一环。"},{"word":"guard","ipa":"/ɡɑːd/","tag":"watchful keeping","definition":"A watch kept to prevent surprise; defense can be static or active and need not involve watching.","definitionCN":"指为防止突袭而进行的警戒；defense 可以是静态或主动的，不一定涉及警戒。"},{"word":"justification","ipa":"/ˌdʒʌstɪfɪˈkeɪʃn/","tag":"reason-giving","definition":"The giving of reasons; a legal defense is a structured argument, while justification is the general act.","definitionCN":"指给出理由；法律上的 defense 是有结构的论证，而 justification 是一般行为。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin verb of warding off, the real spelling split, and the collocations that mark each sense.","cn":"正常联想：真实的拉丁「挡开」动词、真实的拼写分歧，以及标记各义项的固定搭配。"},"normal":[{"en":"de- 'away' + fendere 'strike': strike the attack away.","cn":"de-「离开」+ fendere「击打」：把进攻打开。"},{"en":"The family runs defend, defense, defensive, defender, defensible.","cn":"同族词包括 defend、defense、defensive、defender、defensible。"},{"en":"American defense, British defence.","cn":"美式 defense，英式 defence。"},{"en":"Fixed phrases: national defense, self-defense, in defense of.","cn":"固定搭配有 national defense、self-defense、in defense of。"},{"en":"Five arenas: army, court, field, body, mind.","cn":"五个场域：军队、法庭、赛场、身体、心理。"}],"abstract":[{"en":"Picture a wall that exists only because someone once charged at it.","cn":"想象一道墙，它的存在只因为曾有人冲向它。"},{"en":"Picture a lawyer's sentence standing where a shield would stand.","cn":"想象律师的一句话立在盾牌本该立的位置。"},{"en":"Picture a joke raised like a small shield in front of bad news.","cn":"想象一个笑话像小盾牌一样举在坏消息之前。"}]},"examples":[{"en":"The ministry spends more on defense than on education.","cn":"该部在国防上的开支超过教育。"},{"en":"The court heard the defense's final argument.","cn":"法庭听取了辩护方的最后陈述。"},{"en":"A strong defense kept the score level until the last minute.","cn":"稳固的防守把比分保持到最后时刻。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「de（离开）+ fense（打）」——把进攻打开 → 防御；保卫","word":"defense"},"root":"拉丁 de-「离开」+ fendere「击打」→ defendere「挡开」→ 过去分词 defensus → 名词 defensa → 英语 defense；fendere 更早来源为重构形式。","sensesIntro":{"en":"Eight senses share one wall: an army holds a line, a lawyer holds a case, a team holds a score, a body holds off infection, and a mind holds off anxiety.","cn":"八个义项共享同一道墙：军队守住一线，律师守住一案，球队守住比分，身体挡住感染，心理挡住焦虑。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thick wall standing between a gate and the cavalry on the road.","cn":"核心意象：一道厚墙立在城门与路上的骑兵之间。"},"chain":["AN ATTACK ARRIVES","A LINE IS HELD","THE BLOW IS WARDED OFF","THE CLAIM IS ANSWERED","THE BODY RESISTS","THE MIND HOLDS"],"branches":[{"senses":"01 · 07","en":"PHYSICAL WALL: troops and fortifications stop a moving enemy.","cn":"实体墙：兵力与工事挡住推进的敌军。"},{"senses":"02 · 06","en":"VERBAL WALL: argument answers an attack on a claim or policy.","cn":"言语墙：论证回应针对主张或政策的攻击。"},{"senses":"03 · 05","en":"PERSONAL WALL: a player or a person guards a score or a body.","cn":"个人墙：球员守住比分，个人守住身体。"},{"senses":"04","en":"BIOLOGICAL WALL: skin and immunity resist infection.","cn":"生物墙：皮肤与免疫抵抗感染。"},{"senses":"08","en":"MENTAL WALL: humour and other strategies keep anxiety at a distance.","cn":"心理墙：幽默等策略把焦虑挡在远处。"}]},"affixes":{"intro":{"en":"Defense is a Latin participle turned noun; the family adds agent, adjective and negative suffixes to the same defendere stem.","cn":"defense 是由拉丁分词转成的名词；该词族在同一 defendere 词干上加施动、形容词与否定后缀。"},"latinIntro":{"en":"Latin defendere, defensio and fendere supply the stem, the action noun and the rare verb of striking.","cn":"拉丁 defendere、defensio 与 fendere 提供词干、动作名词与罕见的「击打」动词。"},"items":[{"word":"defend","structure":"Latin defendere (de- + fendere)","meaning":"to ward off, protect","meaningCN":"挡开；保护","example":"The unit defended the bridge for a week.","exampleCN":"这支部队守了那座桥一周。"},{"word":"defense","structure":"Latin defensa, from defensus","meaning":"the act or means of warding off","meaningCN":"抵御的行为或手段","example":"The defense held through the night.","exampleCN":"防线整夜守住了。"},{"word":"defensive","structure":"defense + -ive (tending to)","meaning":"protective in posture","meaningCN":"防御姿态的","example":"They took a defensive position on the hill.","exampleCN":"他们在山上占据防御位置。"},{"word":"defender","structure":"defend + -er (agent)","meaning":"one who defends","meaningCN":"保卫者","example":"The defender cleared the ball.","exampleCN":"防守队员把球解围。"},{"word":"defensible","structure":"defense + -ible (able to be)","meaning":"able to be justified or held","meaningCN":"可辩护的；可守住的","example":"The claim is defensible but thin.","exampleCN":"这一主张可辩护，但根基薄弱。"},{"word":"defenseless","structure":"defense + -less (without)","meaning":"without protection","meaningCN":"无防备的","example":"The nestlings are defenseless for weeks.","exampleCN":"雏鸟在数周内毫无防备。"},{"word":"defense mechanism","structure":"defense + mechanism","meaning":"an automatic protective process","meaningCN":"自动的保护过程","example":"Denial is a defense mechanism.","exampleCN":"否认是一种防御机制。"},{"word":"self-defense","structure":"self + defense","meaning":"protection of one's own person","meaningCN":"对自身的人身保护","example":"She acted in self-defense.","exampleCN":"她是出于自卫才行动的。"},{"word":"defense line","structure":"defense + line","meaning":"a line of fortifications","meaningCN":"防线","example":"The defense line ran along the river.","exampleCN":"防线沿河展开。"}],"latinEntries":[{"word":"defendere","structure":"defendere, defendi, defensum (verb, third conjugation)","meaning":"to ward off, repel","meaningCN":"挡开；击退"},{"word":"defensio","structure":"defensio, defensionis (noun)","meaning":"a defence, protection","meaningCN":"防御；保护"},{"word":"fendere","structure":"fendere (verb, rare outside compounds)","meaning":"to strike","meaningCN":"击打"}]}},{"word":"defensive","ipa_uk":"/dɪˈfensɪv/","ipa_us":"/dɪˈfensɪv/","definition_zh":"防御性的；防守的；戒备的；辩护的","definition_en":"intended to protect against attack or criticism rather than to attack first","core_image":"一只刺猬把身体缩成带刺的球，刺全部朝外","scene":"灌木丛里传来脚步声，刺猬立刻缩成一团。When cornered, the hedgehog rolls into a defensive ball of spines.","sceneCN":"这里 defensive 指「以防御姿态保护自己、不主动进攻」（第 1 个义项：采取守势以抵御可能的攻击）；句意为被逼到角落时，刺猬缩成一个带刺的防御球。图中可辨识物件：刺猬、竖起的刺、缩成的球形、逼近的靴子。","pos":[{"tag":"adj.","zh":"防御性的；防守的；戒备的；辩护的"},{"tag":"n.","zh":"防御态势；防守方（少见，多用于 in the defensive）"}],"collocations":[{"phrase":"defensive posture","zh":"防御姿态"},{"phrase":"defensive strategy","zh":"防御策略"},{"phrase":"defensive driving","zh":"防御性驾驶"},{"phrase":"defensive medicine","zh":"防御性医疗"},{"phrase":"become defensive","zh":"变得戒备"},{"phrase":"defensive line","zh":"防守线"}],"forms":[{"label":"原级","form":"defensive"},{"label":"比较级","form":"more defensive"},{"label":"最高级","form":"most defensive"},{"label":"副词","form":"defensively"},{"label":"名词（戒备）","form":"defensiveness"},{"label":"动词（保卫）","form":"defend"},{"label":"名词（防御）","form":"defense"},{"label":"名词（防守者）","form":"defender"}],"derivatives":[{"word":"defend","pos":"v.","zh":"保卫；辩护"},{"word":"defense","pos":"n.","zh":"防御；辩护"},{"word":"defensively","pos":"adv.","zh":"防御地；戒备地"},{"word":"defensiveness","pos":"n.","zh":"戒备心"},{"word":"defender","pos":"n.","zh":"防守者；保卫者"}],"senses":[{"no":"01","title":"Protective rather than attacking","titleCN":"以保护为目的而非进攻","definition":"designed or acting to protect against an attack instead of starting one","definitionCN":"旨在抵御攻击而非主动发起攻击","example":"When cornered, the hedgehog rolls into a defensive ball of spines.","exampleCN":"被逼到角落时，刺猬缩成一个带刺的防御球。","why":"-ive marks a tendency: the word describes a posture oriented toward warding off, not toward striking.","whyCN":"-ive 表示倾向：这个词描述的是朝向挡开而非朝向击打的姿态。"},{"no":"02","title":"Guarding a lead in sport","titleCN":"体育中守住领先","definition":"playing so as to prevent the opponent from scoring, often to protect an existing lead","definitionCN":"以阻止对手得分的方式比赛，常为保住已有领先","example":"The team went defensive after scoring early.","exampleCN":"球队早早得分后转入防守。","why":"A team without the ball is in the same position as an army under attack.","whyCN":"无球的球队与受攻击的军队处境相同。"},{"no":"03","title":"Biological defence structures","titleCN":"生物的防御结构","definition":"body features such as spines, shells or toxins that deter predators","definitionCN":"棘刺、外壳或毒素等阻止捕食者的身体特征","example":"The cactus's defensive spines keep grazing animals away.","exampleCN":"仙人掌的防御性刺让食草动物退开。","why":"Plants cannot flee, so they grow their defence.","whyCN":"植物不能逃跑，于是把防御长在身上。"},{"no":"04","title":"Guarded or touchy in manner","titleCN":"态度戒备或易被触怒","definition":"quick to feel criticised or attacked and slow to open up","definitionCN":"容易觉得被批评或攻击，且不易敞开心扉","example":"He became defensive whenever his methods were questioned.","exampleCN":"只要有人质疑他的方法，他就变得戒备。","why":"Criticism is felt as an attack, so the body's posture appears in speech.","whyCN":"批评被感受为攻击，于是身体的姿态出现在言语里。"},{"no":"05","title":"Serving to justify a claim","titleCN":"用于为某主张辩护","definition":"written or spoken in order to answer criticism of a person or position","definitionCN":"为回应针对某人或某立场的批评而写或说","example":"Her defensive article answered every point in the review.","exampleCN":"她那篇辩护文章回应了评论中的每一个要点。","why":"Words can form the same wall that armour forms.","whyCN":"词句能形成与铠甲相同的墙。"},{"no":"06","title":"Designed for safety in advance","titleCN":"为安全而预先设计的","definition":"used of practices that reduce risk by assuming other people may make mistakes","definitionCN":"形容通过假定他人可能出错来降低风险的做法","example":"Defensive driving assumes the other car may not stop.","exampleCN":"防御性驾驶假定另一辆车可能不会停。","why":"Safety can be planned, and the adjective follows the plan.","whyCN":"安全可以被计划，形容词便跟着计划走。"},{"no":"07","title":"Protecting domestic industry","titleCN":"保护本国产业","definition":"used of economic measures taken to shield local producers from foreign competition","definitionCN":"形容为保护本地生产者免受外国竞争而采取的经济措施","example":"The government raised a defensive tariff on steel.","exampleCN":"政府提高了钢铁的防御性关税。","why":"An industry under competition is defended like a city under siege.","whyCN":"处于竞争中的产业像被围的城市一样受到防守。"},{"no":"08","title":"Extra testing to avoid blame","titleCN":"为避免责任而多做检查","definition":"used of medical practice that orders unnecessary tests chiefly to reduce legal risk","definitionCN":"形容主要为降低法律风险而安排不必要检查的医疗做法","example":"Defensive medicine raises costs without improving outcomes.","exampleCN":"防御性医疗抬高成本却不改善结果。","why":"Legal risk is treated as an attack that tests can ward off.","whyCN":"法律风险被当作可以用检查挡开的攻击。"}],"etymology":{"intro":{"en":"Defensive comes from late Latin defensivus, an adjective built on defendere 'to ward off', and reached English through French défensif in the sixteenth century.","cn":"defensive 来自晚期拉丁 defensivus，是由 defendere「挡开」构成的形容词，16 世纪经法语 défensif 进入英语。"},"items":[{"era":"LATIN DEFENDERE","en":"Defendere 'to ward off, repel' joins de- 'away' to fendere 'to strike'.","cn":"defendere「挡开、击退」由 de-「离开」与 fendere「击打」构成。"},{"era":"LATE LATIN DEFENSIVUS","en":"Defensivus was formed with -ivus, an adjective suffix of tendency or function.","cn":"defensivus 由表示倾向或功能的形容词后缀 -ivus 构成。"},{"era":"FRENCH DEFENSIF","en":"French défensif carried the adjective into English, where defensive appears in the 1500s.","cn":"法语 défensif 把这个形容词带入英语，defensive 于 16 世纪出现。"},{"era":"SPORTING SENSE","en":"The sporting use for a side that prevents scoring is a nineteenth-century extension.","cn":"指阻止对方得分的一方的体育义，是 19 世纪的引申。"},{"era":"PSYCHOLOGICAL SENSE","en":"The sense 'guarded, quick to take offence' developed in ordinary speech, not in medicine.","cn":"「戒备、易被触怒」这一义在日常口语中发展出来，并非医学用语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root): fendere is thinly attested outside compounds and its deeper origin is reconstructed; first dates for the sporting and psychological senses are approximate.","cn":"来源不确定（词根）：fendere 在复合词外记录很少，其更早来源属重构；体育义与心理义的首见年代为约数。"}]},"similar":{"note":{"en":"Group one separates the adjective from the noun and adverb of the same family; group two separates attitudes and arrangements that resist rather than attack.","cn":"第一组区分该形容词与同族的名词、副词；第二组区分抵抗而非进攻的态度与安排。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"defense","ipa":"/dɪˈfens/","tag":"the noun","definition":"The act or system of protection; defensive is the adjective describing such a posture.","definitionCN":"指保护的行为或体系；defensive 是描述这种姿态的形容词。"},{"word":"defensible","ipa":"/dɪˈfensəbl/","tag":"able to be defended","definition":"Able to be justified or held; it judges viability, whereas defensive describes orientation.","definitionCN":"指可被辩护或可守住的；评价可行性，而 defensive 描述取向。"},{"word":"defensively","ipa":"/dɪˈfensɪvli/","tag":"adverb","definition":"In a defensive manner; it modifies an action rather than naming a posture.","definitionCN":"指以防御的方式；修饰动作，而非命名姿态。"},{"word":"defensiveness","ipa":"/dɪˈfensɪvnəs/","tag":"the quality","definition":"The quality of being guarded; the adjective describes a person, the noun names the trait.","definitionCN":"指戒备的性质；形容词描述人，名词命名该特质。"}]},{"heading":"NEAR MEANING","entries":[{"word":"protective","ipa":"/prəˈtektɪv/","tag":"shielding, not opposing","definition":"Designed to keep something safe from harm; defensive often implies an opponent, protective does not.","definitionCN":"指设计来使某物免受伤害；defensive 常暗示有对手，protective 不暗示。"},{"word":"guarded","ipa":"/ˈɡɑːdɪd/","tag":"reserved in manner","definition":"Careful not to reveal feelings; it is a personal manner, while defensive can be military or economic.","definitionCN":"指谨慎不露情绪；是个人态度，而 defensive 可指军事或经济。"},{"word":"reactive","ipa":"/riˈæktɪv/","tag":"responding, not planning","definition":"Acting only after something happens; defensive action can be planned in advance.","definitionCN":"指事情发生后才行动；防御行动可以事先计划。"},{"word":"resistant","ipa":"/rɪˈzɪstənt/","tag":"withstanding force","definition":"Able to withstand a force without yielding; defensive stresses the posture, resistant the capacity.","definitionCN":"指能承受力量而不屈服；defensive 强调姿态，resistant 强调能力。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin adjective suffix, the real family of defend, and the fixed phrases that mark each arena.","cn":"正常联想：真实的拉丁形容词后缀、真实的 defend 词族，以及标记各场域的固定搭配。"},"normal":[{"en":"defend + -ive: tending to ward off.","cn":"defend 加 -ive：倾向于挡开。"},{"en":"The family runs defend, defense, defensive, defender, defensiveness.","cn":"同族词包括 defend、defense、defensive、defender、defensiveness。"},{"en":"Fixed phrases: defensive posture, defensive driving, defensive medicine.","cn":"固定搭配有 defensive posture、defensive driving、defensive medicine。"},{"en":"The word covers armies, teams, animals, feelings and tariffs.","cn":"这个词覆盖军队、球队、动物、情绪与关税。"},{"en":"Note the -sive spelling, not -cive.","cn":"注意拼写是 -sive，不是 -cive。"}],"abstract":[{"en":"Picture a hedgehog becoming a ball of outward-pointing spines.","cn":"想象一只刺猬变成一个向外竖刺的球。"},{"en":"Picture a team that stops trying to score and starts protecting a one-goal lead.","cn":"想象一支球队不再想着进球，而开始守住一球领先。"},{"en":"Picture a person answering a simple question as if it were an accusation.","cn":"想象一个人把简单提问当作指控来回应。"}]},"examples":[{"en":"The army stayed defensive until reinforcements arrived.","cn":"军队一直保持守势，直到援军到达。"},{"en":"She grew defensive when asked about the delay.","cn":"被问及延误时，她变得戒备起来。"},{"en":"The species relies on defensive chemicals rather than speed.","cn":"这个物种依靠防御性化学物质而非速度。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「defense（防御）+ -ive（性质）」——带着防御性质的 → 防御性的；戒备的","word":"defensive"},"root":"拉丁 de-「离开」+ fendere「击打」→ defendere「挡开」→ 晚期拉丁 defensivus → 法语 défensif → 英语 defensive；fendere 更早来源为重构形式。","sensesIntro":{"en":"Eight senses share one turned back: an army, a team, a cactus, a person, a lawyer, a driver, a tariff and a doctor all choose to shield rather than strike.","cn":"八个义项共享同一个转身：军队、球队、仙人掌、个人、律师、司机、关税与医生都选择护住而非出击。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hedgehog rolled into a ball with every spine pointing outward.","cn":"核心意象：刺猬缩成球，每一根刺都朝外。"},"chain":["SENSE A THREAT","TURN INWARD","RAISE A BARRIER","ABSORB THE BLOW","HOLD WHAT YOU HAVE","JUSTIFY THE POSITION"],"branches":[{"senses":"01 · 03","en":"BODY AND ARMY: spines and walls make the attack cost too much.","cn":"身体与军队：棘刺与墙让进攻代价过高。"},{"senses":"02 · 06","en":"CONTEST AND ROAD: holding a lead or assuming another's error.","cn":"比赛与道路：守住领先或假定他人会出错。"},{"senses":"04","en":"FEELING: criticism is met as if it were a physical blow.","cn":"情绪：批评被当作实体打击来迎接。"},{"senses":"05","en":"ARGUMENT: words are arranged as a barrier around a claim.","cn":"论证：词句被排成围绕主张的屏障。"},{"senses":"07 · 08","en":"SYSTEM: tariffs and extra tests buy safety at a cost.","cn":"系统：关税与额外检查以成本换取安全。"}]},"affixes":{"intro":{"en":"Defensive is a Latin participle stem plus the adjective suffix -ive; the same stem yields the verb, the noun and the agent noun.","cn":"defensive 是拉丁分词词干加形容词后缀 -ive；同一词干还产生动词、名词与施动名词。"},"latinIntro":{"en":"Latin defendere, defensio and the late adjective defensivus carry the family into English.","cn":"拉丁 defendere、defensio 与晚期形容词 defensivus 把该词族带入英语。"},"items":[{"word":"defend","structure":"Latin defendere","meaning":"to ward off","meaningCN":"挡开；保卫","example":"They defended the pass for three days.","exampleCN":"他们守了那个隘口三天。"},{"word":"defense","structure":"Latin defensa","meaning":"protection against attack","meaningCN":"抵御攻击","example":"The defense was thin at the left flank.","exampleCN":"左翼的防御很薄弱。"},{"word":"defensive","structure":"defense + -ive (tending to)","meaning":"protective in orientation","meaningCN":"以保护为取向的","example":"The unit took a defensive stance.","exampleCN":"这支部队采取防御姿态。"},{"word":"-ive","structure":"Latin -ivus (tendency or function)","meaning":"tending to act in a certain way","meaningCN":"倾向于以某种方式行动","example":"The suffix turns a verb stem into a tendency.","exampleCN":"这个后缀把动词词干变成一种倾向。"},{"word":"defensively","structure":"defensive + -ly (adverb)","meaning":"in a protective manner","meaningCN":"以防御的方式","example":"He answered defensively.","exampleCN":"他带着戒备回答。"},{"word":"defensiveness","structure":"defensive + -ness (quality)","meaning":"guardedness","meaningCN":"戒备心","example":"Her defensiveness faded with time.","exampleCN":"她的戒备心随时间消退。"},{"word":"defender","structure":"defend + -er (agent)","meaning":"one who protects","meaningCN":"保卫者","example":"The defender blocked the shot.","exampleCN":"防守者封住了射门。"},{"word":"defensible","structure":"defense + -ible (able)","meaning":"able to be justified","meaningCN":"可辩护的","example":"The decision is defensible.","exampleCN":"这个决定站得住脚。"},{"word":"defenseless","structure":"defense + -less (without)","meaning":"unprotected","meaningCN":"无防备的","example":"The burrow left them defenseless.","exampleCN":"这个洞穴让他们毫无防备。"}],"latinEntries":[{"word":"defendere","structure":"defendere, defendi, defensum (verb)","meaning":"to ward off, protect","meaningCN":"挡开；保护"},{"word":"defensivus","structure":"defensivus, defensiva, defensivum (late adjective)","meaning":"serving for defence","meaningCN":"用于防御的"},{"word":"defensio","structure":"defensio, defensionis (noun)","meaning":"a defence","meaningCN":"防御；辩护"}]}},{"word":"defense mechanism","ipa_uk":"/dɪˈfens məˈkænɪzəm/","ipa_us":"/dɪˈfens məˈkænɪzəm/","definition_zh":"防御机制；（心理）防御机制","definition_en":"a process by which an organism protects itself, or in psychology an unconscious strategy that reduces anxiety","core_image":"一层看不见的壳在情绪外面合拢，把刺耳的话挡在外面","scene":"病人听到诊断后先笑了一下，接着谈起天气。Denial is a common defense mechanism that keeps painful news at a distance.","sceneCN":"这里 defense mechanism 指「无意识中用来减轻焦虑的心理防御方式」（第 1 个义项：心理层面自动启动的保护策略，避免痛苦信息直接冲击自己）；句意为否认是一种常见的防御机制，它把痛苦的消息挡在远处。图中可辨识物件：微笑、转向窗外的目光、桌上的诊断单。","pos":[{"tag":"n.","zh":"防御机制（可数；心理、生物与工程语境通用）"}],"collocations":[{"phrase":"psychological defense mechanism","zh":"心理防御机制"},{"phrase":"immune defense mechanism","zh":"免疫防御机制"},{"phrase":"plant defense mechanism","zh":"植物防御机制"},{"phrase":"use a defense mechanism","zh":"使用一种防御机制"},{"phrase":"primitive defense mechanism","zh":"原始防御机制"},{"phrase":"defense mechanisms of the body","zh":"身体的防御机制"}],"forms":[{"label":"复数","form":"defense mechanisms"},{"label":"英式拼写","form":"defence mechanism"},{"label":"相关名词（防御）","form":"defense"},{"label":"相关名词（机制）","form":"mechanism"},{"label":"相关形容词（防御的）","form":"defensive"},{"label":"相关动词（保卫）","form":"defend"}],"derivatives":[{"word":"defense","pos":"n.","zh":"防御；辩护"},{"word":"mechanism","pos":"n.","zh":"机制；装置"},{"word":"defensive","pos":"adj.","zh":"防御的"},{"word":"self-defense","pos":"n.","zh":"自卫"},{"word":"mechanistic","pos":"adj.","zh":"机械论的"}],"senses":[{"no":"01","title":"Unconscious psychological strategy","titleCN":"无意识的心理策略","definition":"an automatic mental manoeuvre that keeps anxiety, guilt or painful information out of awareness","definitionCN":"自动把焦虑、内疚或痛苦信息挡在意识之外的心理操作","example":"Denial is a common defense mechanism that keeps painful news at a distance.","exampleCN":"否认是一种常见的防御机制，它把痛苦的消息挡在远处。","why":"Psychoanalysis borrowed the military image: the mind mounts a defence that the person does not consciously direct.","whyCN":"精神分析借用了军事意象：心灵架起一道本人并未有意识指挥的防线。"},{"no":"02","title":"Immune defence of the body","titleCN":"身体的免疫防御机制","definition":"the coordinated cellular and chemical responses that resist infection","definitionCN":"抵抗感染的细胞与化学协同反应","example":"Fever is a defense mechanism that makes the body hostile to some pathogens.","exampleCN":"发热是一种防御机制，使身体对某些病原体不利。","why":"The immune system is the body's standing army, so its processes take the same name.","whyCN":"免疫系统是身体的常备军，其过程因而取同一名称。"},{"no":"03","title":"Animal structural defence","titleCN":"动物的构造防御","definition":"a body feature such as a shell, spine or venom that deters predators","definitionCN":"外壳、棘刺或毒液等阻止捕食者的身体特征","example":"The turtle's shell is a defense mechanism against crushing bites.","exampleCN":"龟壳是抵御咬碎式攻击的防御机制。","why":"A shell is a mechanism in the plain sense: a working device that stops a bite.","whyCN":"外壳是字面意义的机制：一个阻止咬击的运作装置。"},{"no":"04","title":"Plant chemical defence","titleCN":"植物的化学防御","definition":"a plant's toxins, thorns or resins that reduce herbivory","definitionCN":"植物用以减少被取食的毒素、刺或树脂","example":"Caffeine in coffee leaves acts as a defense mechanism against insects.","exampleCN":"咖啡叶中的咖啡因对昆虫起防御机制的作用。","why":"Plants cannot run, so chemistry becomes their mechanism.","whyCN":"植物不能跑，于是化学成为它们的机制。"},{"no":"05","title":"Behavioural defence","titleCN":"行为防御","definition":"an action such as playing dead, fleeing or grouping that reduces the risk of being eaten","definitionCN":"装死、逃跑或结群等降低被吃风险的动作","example":"Playing dead is a defense mechanism that some beetles use when touched.","exampleCN":"装死是某些甲虫被触碰时使用的防御机制。","why":"When structures are fixed, behaviour is the movable mechanism.","whyCN":"当结构固定，行为就是可移动的机制。"},{"no":"06","title":"Social defence within a group","titleCN":"群体内的社会防御","definition":"a shared norm or ritual that protects a group from conflict or outside pressure","definitionCN":"保护群体免受冲突或外部压力的共同规范或仪式","example":"Ritual courtesy can work as a defense mechanism inside a tense team.","exampleCN":"在紧张的团队里，礼节可以充当一种防御机制。","why":"A group defends itself with shared rules the way a body defends itself with cells.","whyCN":"群体用共同规则自卫，正如身体用细胞自卫。"},{"no":"07","title":"Organisational buffer","titleCN":"组织中的缓冲","definition":"a procedure or layer that shields decision-makers from blame or information overload","definitionCN":"使决策者免受责任或信息过载冲击的程序或层级","example":"Endless approval layers became a defense mechanism against accountability.","exampleCN":"层层审批成了一种逃避问责的防御机制。","why":"An organisation builds procedural armour against blame.","whyCN":"组织用程序铠甲抵御责任。"},{"no":"08","title":"Engineered fail-safe","titleCN":"工程上的失效保护","definition":"a designed system that limits damage when a component fails","definitionCN":"在部件失效时限制损害的设计系统","example":"The pressure valve is a defense mechanism against tank rupture.","exampleCN":"泄压阀是防止罐体破裂的防御机制。","why":"A valve is designed to be the weak point that fails safely.","whyCN":"阀门被设计成安全失效的那个薄弱点。"}],"etymology":{"intro":{"en":"Defense comes from Latin defendere 'to ward off'; mechanism comes from Greek mēkhanē 'device' through Latin machina. The full phrase is a modern technical compound, first biological and then psychoanalytic.","cn":"defense 来自拉丁 defendere「挡开」；mechanism 经拉丁 machina 来自希腊 mēkhanē「装置」。完整短语是现代技术复合词，先用于生物学，后用于精神分析。"},"items":[{"era":"LATIN DEFENDERE","en":"Defendere joins de- 'away' to fendere 'to strike', giving the sense of driving an attack off.","cn":"defendere 由 de-「离开」与 fendere「击打」结合，表示把进攻赶开。"},{"era":"GREEK MEKHANE","en":"Greek mēkhanē meant 'machine, device, contrivance'; Latin borrowed it as machina.","cn":"希腊 mēkhanē 意为「机械、装置、巧计」；拉丁语借作 machina。"},{"era":"NINETEENTH-CENTURY BIOLOGY","en":"Biologists first used defense mechanism for the body's own protective responses to injury and infection.","cn":"生物学家最早用 defense mechanism 指身体对损伤与感染的保护反应。"},{"era":"PSYCHOANALYSIS","en":"Freud's circle made the phrase central to psychology in the 1920s; the German term Abwehrmechanismus was rendered as defense mechanism.","cn":"弗洛伊德学派在 1920 年代使这个短语成为心理学核心术语；德语 Abwehrmechanismus 被译作防御机制。"},{"era":"ENGINEERING","en":"Twentieth-century engineering generalized the phrase to fail-safe devices and protective subsystems.","cn":"20 世纪工程学把这个短语推广到失效保护装置与防护子系统。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and Greek root): the exact first English use of the full phrase is unrecorded, the 1920s psychoanalytic date is approximate, and the origin of mēkhanē may be Pre-Greek. The two Latin layers are secure.","cn":"来源不确定（首见年代与希腊词根）：完整短语的最早英语使用无记录，1920 年代的精神分析年代为约数，mēkhanē 的来源可能属前希腊语底层；两个拉丁层次可靠。"}]},"similar":{"note":{"en":"Group one separates the phrase from its two parts and its spelling variants; group two separates protective strategies by context.","cn":"第一组把该短语与两个组成部分及拼写变体分开；第二组按语境区分各类保护策略。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"defense","ipa":"/dɪˈfens/","tag":"only the goal","definition":"The general act of protection; the compound names a specific working process that achieves it.","definitionCN":"泛指保护行为；复合词命名实现保护的具体运作过程。"},{"word":"mechanism","ipa":"/ˈmekənɪzəm/","tag":"only the means","definition":"Any working arrangement; the compound ties it to protection.","definitionCN":"泛指任何运作安排；复合词把它限定为保护用途。"},{"word":"defence mechanism","ipa":"/dɪˈfens məˈkænɪzəm/","tag":"British spelling","definition":"The same phrase in British spelling; American English writes defense.","definitionCN":"同一短语的英式拼写；美式英语写 defense。"},{"word":"immune defense","ipa":"/ɪˈmjuːn dɪˈfens/","tag":"one subtype","definition":"The body's resistance to infection; it is one kind of defense mechanism, not the general term.","definitionCN":"指身体对感染的抵抗；是防御机制的一种，而非总称。"}]},{"heading":"NEAR MEANING","entries":[{"word":"coping strategy","ipa":"/ˈkəʊpɪŋ ˈstrætədʒi/","tag":"often conscious","definition":"A deliberate way of handling stress; a defense mechanism is typically unconscious.","definitionCN":"指有意识处理压力的办法；防御机制通常是无意识的。"},{"word":"immunity","ipa":"/ɪˈmjuːnəti/","tag":"the state","definition":"The body's resistance to a pathogen; it is the outcome that immune defense mechanisms produce.","definitionCN":"指身体对病原体的抵抗状态；是免疫防御机制产生的结果。"},{"word":"protection","ipa":"/prəˈtekʃn/","tag":"general safety","definition":"The broad state of being kept safe; the compound specifies a mechanism doing the keeping.","definitionCN":"泛指被保护的状态；复合词具体指明起保护作用的机制。"},{"word":"adaptation","ipa":"/ˌædæpˈteɪʃn/","tag":"fit to environment","definition":"A trait that improves survival; a defense mechanism is one kind of adaptation aimed at threats.","definitionCN":"指提高存活率的特征；防御机制是针对威胁的一类适应。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real military metaphor inside psychoanalysis, the real biological usage, and the actual Freudian term.","cn":"正常联想：精神分析中真实的军事隐喻、真实的生物学用法，以及真实的弗洛伊德术语。"},"normal":[{"en":"defense 'warding off' + mechanism 'device': the device that wards off.","cn":"defense「挡开」+ mechanism「装置」：起挡开作用的装置。"},{"en":"The family runs defense, defensive, mechanism, mechanistic.","cn":"同族词包括 defense、defensive、mechanism、mechanistic。"},{"en":"The German term was Abwehrmechanismus, literally a warding-off mechanism.","cn":"德语原词是 Abwehrmechanismus，字面就是「挡开机制」。"},{"en":"One phrase, three homes: mind, body, machine.","cn":"一个短语，三个归属：心灵、身体、机器。"},{"en":"Fixed phrases: psychological defense mechanism, immune defense mechanism.","cn":"固定搭配有 psychological defense mechanism、immune defense mechanism。"}],"abstract":[{"en":"Picture a smile closing like a shutter before bad news lands.","cn":"想象一个微笑像百叶窗在坏消息落下前合上。"},{"en":"Picture the mind posting a guard who asks no questions.","cn":"想象心灵派出一名从不提问的守卫。"},{"en":"Picture a valve that opens only when the pressure would break the tank.","cn":"想象一个只在压力将要撑破罐体时才打开的阀门。"}]},"examples":[{"en":"Projection is a defense mechanism that puts one's own anger onto others.","cn":"投射是一种防御机制，把自身的愤怒放到别人身上。"},{"en":"The immune defense mechanism recognizes the virus within hours.","cn":"免疫防御机制在数小时内识别出病毒。"},{"en":"Thick bark is the tree's defense mechanism against fire.","cn":"厚树皮是树木抵御火灾的防御机制。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「defense（防御）+ mechanism（机制）」——心里自动架起的那道防线 → 防御机制","word":"defense mechanism"},"root":"拉丁 defendere「挡开」+ 希腊 mēkhanē「装置」（经拉丁 machina）→ mechanism；整个短语为现代技术复合词，19 世纪用于生物学，20 世纪用于精神分析。","sensesIntro":{"en":"Eight senses follow one hidden shield: the mind denies, the body fights infection, shells and toxins deter, behaviour escapes, groups ritualize, offices buffer, and valves fail safely.","cn":"八个义项沿同一面隐形盾牌展开：心灵否认，身体抗击感染，外壳与毒素退敌，行为逃避，群体以仪式缓冲，机关以层级缓冲，阀门安全失效。"},"semanticMap":{"core":{"en":"CORE IMAGE: an invisible shell closing around a feeling before a hard sentence lands.","cn":"核心意象：一层看不见的壳在一句硬话落下前裹住情绪。"},"chain":["A THREAT ARRIVES","A SHIELD FORMS","THE BLOW IS ABSORBED","ANXIETY DROPS","THE PERSON FUNCTIONS","THE PATTERN REPEATS"],"branches":[{"senses":"01 · 06","en":"MIND AND GROUP: denial and ritual keep painful material at a distance.","cn":"心灵与群体：否认与仪式把痛苦材料挡在远处。"},{"senses":"02","en":"IMMUNE: cells and fever make the body hostile to invaders.","cn":"免疫：细胞与发热让身体对入侵者不利。"},{"senses":"03 · 04 · 05","en":"ORGANISM: shells, toxins and playing dead are evolved shields.","cn":"生物：外壳、毒素与装死是演化出的盾牌。"},{"senses":"07","en":"ORGANISATION: layers of approval absorb blame.","cn":"组织：层层审批吸收责任。"},{"senses":"08","en":"MACHINE: a valve limits damage when something fails.","cn":"机器：阀门在部件失效时限制损害。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin-derived noun of warding off to a Greek-derived noun of device; both halves are free forms, not a root with affixes.","cn":"这个短语把拉丁来源的「挡开」名词与希腊来源的「装置」名词连接；两半都是自由词形，并非词根加词缀。"},"latinIntro":{"en":"Latin defendere and defensio supply defense; machina, from Greek mēkhanē, supplies mechanism.","cn":"拉丁 defendere 与 defensio 提供 defense；来自希腊 mēkhanē 的 machina 提供 mechanism。"},"items":[{"word":"defense","structure":"Latin defensa < defendere","meaning":"protection against attack","meaningCN":"抵御攻击","example":"The body's defense begins at the skin.","exampleCN":"身体的防御始于皮肤。"},{"word":"mechanism","structure":"Greek mēkhanē via Latin machina + -ism","meaning":"working arrangement","meaningCN":"运作机制","example":"The mechanism can be switched off.","exampleCN":"这个机制可以被关闭。"},{"word":"defensive","structure":"defense + -ive","meaning":"protective in posture","meaningCN":"防御姿态的","example":"A defensive reaction is automatic.","exampleCN":"防御反应是自动的。"},{"word":"mechanistic","structure":"mechanism + -istic","meaning":"explained as a mechanism","meaningCN":"以机制解释的","example":"A mechanistic model treats the mind as a system.","exampleCN":"机制模型把心灵当作一个系统。"},{"word":"defense mechanisms","structure":"defense mechanism + plural -s","meaning":"several such processes","meaningCN":"多种此类过程","example":"People usually rely on several defense mechanisms.","exampleCN":"人通常依赖多种防御机制。"},{"word":"immune defense","structure":"immune + defense","meaning":"resistance to infection","meaningCN":"对感染的抵抗","example":"Immune defense includes fever and antibodies.","exampleCN":"免疫防御包括发热与抗体。"},{"word":"plant defense","structure":"plant + defense","meaning":"protection of plants","meaningCN":"植物的防御","example":"Plant defense often takes the form of chemistry.","exampleCN":"植物防御常以化学形式出现。"},{"word":"behavioral defense","structure":"behavioral + defense","meaning":"protection by action","meaningCN":"以行动保护自己","example":"Behavioral defense includes flight and grouping.","exampleCN":"行为防御包括逃跑与结群。"},{"word":"self-defense","structure":"self + defense","meaning":"protecting one's own person","meaningCN":"保护自身","example":"Self-defense can become a defense mechanism in the mind.","exampleCN":"自卫在心理层面可以变成一种防御机制。"}],"latinEntries":[{"word":"defendere","structure":"defendere, defendi, defensum (verb)","meaning":"to ward off","meaningCN":"挡开"},{"word":"defensio","structure":"defensio, defensionis (noun)","meaning":"a defence","meaningCN":"防御"},{"word":"machina","structure":"machina, machinae (noun, from Greek mēkhanē)","meaning":"device","meaningCN":"装置"}]}},{"word":"protective","ipa_uk":"/prəˈtektɪv/","ipa_us":"/prəˈtektɪv/","definition_zh":"保护的；防护的；保护性的","definition_en":"giving protection from harm, damage or loss","core_image":"一双厚手套把易碎的玻璃杯包住，杯壁不再直接受力","scene":"野外摄影师在镜头前又加了一层薄膜。A thin protective coating keeps the lens from scratching in the field.","sceneCN":"这里 protective 指「起防护作用、使对象免受损伤」（第 1 个义项：在物体表面加一层屏障以抵挡磨损）；句意为野外加的一层薄防护膜使镜片不被刮伤。图中可辨识物件：镜头、透明薄膜、沙砾、相机包。","pos":[{"tag":"adj.","zh":"保护的；防护的；保护性的"}],"collocations":[{"phrase":"protective clothing","zh":"防护服"},{"phrase":"protective coating","zh":"防护涂层"},{"phrase":"protective factor","zh":"保护因素"},{"phrase":"protective order","zh":"保护令"},{"phrase":"protective tariff","zh":"保护性关税"},{"phrase":"protective custody","zh":"保护性拘留"},{"phrase":"over-protective parent","zh":"过度保护孩子的家长"}],"forms":[{"label":"原级","form":"protective"},{"label":"比较级","form":"more protective"},{"label":"最高级","form":"most protective"},{"label":"副词","form":"protectively"},{"label":"名词（保护性）","form":"protectiveness"},{"label":"动词（保护）","form":"protect"},{"label":"名词（保护）","form":"protection"},{"label":"名词（保护者）","form":"protector"}],"derivatives":[{"word":"protect","pos":"v.","zh":"保护；防护"},{"word":"protection","pos":"n.","zh":"保护；防护"},{"word":"protector","pos":"n.","zh":"保护者；防护装置"},{"word":"protectively","pos":"adv.","zh":"以保护的方式"},{"word":"protectionism","pos":"n.","zh":"保护主义"}],"senses":[{"no":"01","title":"Shielding an object from damage","titleCN":"使物件免受损伤","definition":"forming a barrier that keeps an object from being scratched, worn or broken","definitionCN":"形成屏障，使物件不被刮伤、磨损或打破","example":"A thin protective coating keeps the lens from scratching in the field.","exampleCN":"一层薄防护膜使镜片在野外不被刮伤。","why":"-ive marks function: the coating exists in order to protect, whether or not it is currently doing so.","whyCN":"-ive 标记功能：这层膜的存在目的就是保护，不论此刻是否正在受力。"},{"no":"02","title":"Careful in guarding people","titleCN":"对人过度看护","definition":"used of a person who watches over others so closely that it limits their freedom","definitionCN":"形容一个人过度看护他人，以至限制对方自由","example":"His protective manner kept his younger brother from making friends.","exampleCN":"他那过度保护的态度让弟弟交不到朋友。","why":"Care can become a barrier, so the same adjective covers a parent's vigilance.","whyCN":"照料可以变成屏障，因此同一个形容词也覆盖家长的警觉。"},{"no":"03","title":"Legal measure that keeps someone safe","titleCN":"法律上的保护措施","definition":"a court order or legal status that shields a person from harm or harassment","definitionCN":"使某人免受伤害或骚扰的法院命令或法律地位","example":"The court issued a protective order after the threat.","exampleCN":"在威胁发生之后，法院发布了保护令。","why":"A court order is a legal coating around a person.","whyCN":"法院命令是裹在人身上的一层法律涂层。"},{"no":"04","title":"Coloration that hides or warns","titleCN":"起隐藏或警告作用的体色","definition":"used of colours that help an animal avoid detection or advertise a defence","definitionCN":"形容帮助动物避免被发现或通告防御手段的颜色","example":"Protective coloration makes the nestlings nearly invisible.","exampleCN":"保护色让雏鸟几乎看不见。","why":"Colour is the animal's own coating, grown instead of worn.","whyCN":"体色是动物自带的涂层，长出来而非穿上去。"},{"no":"05","title":"Tariff that shields local industry","titleCN":"保护本地产业的关税","definition":"used of a tax on imports intended to raise the price of foreign competitors","definitionCN":"形容旨在提高外国竞争者价格的进口税","example":"The protective tariff kept the mill open for another decade.","exampleCN":"保护性关税让这家工厂又开了十年。","why":"A tariff is a wall placed around a domestic market.","whyCN":"关税是围在国内市场外的一道墙。"},{"no":"06","title":"Custody for a person's safety","titleCN":"为安全而实施的拘留","definition":"used of detention intended to keep a person from harm rather than to punish","definitionCN":"形容旨在使某人免受伤害而非惩罚的拘留","example":"The witness was held in protective custody overnight.","exampleCN":"那名证人被以保护性拘留关押了一夜。","why":"Custody keeps a person inside a legal shield.","whyCN":"拘留把一个人留在法律盾牌之内。"},{"no":"07","title":"Factor that reduces risk","titleCN":"降低风险的保护因素","definition":"used of a condition or habit that lowers the chance of a bad outcome","definitionCN":"形容降低不良结果几率的条件或习惯","example":"Regular sleep is a protective factor for adolescent mental health.","exampleCN":"规律睡眠是青少年心理健康的保护因素。","why":"A habit acts before the harm, which is what a protective layer does.","whyCN":"习惯在伤害之前起作用，这正是防护层的作用。"},{"no":"08","title":"Instinct to guard the young","titleCN":"护幼本能","definition":"used of an animal's instinctive readiness to defend its offspring","definitionCN":"形容动物保护后代的本能反应","example":"The mother bear's protective instinct made the trail impassable.","exampleCN":"母熊的护幼本能让那条小路无法通行。","why":"The instinct puts the parent's body between the danger and the young.","whyCN":"本能把亲本的身体放在危险与幼体之间。"}],"etymology":{"intro":{"en":"Protective comes from protect, from Latin protegere 'to cover in front', built on pro- 'before' and tegere 'to cover'. The adjective protectivus is late Latin; English protective appears in the sixteenth century.","cn":"protective 来自 protect，后者出自拉丁 protegere「在前面遮盖」，由 pro-「在前」与 tegere「覆盖」构成。形容词 protectivus 为晚期拉丁；英语 protective 于 16 世纪出现。"},"items":[{"era":"LATIN TEGERE","en":"Tegere 'to cover' supplies the core image of a roof or shield placed over something.","cn":"tegere「覆盖」提供核心意象：把屋顶或盾牌置于某物之上。"},{"era":"LATIN PROTEGERE","en":"Protegere joined pro- 'in front' to tegere, giving 'to cover in front, to shield'.","cn":"protegere 把 pro-「在前」与 tegere 结合，意为「在前面遮盖、屏蔽」。"},{"era":"PROTECTIO","en":"The noun protectio 'a covering, protection' supplied the action noun behind protect and protection.","cn":"名词 protectio「遮盖、保护」提供了 protect 与 protection 背后的动作名词。"},{"era":"FRENCH PROTECTIF","en":"French protectif carried the adjective into English, where protective is recorded from the 1500s.","cn":"法语 protectif 把这个形容词带入英语，protective 自 16 世纪有记录。"},{"era":"ECONOMIC AND LEGAL SENSES","en":"Protective tariff and protective custody are eighteenth- and nineteenth-century specializations.","cn":"保护性关税与保护性拘留是 18、19 世纪的特化用法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact first English use of protective is unrecorded and the sixteenth-century date is approximate. The Latin protegere and tegere layers are secure.","cn":"来源不确定（首见年代）：protective 的最早英语使用无记录，16 世纪之数为约数；拉丁 protegere 与 tegere 这两层可靠。"}]},"similar":{"note":{"en":"Group one separates the adjective from the verb, noun and adverb of the family; group two separates kinds of shielding by purpose.","cn":"第一组区分该形容词与同族动词、名词、副词；第二组按目的区分各类屏蔽。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"protection","ipa":"/prəˈtekʃn/","tag":"the noun","definition":"The state or act of being protected; protective describes what provides it.","definitionCN":"指被保护的状态或行为；protective 描述提供保护的事物。"},{"word":"protector","ipa":"/prəˈtektə/","tag":"the agent","definition":"A person or device that protects; protective is a quality, not an agent.","definitionCN":"指起保护作用的人或装置；protective 是性质，不是施动者。"},{"word":"protectively","ipa":"/prəˈtektɪvli/","tag":"adverb","definition":"In a protecting manner; it modifies a verb rather than describing a thing.","definitionCN":"指以保护的方式；修饰动词，而非描述事物。"},{"word":"protectiveness","ipa":"/prəˈtektɪvnəs/","tag":"the quality","definition":"The tendency to protect; the adjective describes, the noun names the trait.","definitionCN":"指保护倾向；形容词描述，名词命名特质。"}]},{"heading":"NEAR MEANING","entries":[{"word":"defensive","ipa":"/dɪˈfensɪv/","tag":"against an opponent","definition":"Oriented against an attack; protective need not imply any attacker.","definitionCN":"指针对攻击的取向；protective 不一定暗示攻击者。"},{"word":"preventive","ipa":"/prɪˈventɪv/","tag":"stopping harm early","definition":"Acting before harm occurs; protective describes the barrier, preventive the timing.","definitionCN":"指在伤害发生前行动；protective 描述屏障，preventive 描述时机。"},{"word":"sheltering","ipa":"/ˈʃeltərɪŋ/","tag":"giving refuge","definition":"Providing cover or refuge; protective is broader and includes coatings and laws.","definitionCN":"指提供遮蔽或庇护；protective 更宽，包含涂层与法律。"},{"word":"safeguarding","ipa":"/ˈseɪfɡɑːdɪŋ/","tag":"active keeping safe","definition":"The ongoing activity of keeping someone safe; protective is the quality of the measure.","definitionCN":"指持续使某人安全的行动；protective 是措施的性质。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real pro- plus tegere structure, the real family, and the fixed phrases for clothing, law, trade and health.","cn":"正常联想：真实的 pro- 加 tegere 结构、真实词族，以及衣物、法律、贸易与健康领域的固定搭配。"},"normal":[{"en":"pro- 'in front' + tegere 'cover' + -ive: tending to cover in front.","cn":"pro-「在前」+ tegere「覆盖」+ -ive：倾向于在前面遮盖。"},{"en":"The family runs protect, protection, protective, protector, protectively.","cn":"同族词包括 protect、protection、protective、protector、protectively。"},{"en":"Fixed phrases: protective clothing, protective coating, protective order.","cn":"固定搭配有 protective clothing、protective coating、protective order。"},{"en":"The same adjective serves gloves, laws, tariffs and instincts.","cn":"同一个形容词可用于手套、法律、关税与本能。"},{"en":"Compare protection, the noun, and protector, the agent.","cn":"比较名词 protection 与施动者 protector。"}],"abstract":[{"en":"Picture thick gloves closed around a glass that must not break.","cn":"想象厚手套包住一只绝不能破的玻璃杯。"},{"en":"Picture a transparent film taking every scratch that the lens would have taken.","cn":"想象一层透明膜替镜片承受了每一道刮痕。"},{"en":"Picture a parent standing one step too close to a child's every decision.","cn":"想象一位家长站得离孩子的每个决定都太近。"}]},"examples":[{"en":"Workers wore protective masks around the solvent.","cn":"工人在溶剂旁戴着防护口罩。"},{"en":"The law provides protective measures for witnesses.","cn":"法律为证人提供保护措施。"},{"en":"Protective coloration kept the eggs hidden from above.","cn":"保护色使这些卵从上方看不被发现。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「protect（保护）+ -ive（性质）」——带着保护性质的 → 防护的；保护性的","word":"protective"},"root":"拉丁 pro-「在前」+ tegere「覆盖」→ protegere「在前面遮盖」→ 晚期拉丁 protectivus → 法语 protectif → 英语 protective。","sensesIntro":{"en":"Eight senses share one covering: a film over a lens, a parent over a child, a court over a witness, colour over a nest, a tariff over a mill, custody over a witness, a habit over health, and an instinct over cubs.","cn":"八个义项共享同一层覆盖：薄膜覆镜片、家长护孩子、法院护证人、体色护巢、关税护工厂、拘留护证人、习惯护健康、本能护幼崽。"},"semanticMap":{"core":{"en":"CORE IMAGE: thick gloves closed around a fragile glass, taking the force instead of it.","cn":"核心意象：厚手套包住易碎玻璃，替它承受力量。"},"chain":["A FRAGILE THING","A LAYER GOES OVER IT","THE FORCE IS ABSORBED","THE THING SURVIVES","THE LAYER IS MADE A RULE","THE HABIT IS KEPT"],"branches":[{"senses":"01 · 04","en":"PHYSICAL COVER: coatings and body colour absorb damage or hide the young.","cn":"物理覆盖：涂层与体色吸收损伤或藏住幼体。"},{"senses":"02 · 08","en":"CARE: a person or animal stands between danger and the one guarded.","cn":"看护：人或动物站危险与被护者之间。"},{"senses":"03 · 06","en":"LAW: orders and custody replace the body with legal walls.","cn":"法律：命令与拘留用法律墙壁替代身体。"},{"senses":"05","en":"TRADE: a tariff is a wall around a domestic industry.","cn":"贸易：关税是围住本国产业的一道墙。"},{"senses":"07","en":"HEALTH: a habit lowers risk before harm appears.","cn":"健康：习惯在伤害出现前降低风险。"}]},"affixes":{"intro":{"en":"Protective is a Latin verb stem plus -ive; the Latin family of protegere supplies the verb, the action noun and the agent.","cn":"protective 是拉丁动词词干加 -ive；protegere 的拉丁词族提供动词、动作名词与施动者。"},"latinIntro":{"en":"Latin protegere, protectio and tectus supply the idea of covering something in front.","cn":"拉丁 protegere、protectio 与 tectus 提供「在前面覆盖某物」的意思。"},"items":[{"word":"protect","structure":"Latin protegere (pro- + tegere)","meaning":"to shield","meaningCN":"保护；屏蔽","example":"The wall protects the village from wind.","exampleCN":"这堵墙保护村庄免受风。"},{"word":"protection","structure":"protect + -ion (action or state)","meaning":"the state of being shielded","meaningCN":"被保护的状态","example":"Protection from rain was the first concern.","exampleCN":"首先考虑的是防雨。"},{"word":"protective","structure":"protect + -ive (tending to)","meaning":"serving to protect","meaningCN":"起保护作用的","example":"The coating is protective, not decorative.","exampleCN":"这层涂层是防护性的，不是装饰性的。"},{"word":"protector","structure":"protect + -or (agent)","meaning":"one who protects","meaningCN":"保护者；防护装置","example":"A surge protector guards the equipment.","exampleCN":"浪涌保护器保护设备。"},{"word":"protectively","structure":"protective + -ly (adverb)","meaning":"in a shielding way","meaningCN":"以保护的方式","example":"She stood protectively between them.","exampleCN":"她护在两人中间。"},{"word":"protectiveness","structure":"protective + -ness (quality)","meaning":"the tendency to shield","meaningCN":"保护性；看护倾向","example":"His protectiveness became a burden.","exampleCN":"他的过度保护成了负担。"},{"word":"protective clothing","structure":"protective + clothing","meaning":"garments that shield the body","meaningCN":"保护身体的衣物","example":"Protective clothing is required near acid.","exampleCN":"在酸附近必须穿防护服。"},{"word":"protective tariff","structure":"protective + tariff","meaning":"a tax shielding local producers","meaningCN":"保护本地生产者的税","example":"The protective tariff raised import prices.","exampleCN":"保护性关税抬高了进口价格。"},{"word":"protective custody","structure":"protective + custody","meaning":"detention for safety","meaningCN":"为安全实施的拘留","example":"The child was placed in protective custody.","exampleCN":"那名儿童被置于保护性拘留。"}],"latinEntries":[{"word":"protegere","structure":"protegere, protexi, protectum (verb)","meaning":"to cover in front, shield","meaningCN":"在前面遮盖；保护"},{"word":"protectio","structure":"protectio, protectionis (noun)","meaning":"a covering, protection","meaningCN":"遮盖；保护"},{"word":"tegere","structure":"tegere, texi, tectum (verb)","meaning":"to cover","meaningCN":"覆盖"}]}},{"word":"protection","ipa_uk":"/prəˈtekʃn/","ipa_us":"/prəˈtekʃn/","definition_zh":"保护；防护；保护措施；保护区","definition_en":"the state or act of being kept safe from harm, or a measure that keeps something safe","core_image":"一把撑开的伞把雨挡在头顶之外，伞骨下是一小片干的区域","scene":"举报人担心遭到报复，于是向监察机构求助。The new law offers protection for whistle-blowers who report waste.","sceneCN":"这里 protection 指「法律提供的保护措施」（第 2 个义项：由制度或规则提供的安全保障，使某人免受伤害或报复）；句意为新法律为举报浪费行为的吹哨人提供保护。图中可辨识物件：法律文本、举报信封、监察机构门牌、撑开的伞。","pos":[{"tag":"n.","zh":"保护；防护；保护措施；保护区（可数或不可数）"}],"collocations":[{"phrase":"environmental protection","zh":"环境保护"},{"phrase":"data protection","zh":"数据保护"},{"phrase":"under the protection of","zh":"在……的保护下"},{"phrase":"legal protection","zh":"法律保护"},{"phrase":"social protection","zh":"社会保护"},{"phrase":"protection order","zh":"保护令"},{"phrase":"wildlife protection","zh":"野生动物保护"}],"forms":[{"label":"复数（指具体措施）","form":"protections"},{"label":"动词（保护）","form":"protect"},{"label":"形容词（保护的）","form":"protective"},{"label":"名词（保护者）","form":"protector"},{"label":"名词（保护主义）","form":"protectionism"},{"label":"名词（保护主义者）","form":"protectionist"}],"derivatives":[{"word":"protect","pos":"v.","zh":"保护；防护"},{"word":"protective","pos":"adj.","zh":"保护的；防护的"},{"word":"protector","pos":"n.","zh":"保护者；防护装置"},{"word":"protectionism","pos":"n.","zh":"保护主义"},{"word":"protectionist","pos":"n./adj.","zh":"保护主义者；保护主义的"}],"senses":[{"no":"01","title":"Physical shielding from harm","titleCN":"免受伤害的物理防护","definition":"the state of being covered or guarded so that harm cannot reach","definitionCN":"被覆盖或看守、使伤害无法到达的状态","example":"The umbrella offered little protection against the wind.","exampleCN":"那把伞对风几乎起不到防护作用。","why":"The Latin noun named a covering; the modern sense keeps that image of something placed between a person and a threat.","whyCN":"这个拉丁名词命名一层遮盖；现代义保留「把某物置于人与威胁之间」的意象。"},{"no":"02","title":"Legal or institutional safeguard","titleCN":"法律或制度上的保障","definition":"a rule, law or arrangement that keeps a person or group safe from harm or retaliation","definitionCN":"使个人或群体免受伤害或报复的规则、法律或安排","example":"The new law offers protection for whistle-blowers who report waste.","exampleCN":"新法律为举报浪费行为的吹哨人提供保护。","why":"The law takes the place of the umbrella and stands between a person and a threat.","whyCN":"法律替代雨伞，立在人与其威胁之间。"},{"no":"03","title":"Environmental conservation","titleCN":"环境保护","definition":"measures taken to keep ecosystems, species or resources from damage","definitionCN":"为防止生态系统、物种或资源受损而采取的措施","example":"The reserve was created for the protection of nesting turtles.","exampleCN":"这个保护区是为保护筑巢海龟而设立的。","why":"Nature cannot hold an umbrella, so a reserve is built around it.","whyCN":"自然无法自己撑伞，于是围绕它建立保护区。"},{"no":"04","title":"Social security against hardship","titleCN":"抵御困境的社会保障","definition":"public arrangements that shield people from poverty, illness or unemployment","definitionCN":"使人们免受贫困、疾病或失业的公共安排","example":"Social protection kept the family afloat after the layoff.","exampleCN":"失业后，社会保障让这个家庭撑了下来。","why":"Hardship is a threat, so public arrangements are built as a cover.","whyCN":"困境是一种威胁，于是公共安排被搭成遮盖。"},{"no":"05","title":"Safeguarding of personal data","titleCN":"个人数据保护","definition":"rules and technical measures that keep personal information from misuse","definitionCN":"防止个人信息被滥用的规则与技术措施","example":"Data protection requires consent before sharing.","exampleCN":"数据保护要求在共享前取得同意。","why":"Information can be harmed, so rules form a layer around it.","whyCN":"信息会受损，于是规则在它周围形成一层。"},{"no":"06","title":"Trade protection for domestic producers","titleCN":"对本国生产者的贸易保护","definition":"tariffs or quotas that shield local industries from foreign competition","definitionCN":"使本地产业免受外国竞争的关税或配额","example":"The minister argued for temporary protection of the steel sector.","exampleCN":"部长主张对钢铁行业实行临时保护。","why":"A market under foreign competition is shielded like a town under attack.","whyCN":"面对外国竞争的市场像受攻击的城镇一样被遮蔽。"},{"no":"07","title":"A protected area","titleCN":"保护区","definition":"a place legally set aside where wildlife or a site is shielded from development","definitionCN":"依法划出、使野生动物或遗址免受开发的地方","example":"The reef is a marine protection where anchoring is banned.","exampleCN":"这片珊瑚礁是一处禁止下锚的海洋保护区。","why":"When protection is fixed to a place, the abstract noun becomes a mapped area.","whyCN":"当保护固定在某个地点，抽象名词就变成地图上的区域。"},{"no":"08","title":"Gear worn against injury","titleCN":"防受伤的护具","definition":"equipment worn to absorb impact or prevent injury in sport or work","definitionCN":"在运动或工作中吸收冲击、防止受伤的装备","example":"Knee protection is compulsory on the course.","exampleCN":"这条赛道上必须佩戴护膝。","why":"Padding is the umbrella worn on the body.","whyCN":"护具是穿在身上的伞。"}],"etymology":{"intro":{"en":"Protection comes from Latin protectio 'a covering, defence', from protegere 'to cover in front', through French protection. The word is recorded in English from the fourteenth century.","cn":"protection 经法语 protection 来自拉丁 protectio「遮盖、防御」，后者出自 protegere「在前面遮盖」。英语自 14 世纪有记录。"},"items":[{"era":"LATIN TEGERE","en":"Tegere 'to cover' gives the family its core image of a roof or shield over something.","cn":"tegere「覆盖」给该词族提供核心意象：某物上方的屋顶或盾牌。"},{"era":"LATIN PROTEGERE","en":"Protegere 'to cover in front, shield' added pro- 'before' to tegere.","cn":"protegere「在前面遮盖、屏蔽」在 tegere 前加上 pro-「在前」。"},{"era":"PROTECTIO","en":"Protectio named the covering or the act of shielding; its stem supplies protection and protector.","cn":"protectio 命名遮盖或屏蔽行为；其词干提供 protection 与 protector。"},{"era":"FRENCH PROTECTION","en":"Old French protection passed into English in the 1300s, first in legal and military contexts.","cn":"古法语 protection 于 14 世纪进入英语，最初用于法律与军事语境。"},{"era":"MODERN EXTENSIONS","en":"Environmental, data and social protection are nineteenth- and twentieth-century extensions of the legal sense.","cn":"环境、数据与社会保护是 19、20 世纪从法律义延伸出来的用法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest English use is not precisely dated and the fourteenth-century figure is approximate. The Latin protegere and protectio layers are secure.","cn":"来源不确定（首见年代）：最早的英语使用没有精确年代，14 世纪之数为约数；拉丁 protegere 与 protectio 这两层可靠。"}]},"similar":{"note":{"en":"Group one separates the noun from the verb, adjective and agent of the family; group two separates forms of safeguarding by scope.","cn":"第一组区分该名词与同族动词、形容词、施动者；第二组按范围区分各类保障。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"protective","ipa":"/prəˈtektɪv/","tag":"adjective","definition":"The adjective describing a guarding quality; protection is the thing provided.","definitionCN":"描述防护性质的形容词；protection 是被提供的东西。"},{"word":"protector","ipa":"/prəˈtektə/","tag":"agent","definition":"One who or that which protects; protection is the state or measure, not the agent.","definitionCN":"指保护者或防护装置；protection 是状态或措施，不是施动者。"},{"word":"protect","ipa":"/prəˈtekt/","tag":"verb","definition":"The action of shielding; protection is the resulting state or the arrangement.","definitionCN":"指屏蔽动作；protection 是结果状态或安排。"},{"word":"protections","ipa":"/prəˈtekʃnz/","tag":"countable plural","definition":"Specific safeguards, as in legal protections; the singular is usually the general state.","definitionCN":"指具体保障措施，如法律保护条款；单数多为一般状态。"}]},{"heading":"NEAR MEANING","entries":[{"word":"defense","ipa":"/dɪˈfens/","tag":"against attack","definition":"Resistance to a specific attack; protection is broader and includes prevention and care.","definitionCN":"指对具体攻击的抵抗；protection 更宽，包含预防与照料。"},{"word":"safety","ipa":"/ˈseɪfti/","tag":"the condition","definition":"The condition of being safe; protection is the measure that produces it.","definitionCN":"指安全的状态；protection 是产生该状态的措施。"},{"word":"conservation","ipa":"/ˌkɒnsəˈveɪʃn/","tag":"careful keeping","definition":"Careful management to prevent loss of natural or cultural resources; it is one form of protection.","definitionCN":"指防止自然或文化资源流失的谨慎管理；是保护的一种形式。"},{"word":"custody","ipa":"/ˈkʌstədi/","tag":"guarding by an authority","definition":"Keeping a person in official care; protection can be legal without detention.","definitionCN":"指由官方照管某人；protection 可以是法律性的而不涉及拘留。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin noun of covering, the real family, and the collocations of law, environment and data.","cn":"正常联想：真实的拉丁「遮盖」名词、真实词族，以及法律、环境与数据领域的固定搭配。"},"normal":[{"en":"protegere 'cover in front' + -ion: the state of being covered.","cn":"protegere「在前面遮盖」+ -ion：被遮盖的状态。"},{"en":"The family runs protect, protection, protective, protector, protectionism.","cn":"同族词包括 protect、protection、protective、protector、protectionism。"},{"en":"Fixed phrases: environmental protection, data protection, legal protection.","cn":"固定搭配有 environmental protection、data protection、legal protection。"},{"en":"The noun is countable when it means specific measures.","cn":"指具体措施时，这个名词可数。"},{"en":"One umbrella covers rain, law, reefs and knees.","cn":"一把伞同时覆盖雨、法律、珊瑚礁与膝盖。"}],"abstract":[{"en":"Picture an umbrella holding a dry circle open in a downpour.","cn":"想象一把伞在暴雨中撑开一小片干燥的圆。"},{"en":"Picture a statute standing between a witness and a threat.","cn":"想象一条法规立在证人与威胁之间。"},{"en":"Picture a reef marked off by buoys so that no anchor can fall.","cn":"想象一片珊瑚礁被浮标圈起，任何锚都落不下去。"}]},"examples":[{"en":"The helmet gives reliable protection against a fall.","cn":"头盔能在摔倒时提供可靠的保护。"},{"en":"The park was declared a protection for the last wild herd.","cn":"这座公园被宣布为最后一群野生兽群的保护区。"},{"en":"Consumer protection laws require clear labelling.","cn":"消费者保护法要求标示清楚。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「protect（保护）+ -ion（状态）」——被护住的状态 → 保护；防护","word":"protection"},"root":"拉丁 pro-「在前」+ tegere「覆盖」→ protegere「在前面遮盖」→ protectio「遮盖、防御」→ 法语 protection → 英语 protection。","sensesIntro":{"en":"Eight senses share one umbrella: rain over a head, law over a witness, rules over a reef, welfare over a family, consent over data, a tariff over a mill, a reserve over turtles, and padding over a knee.","cn":"八个义项共享同一把伞：替头顶挡雨、替证人挡法外报复、替珊瑚礁挡开发、替家庭挡困境、替数据挡滥用、替工厂挡竞争、替海龟挡侵扰、替膝盖挡冲击。"},"semanticMap":{"core":{"en":"CORE IMAGE: an open umbrella holding a small dry circle inside a downpour.","cn":"核心意象：一把撑开的伞在暴雨中守住一小片干燥的圆。"},"chain":["A THREAT ABOVE","A COVER IS RAISED","THE HARM IS DIVERTED","A SMALL SAFE SPACE","A RULE REPLACES THE COVER","THE SPACE IS SET ASIDE"],"branches":[{"senses":"01 · 08","en":"PHYSICAL COVER: umbrellas, helmets and padding take the blow.","cn":"物理遮盖：伞、头盔与护具承受冲击。"},{"senses":"02 · 04 · 05","en":"INSTITUTIONAL COVER: law, welfare and consent rules stand in for the umbrella.","cn":"制度遮盖：法律、福利与同意规则替代雨伞。"},{"senses":"03","en":"CONSERVATION: measures that keep ecosystems from damage.","cn":"保护措施：防止生态系统受损的行动。"},{"senses":"06","en":"TRADE COVER: tariffs shield producers from competition.","cn":"贸易遮盖：关税使生产者免受竞争。"},{"senses":"07","en":"PLACE: protection becomes a bounded area on a map.","cn":"地点：保护变成地图上一块有边界的地方。"}]},"affixes":{"intro":{"en":"Protection is a Latin action noun in -io built on the protegere stem; English adds further suffixes for agent, quality and doctrine.","cn":"protection 是由 protegere 词干加 -io 构成的拉丁动作名词；英语再加后缀表示施动者、性质与主义。"},"latinIntro":{"en":"Latin protegere, protectio and tectus carry the covering image into English.","cn":"拉丁 protegere、protectio 与 tectus 把「遮盖」意象带入英语。"},"items":[{"word":"protect","structure":"Latin protegere","meaning":"to shield","meaningCN":"保护；屏蔽","example":"The levee protects the town.","exampleCN":"堤坝保护着这座镇。"},{"word":"protection","structure":"Latin protectio (action noun)","meaning":"the state of being shielded","meaningCN":"受保护的状态","example":"Protection from the sun matters at noon.","exampleCN":"正午防晒很重要。"},{"word":"protective","structure":"protect + -ive","meaning":"serving to shield","meaningCN":"起防护作用的","example":"Protective gloves are worn here.","exampleCN":"这里要戴防护手套。"},{"word":"protector","structure":"protect + -or (agent)","meaning":"one who shields","meaningCN":"保护者","example":"The treaty made the state a protector.","exampleCN":"条约使该国成为保护者。"},{"word":"protectionism","structure":"protection + -ism (doctrine)","meaning":"a policy of shielding domestic industry","meaningCN":"保护本国产业的政策","example":"Protectionism raises prices at home.","exampleCN":"保护主义抬高国内价格。"},{"word":"protectionist","structure":"protectionism + -ist (adherent)","meaning":"one who favours such a policy","meaningCN":"支持保护主义的人","example":"The protectionist blocked the treaty.","exampleCN":"那名保护主义者阻挠了条约。"},{"word":"environmental protection","structure":"environmental + protection","meaning":"keeping ecosystems from harm","meaningCN":"使生态系统免受损害","example":"Environmental protection is written into the charter.","exampleCN":"环境保护被写进章程。"},{"word":"data protection","structure":"data + protection","meaning":"keeping personal data safe","meaningCN":"保护个人数据安全","example":"Data protection rules limit sharing.","exampleCN":"数据保护规则限制共享。"},{"word":"protection order","structure":"protection + order","meaning":"a legal order to keep someone safe","meaningCN":"保护某人安全的法院命令","example":"A protection order was served that night.","exampleCN":"当晚送达了一份保护令。"}],"latinEntries":[{"word":"protegere","structure":"protegere, protexi, protectum (verb)","meaning":"to cover in front","meaningCN":"在前面遮盖"},{"word":"protectio","structure":"protectio, protectionis (noun)","meaning":"a covering, protection","meaningCN":"遮盖；保护"},{"word":"tegere","structure":"tegere, texi, tectum (verb)","meaning":"to cover","meaningCN":"覆盖"}]}},{"word":"thermoregulation","ipa_uk":"/ˌθɜːməʊrɪˈɡjʊleɪʃn/","ipa_us":"/ˌθɜːrmoʊˌreɡjəˈleɪʃn/","definition_zh":"体温调节；温度调节","definition_en":"the processes by which an organism or system keeps its temperature within a workable range","core_image":"一只蜥蜴在正午把身体抬离滚烫的岩石，四肢轮流抬起散热","scene":"正午的沙漠岩石烫得无法久留。Desert lizards rely on behavioral thermoregulation to avoid overheating at noon.","sceneCN":"这里 thermoregulation 指「生物把自身体温维持在可承受范围内的过程」（第 1 个义项：通过行为或生理方式调节体温，避免过热或过冷）；句意为沙漠蜥蜴依靠行为性体温调节来避免正午过热。图中可辨识物件：烫热的岩石、抬起的四肢、阴影、正午太阳。","pos":[{"tag":"n.","zh":"体温调节；温度调节（不可数）"}],"collocations":[{"phrase":"behavioral thermoregulation","zh":"行为性体温调节"},{"phrase":"physiological thermoregulation","zh":"生理性体温调节"},{"phrase":"thermoregulation in reptiles","zh":"爬行动物的体温调节"},{"phrase":"disrupt thermoregulation","zh":"扰乱体温调节"},{"phrase":"thermoregulation mechanism","zh":"体温调节机制"},{"phrase":"impaired thermoregulation","zh":"体温调节受损"}],"forms":[{"label":"动词（调节体温）","form":"thermoregulate"},{"label":"形容词（体温调节的）","form":"thermoregulatory"},{"label":"名词（调节者）","form":"thermoregulator"},{"label":"相关形容词（恒温的）","form":"endothermic"},{"label":"相关形容词（变温的）","form":"ectothermic"},{"label":"相关名词（热感受器）","form":"thermoreceptor"}],"derivatives":[{"word":"thermoregulate","pos":"v.","zh":"调节体温"},{"word":"thermoregulatory","pos":"adj.","zh":"体温调节的"},{"word":"thermoregulator","pos":"n.","zh":"体温调节者；恒温器"},{"word":"endotherm","pos":"n.","zh":"恒温动物"},{"word":"ectotherm","pos":"n.","zh":"变温动物"}],"senses":[{"no":"01","title":"Behavioural temperature control","titleCN":"行为性体温调节","definition":"the use of movement, posture or shelter to keep body temperature within limits","definitionCN":"通过移动、姿态或寻找遮蔽把体温维持在限度内","example":"Desert lizards rely on behavioral thermoregulation to avoid overheating at noon.","exampleCN":"沙漠蜥蜴依靠行为性体温调节来避免正午过热。","why":"Thermo- names heat and regulation names keeping within limits; behaviour is one of the ways an animal does the keeping.","whyCN":"thermo- 命名热，regulation 命名维持在限度内；行为是动物实现这种维持的方式之一。"},{"no":"02","title":"Physiological temperature control","titleCN":"生理性体温调节","definition":"internal adjustments such as sweating, shivering or changing blood flow to the skin","definitionCN":"出汗、发抖或改变皮肤血流等内部调节","example":"Sweating is the body's main physiological thermoregulation in dry heat.","exampleCN":"在干热环境中，出汗是身体主要的生理性体温调节方式。","why":"If behaviour is not enough, the body adjusts its own chemistry and blood flow.","whyCN":"如果行为不够，身体就调整自身的化学与血流。"},{"no":"03","title":"Endothermic regulation","titleCN":"恒温动物的体温调节","definition":"the maintenance of a stable body temperature by internal heat production, as in mammals and birds","definitionCN":"通过内部产热维持稳定体温，如哺乳动物与鸟类","example":"Endothermic thermoregulation lets a bird stay active through a cold night.","exampleCN":"恒温调节让一只鸟在寒夜中保持活动。","why":"Making heat internally is one strategy for keeping the core steady.","whyCN":"在体内产热是维持核心温度的一种策略。"},{"no":"04","title":"Ectothermic regulation","titleCN":"变温动物的体温调节","definition":"the control of body temperature by gaining heat from the environment, as in reptiles and insects","definitionCN":"通过从环境获得热量来控制体温，如爬行动物与昆虫","example":"Ectothermic thermoregulation depends on basking and retreating to shade.","exampleCN":"变温调节依赖晒太阳与退回阴影。","why":"Taking heat from outside is the other strategy for the same goal.","whyCN":"从外部取热是达成同一目标的另一策略。"},{"no":"05","title":"Plant temperature control","titleCN":"植物的温度调节","definition":"the use of transpiration, leaf angle or heat-shock proteins to avoid damage from heat or cold","definitionCN":"通过蒸腾、叶角或热激蛋白避免高温或低温损伤","example":"Transpiration provides a form of thermoregulation in broad leaves.","exampleCN":"蒸腾为阔叶提供一种温度调节形式。","why":"Plants cannot move, so they cool through water loss and leaf angle.","whyCN":"植物不能移动，于是通过失水与叶角降温。"},{"no":"06","title":"Insect thermoregulation","titleCN":"昆虫的体温调节","definition":"the use of shivering, wing position or social clustering to control thoracic temperature","definitionCN":"通过发抖、调整翅位或群体聚集控制胸部温度","example":"Bees use wing vibration as thermoregulation inside the hive.","exampleCN":"蜜蜂在蜂巢内用翅膀振动进行体温调节。","why":"An insect can warm its flight muscles without warming the whole body.","whyCN":"昆虫可以只暖飞行肌而不暖全身。"},{"no":"07","title":"Aquatic thermal regulation","titleCN":"水生生物的体温调节","definition":"the use of countercurrent blood flow or behavioural depth change to conserve or lose heat in water","definitionCN":"通过逆流血流或改变活动深度在水中保温或散热","example":"Countercurrent thermoregulation keeps a dolphin's core warm in cold water.","exampleCN":"逆流调节让海豚在冷水中保持核心体温。","why":"Water carries heat away fast, so a countercurrent exchanger is needed to keep it.","whyCN":"水带走热量很快，因此需要逆流交换器来保住热量。"},{"no":"08","title":"Engineering temperature control","titleCN":"工程上的温度控制","definition":"the design of radiators, insulation or active cooling to keep a machine or spacecraft within limits","definitionCN":"设计散热器、隔热层或主动冷却，使机器或航天器保持在限度内","example":"Spacecraft thermoregulation relies on radiators and reflective coatings.","exampleCN":"航天器的温度调节依靠散热器与反射涂层。","why":"A machine cannot sweat, so radiators do the same job by design.","whyCN":"机器不会出汗，于是散热器以设计完成同样的工作。"}],"etymology":{"intro":{"en":"Thermoregulation joins Greek thermē 'heat' (thermos 'hot') to Latin regulare 'to regulate', from regula 'rule'. The compound is twentieth-century scientific English.","cn":"thermoregulation 把希腊 thermē「热」（thermos「热的」）与拉丁 regulare「调节」结合，后者出自 regula「规则」。这个复合词是 20 世纪的科学英语。"},"items":[{"era":"GREEK THERME","en":"Greek thermē meant 'heat', and thermos meant 'hot'; the combining form thermo- entered science through these words.","cn":"希腊 thermē 意为「热」，thermos 意为「热的」；组合形式 thermo- 通过这些词进入科学。"},{"era":"LATIN REGULA","en":"Latin regula 'rule, straight edge' gave regulare 'to direct, regulate'.","cn":"拉丁 regula「规则、直尺」衍生出 regulare「指导、调节」。"},{"era":"LATIN REGULARE","en":"Regulare supplied regulation and regulator; the suffix -ation names the process.","cn":"regulare 提供 regulation 与 regulator；后缀 -ation 命名过程。"},{"era":"SCIENTIFIC COMPOUND","en":"Thermoregulation was coined in the twentieth century when physiology needed a single term for all heat-control processes.","cn":"20 世纪生理学需要一个统称所有控热过程的术语时，造出了 thermoregulation。"},{"era":"ENGINEERING TRANSFER","en":"The same compound was later applied to machines and spacecraft, where heat must be managed by design.","cn":"同一复合词后来被用于机器与航天器，那里必须通过设计来管理热量。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (Greek root): the origin of Greek thermē is debated and often reconstructed from a root for warmth; the exact first use of the compound is unrecorded. The Latin regula layer is secure.","cn":"来源不确定（希腊词根）：希腊 thermē 的来源有争议，常被重构为表示温暖的词根；该复合词的最早使用无记录；拉丁 regula 这一层可靠。"}]},"similar":{"note":{"en":"Group one separates the compound from its verb, adjective and related body terms; group two separates heat-management ideas by mechanism or setting.","cn":"第一组把复合词与它的动词、形容词及相关身体术语分开；第二组按机制或场景区分热量管理概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"thermoregulate","ipa":"/ˌθɜːməʊˈreɡjʊleɪt/","tag":"the verb","definition":"To carry out thermoregulation; the noun names the whole process.","definitionCN":"指执行体温调节；名词命名整个过程。"},{"word":"thermoregulatory","ipa":"/ˌθɜːməʊˈreɡjʊlətəri/","tag":"adjective","definition":"Relating to thermoregulation, as in thermoregulatory behaviour; it describes rather than names.","definitionCN":"表示与体温调节有关的，如调节行为；描述而非命名。"},{"word":"thermoregulator","ipa":"/ˌθɜːməʊˈreɡjʊleɪtə/","tag":"agent","definition":"Something that regulates temperature, such as a device; it is the agent, not the process.","definitionCN":"指调节温度的事物，如装置；是施动者，不是过程。"},{"word":"thermoreceptor","ipa":"/ˌθɜːməʊrɪˈseptə/","tag":"sensor","definition":"A nerve ending that senses temperature; it is one component used in thermoregulation.","definitionCN":"指感受温度的神经末梢；是体温调节所使用的一个部件。"}]},{"heading":"NEAR MEANING","entries":[{"word":"homeostasis","ipa":"/ˌhəʊmiəʊˈsteɪsɪs/","tag":"whole-body stability","definition":"The maintenance of steady internal conditions generally; thermoregulation is its temperature branch.","definitionCN":"泛指维持稳定的内部环境；体温调节是其中管温度的一支。"},{"word":"thermal regulation","ipa":"/ˈθɜːml ˌreɡjʊˈleɪʃn/","tag":"engineering wording","definition":"The engineering phrase for controlling temperature in devices; thermoregulation is usual for organisms.","definitionCN":"工程中控制装置温度的说法；生物语境通常用 thermoregulation。"},{"word":"acclimatization","ipa":"/əˌklaɪmətaɪˈzeɪʃn/","tag":"adjustment over time","definition":"A gradual adjustment to a new climate; thermoregulation is the ongoing control, not the adjustment.","definitionCN":"指对新气候的逐渐适应；thermoregulation 是持续控制，不是适应过程。"},{"word":"heat balance","ipa":"/hiːt ˈbæləns/","tag":"the accounting","definition":"The balance of heat gained and lost; thermoregulation is the active process that maintains that balance.","definitionCN":"指获得与散失热量的平衡；thermoregulation 是维持该平衡的主动过程。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek word for heat, the real Latin verb of regulating, and the real behavioural and physiological split.","cn":"正常联想：真实的希腊语「热」、真实的拉丁「调节」动词，以及真实的行为与生理二分。"},"normal":[{"en":"thermo- 'heat' + regulation 'keeping within a rule': keeping heat within limits.","cn":"thermo-「热」+ regulation「按规则维持」：把热量维持在限度内。"},{"en":"The family runs thermoregulate, thermoregulatory, thermoregulator, endotherm, ectotherm.","cn":"同族词包括 thermoregulate、thermoregulatory、thermoregulator、endotherm、ectotherm。"},{"en":"Two big routes: behaviour and physiology.","cn":"两条主要路径：行为与生理。"},{"en":"Fixed phrases: behavioral thermoregulation, impaired thermoregulation.","cn":"固定搭配有 behavioral thermoregulation、impaired thermoregulation。"},{"en":"Two body plans: endothermic mammals, ectothermic reptiles.","cn":"两种体质：恒温的哺乳动物、变温的爬行动物。"}],"abstract":[{"en":"Picture a lizard lifting one foot at a time off rock that is too hot to hold.","cn":"想象一只蜥蜴把四只脚轮流抬离烫得不能久放的岩石。"},{"en":"Picture a bee vibrating its wings to warm the whole hive.","cn":"想象一只蜜蜂振动翅膀，把整个蜂巢暖起来。"},{"en":"Picture a spacecraft turning its radiators to the dark like a lizard turning its back to the sun.","cn":"想象航天器把散热器转向黑暗，像蜥蜴把背转向太阳。"}]},"examples":[{"en":"Thermoregulation in birds combines feathers, panting and behaviour.","cn":"鸟类的体温调节结合了羽毛、喘气与行为。"},{"en":"The drug impairs thermoregulation, so heatstroke risk rises.","cn":"这种药会损害体温调节，因此中暑风险上升。"},{"en":"Engineers studied the termite mound's thermoregulation for passive cooling.","cn":"工程师研究白蚁丘的温度调节，以用于被动降温。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「thermo（热）+ regulation（调节）」——把体温调在合适范围 → 体温调节","word":"thermoregulation"},"root":"希腊 thermē「热」（thermos「热的」）+ 拉丁 regula「规则」→ regulare「调节」→ regulation；整个复合词为 20 世纪科学英语。","sensesIntro":{"en":"Eight senses take one heat budget through life: behaviour, physiology, warm-bloodedness, cold-bloodedness, plants, insects, water and machines.","cn":"八个义项把同一份热量收支放遍生命与机器：行为、生理、恒温、变温、植物、昆虫、水生与航天器。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lizard lifting its feet one by one off rock too hot to hold.","cn":"核心意象：蜥蜴把脚一只只抬离烫得不能久放的岩石。"},"chain":["HEAT ARRIVES","BODY READS IT","HEAT IS GAINED OR LOST","CORE STAYS STEADY","BEHAVIOUR HELPS","DESIGN COPIES IT"],"branches":[{"senses":"01 · 04","en":"BEHAVIOUR: moving to sun or shade does the work for an ectotherm.","cn":"行为：对变温动物而言，往返阳光与阴影就完成了工作。"},{"senses":"02 · 03","en":"PHYSIOLOGY: sweating, shivering and internal heat production hold the core.","cn":"生理：出汗、发抖与内部产热守住核心体温。"},{"senses":"05 · 06","en":"PLANTS AND INSECTS: transpiration, wing vibration and clustering extend the same logic.","cn":"植物与昆虫：蒸腾、振翅与聚集延伸同一逻辑。"},{"senses":"07","en":"WATER: countercurrent flow conserves heat in a cold medium.","cn":"水中：逆流交换在寒冷介质中保住热量。"},{"senses":"08","en":"MACHINE: radiators and coatings do by design what bodies do by physiology.","cn":"机器：散热器与涂层以设计完成身体用生理完成的事。"}]},"affixes":{"intro":{"en":"Thermoregulation combines a Greek combining form for heat with a Latin-derived noun of rule-keeping; the two halves are free forms, not a single root.","cn":"thermoregulation 把希腊语表示热的组合形式与拉丁来源的「守规则」名词结合；两半都是自由词形，并非单一词根。"},"latinIntro":{"en":"Latin regula and regulare supply regulation; Greek thermē supplies the heat element, so the Latin entries cover only the second half.","cn":"拉丁 regula 与 regulare 提供 regulation；希腊 thermē 提供热的成分，因此拉丁条目只覆盖后半部分。"},"items":[{"word":"thermo-","structure":"Greek thermē (heat), thermos (hot)","meaning":"heat","meaningCN":"热","example":"Thermometer and thermos both begin with this element.","exampleCN":"thermometer 与 thermos 都以这个成分开头。"},{"word":"regulation","structure":"Latin regulare + -ation","meaning":"the act of keeping within limits","meaningCN":"使维持在限度内的行为","example":"Regulation keeps the system inside its range.","exampleCN":"调节使系统保持在范围内。"},{"word":"regula","structure":"Latin regula (rule, straight edge)","meaning":"rule; standard","meaningCN":"规则；标准","example":"Regula is the noun behind regulate.","exampleCN":"regula 是 regulate 背后的名词。"},{"word":"thermoregulate","structure":"thermo- + regulate","meaning":"to control body heat","meaningCN":"调节体温","example":"The lizard thermoregulates by shuttling.","exampleCN":"蜥蜴通过往返移动调节体温。"},{"word":"thermoregulatory","structure":"thermoregulate + -ory (adjective)","meaning":"relating to heat control","meaningCN":"与体温调节有关的","example":"Thermoregulatory behaviour changes at dusk.","exampleCN":"体温调节行为在黄昏时改变。"},{"word":"thermoregulator","structure":"thermoregulate + -or (agent)","meaning":"one that regulates heat","meaningCN":"调节温度者；恒温器","example":"The device is a thermoregulator for the tank.","exampleCN":"这个装置是罐体的温度调节器。"},{"word":"endotherm","structure":"endo- (within) + Greek thermē","meaning":"an animal generating its own heat","meaningCN":"自行产热的动物","example":"Endotherms keep a steady core temperature.","exampleCN":"恒温动物保持稳定的核心体温。"},{"word":"ectotherm","structure":"ecto- (outside) + Greek thermē","meaning":"an animal relying on environmental heat","meaningCN":"依赖环境热量的动物","example":"Ectotherms bask to raise their temperature.","exampleCN":"变温动物晒太阳以提高体温。"},{"word":"thermoreceptor","structure":"thermo- + receptor","meaning":"a sensor of temperature","meaningCN":"温度感受器","example":"Thermoreceptors report skin temperature.","exampleCN":"温度感受器报告皮肤温度。"}],"latinEntries":[{"word":"regula","structure":"regula, regulae (noun, first declension)","meaning":"rule, standard","meaningCN":"规则；标准"},{"word":"regulare","structure":"regulare, regulavi, regulatum (verb)","meaning":"to regulate, direct","meaningCN":"调节；指导"},{"word":"regulatio","structure":"regulatio, regulationis (noun)","meaning":"a regulating","meaningCN":"调节；调控"}]}}]);
